window.__HSK_CHAPTER_DATA__['chapter_03'] = [{"meanings_summary": {"en": "stable; steady; settled; to stabilize", "es": "estable; firme; estabilizar; consolidar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When grain harvests (禾) are securely stored under a sheltered roof (宀), life becomes prosperous and stable (稳定).", "composite_memory_hook_es": "Cuando la cosecha (禾) descansa segura bajo el techo del hogar (宀), la vida se vuelve próspera y estable (稳定).", "cultural_and_cognitive_roots": "Ancient agrarian society equated stability with grain in the bin (稳) and family beneath a roof (定). Social equilibrium is perceived as an inner anchor against life's turbulence.", "tone_sandhi_and_pitch_modulation": "Dipping 3rd tone followed by a decisive falling 4th tone: wěn dìng (214-51). 'wěn' dips smoothly down to 21 before transitioning crisply to 51."}, "semantic_boundary_contrasts": {"core_nuance": "稳定 denotes equilibrium, reliability, and resistance to disruptive fluctuations across emotions, structures, or social systems.", "contrasts": [{"id": "1", "compared_word": "稳定 vs. 固定", "pinyin": "gùdìng", "analysis": "稳定 describes a steady state of equilibrium free from turbulence (稳定情绪, 稳定物价), whereas 固定 focuses on physical immobilization or predetermined unchangeability (固定座位, 固定时间)."}, {"id": "2", "compared_word": "稳定 vs. 平静", "pinyin": "píngjìng", "analysis": "稳定 emphasizes endurance, reliability, and security of an overall system, while 平静 describes peaceful sensory stillness or tranquil waters and moods (风浪平静, 心情平静)."}, {"id": "3", "compared_word": "稳定 vs. 沉着", "pinyin": "chénzhuó", "analysis": "稳定 reflects overall equilibrium and steadfastness, whereas 沉着 specifically characterizes a person's poised, unflappable calmness in the face of crisis."}]}, "traps_and_cognates": {"look_alikes": [{"character": "隐", "pinyin": "yǐn", "meaning_en": "hidden; conceal", "distinction_note": "Has 阝 (mound/wall) radical on the left instead of 禾 (grain)"}, {"character": "锭", "pinyin": "dìng", "meaning_en": "ingot; spindle", "distinction_note": "Has 钅 (metal) radical on the left instead of 禾"}, {"character": "绽", "pinyin": "zhàn", "meaning_en": "burst open; split", "distinction_note": "Has 纟 (silk) radical on the left with 定 on the right"}, {"character": "淀", "pinyin": "diàn", "meaning_en": "shallow water; precipitate", "distinction_note": "Has 氵 (water) radical on the left with 定 on the right"}], "etymological_cognates": [{"character": "安定", "pinyin": "ān dìng", "gloss_en": "stable; quiet; settled"}, {"character": "确定", "pinyin": "què dìng", "gloss_en": "definite; certain; confirm"}, {"character": "固定", "pinyin": "gù dìng", "gloss_en": "fixed; regular; fasten"}, {"character": "稳重", "pinyin": "wěn zhòng", "gloss_en": "prudent; staid; composed"}]}, "id": "1", "hanzi": "稳定", "pinyin": "wěn dìng", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "steady and not easily shaken or changing; firm", "definition_es": "estable; seguro; que no cambia con facilidad", "example_phrase": "情绪稳定 (emotionally stable)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to stabilize; to steady; to maintain equilibrium", "definition_es": "estabilizar; pacificar; consolidar", "example_phrase": "稳定物价 (stabilize commodity prices)"}], "example_sentences": [{"id": "#1", "hanzi": "面对突如其来的航海风暴，船长保持着冷静与稳定的心态，带领全船人员化险为夷。", "pinyin": "Miànduì tūrúqílái de hánghǎi fēngbào, chuánzhǎng bǎochí zhe lěngjìng yǔ wěndìng de xīntài, dàilǐng quán chuán rényuán huà xiǎn wéi yí.", "en": "Facing the sudden maritime storm, the captain maintained a calm and steady mindset, leading the entire crew out of danger.", "es": "Frente a la tormenta marítima repentina, el capitán mantuvo una mentalidad tranquila y estable, guiando a la tripulación fuera del peligro."}, {"id": "#2", "hanzi": "为了确保经济平稳过渡，政府出台了多项宏观调控措施以稳定就业和金融市场。", "pinyin": "Wèile quèbǎo jīngjì píngwěn guòdù, zhèngfǔ chūtái le duō xiàng hóngguān tiáokòng cuòshī yǐ wěndìng jiùyè hé jīnróng shìchǎng.", "en": "To ensure a smooth economic transition, the government introduced several macro-control measures to stabilize employment and financial markets.", "es": "Para garantizar una transición económica fluida, el gobierno implementó diversas medidas de control macroeconómico para estabilizar el empleo y los mercados financieros."}], "collocations": [{"hanzi": "情绪稳定", "en": "emotionally stable"}, {"hanzi": "稳定发展", "en": "stable development"}, {"hanzi": "保持稳定", "en": "maintain stability"}, {"hanzi": "稳定人心", "en": "reassure the public; settle people's minds"}, {"hanzi": "政治稳定", "en": "political stability"}, {"hanzi": "稳定增长", "en": "steady growth"}], "idioms": [{"hanzi": "稳扎稳打", "pinyin": "wěn zhā wěn dǎ", "meaning_en": "go forward steadily and strike sure blows; make steady progress"}, {"hanzi": "安居乐业", "pinyin": "ān jū lè yè", "meaning_en": "live and work in peace and contentment"}, {"hanzi": "平稳过渡", "pinyin": "píng wěn guò dù", "meaning_en": "smooth and steady transition"}, {"hanzi": "立足稳固", "pinyin": "lì zú wěn gù", "meaning_en": "gain a firm foothold; stand on solid ground"}], "character_decomposition": [{"character": "稳", "pinyin": "wěn", "meaning_en": "stable; steady; secure", "meaning_es": "estable; firme; seguro", "radical": "禾", "radical_meaning_en": "grain / standing cereal", "meaning_component": "禾 (grain harvest providing security)", "sound_component": "隐 (yǐn / 急 / 爫+工 phonetic/semantic association)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound. Grain (禾) in abundance allows the populace to remain settled and calm.", "visual_mnemonic_story_en": "A granary full of harvested grain (禾) brings steady security and calm to the family.", "visual_mnemonic_story_es": "Un granero colmado de cereal cosechado (禾) aporta tranquilidad y firmeza a la familia.", "tone_mnemonic_anchor": "214", "cangjie": "HDNSP", "traditional": "穩"}, {"character": "定", "pinyin": "dìng", "meaning_en": "settle; decide; fixed", "meaning_es": "fijar; decidir; calmado", "radical": "宀", "radical_meaning_en": "roof / dwelling", "meaning_component": "宀 (roof sheltering a home)", "sound_component": "正 (zhèng / 足 foot resting peacefully)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Ideogrammic compound: a foot (疋/正) resting firmly under a roof (宀), signifying tranquility and permanence.", "visual_mnemonic_story_en": "Under the protective roof of home (宀), your feet rest still and settled (疋).", "visual_mnemonic_story_es": "Bajo el techo protector de la casa (宀), los pies reposan quietos y seguros (疋).", "tone_mnemonic_anchor": "51", "cangjie": "JMO", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "很多人渴望一份稳定的工作与波澜不惊的岁月，但真正的稳定并非来自外界环境的庇护，而是源自内心深处从容应对变故的笃定。在生活的惊涛骇浪中，拥有自我调节的能力，便能在任何风暴里找到稳固的港湾。", "pinyin": "Hěnduō rén kěwàng yí fèn wěndìng de gōngzuò yǔ bōlánbùjīng de suìyuè, dàn zhēnzhèng de wěndìng bìng fēi láizì wàijiè huánjìng de bìhù, ér shì yuánzì nèixīn shēnchù cóngròng yìngduì biàngù de dǔdìng. Zài shēnghuó de jīngtāohàilàng zhōng, yōngyǒu zìwǒ tiáojié de nénglì, biàn néng zài rènhé fēngbào lǐ zhǎodào wěngù de gǎngwān.", "en": "Many people yearn for a stable career and tranquil years, yet genuine stability stems not from sheltered circumstance, but from inner certainty in facing sudden change. Amid life's surging waves, possessing emotional self-regulation allows one to anchor safely in any storm.", "es": "Mucha gente anhela un trabajo estable y años apacibles, pero la verdadera estabilidad no proviene de un entorno protegido, sino de la convicción interior al afrontar los cambios. En medio de los oleajes de la vida, regularse a uno mismo permite hallar un puerto seguro en cualquier tormenta."}, {"id": "#2", "hanzi": "宏观经济学分析指出，维持物价与就业的长期稳定，是保障社会民生和增强投资信心的关键基石。面对全球贸易格局的深刻变动，唯有通过科技创新和结构性改革，才能在全球竞争中构建更加稳健、更有韧性的产业发展体系。", "pinyin": "Hóngguān jīngjìxué fēnxī zhǐchū, wéichí wùjià yǔ jiùyè de chángqī wěndìng, shì bǎozhàng shèhuì mínshēng hé zēngqiáng tóuzī xìnxīn de guānjiàn jīshí. Miànduì quánqiú màoyì gégjú de shēnkè biàndòng, wéiyǒu tōngguò kējì chuàngxīn hé jiégòuxìng gǎigé, cáinéng zài quánqiú jìngzhēng zhōng gòujiàn gèngjiā wěnjiàn, gèng yǒu rènxìng de chǎnyè fāzhǎn tǐxì.", "en": "Macroeconomic analysis indicates that maintaining long-term stability in commodity prices and employment forms the bedrock of social welfare and investor confidence. Facing deep transformations in global trade, only technological innovation and structural reforms can build a resilient industrial system.", "es": "El análisis macroeconómico señala que mantener la estabilidad prolongada de precios y empleo es la base del bienestar y la confianza inversora. Ante las profundas transformaciones del comercio global, la innovación técnica y las reformas estructurales permiten forjar un tejido industrial más sólido y resiliente."}]}, {"meanings_summary": {"en": "sailboat; sailing ship; yacht", "es": "velero; barco de vela; yate"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Hoisting sturdy canvas sails (帆) onto a wooden ship (船) transforms it into an adventurous ocean-going sailboat (帆船).", "composite_memory_hook_es": "Izar fuertes velas de lona (帆) en un barco de madera (船) lo convierte en un intrépido velero (帆船).", "cultural_and_cognitive_roots": "In Chinese maritime history, the invention of battened junk sails enabled long-distance navigation. The sailboat metaphorically embodies self-determination, freedom, and brave pioneering spirit.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a rising 2nd tone: fān chuán (55-35). Both syllables require distinct, ringing open vocal resonance without rushing."}, "semantic_boundary_contrasts": {"core_nuance": "帆船 specifies a water vessel relying fundamentally on wind-driven sails, representing lifestyle sailing and expedition voyages.", "contrasts": [{"id": "1", "compared_word": "帆船 vs. 轮船", "pinyin": "lúnchuán", "analysis": "帆船 uses wind and sails for propulsion and represents sport or leisure, whereas 轮船 is a motorized steam or motor ship used for industrial passenger and cargo transport."}, {"id": "2", "compared_word": "帆船 vs. 快艇", "pinyin": "kuàitǐng", "analysis": "帆船 emphasizes natural wind navigation and patience on long routes, while 快艇 is a high-speed engine-powered motorboat designed for rapid cruising or water patrol."}, {"id": "3", "compared_word": "帆船 vs. 军舰", "pinyin": "jūnjiàn", "analysis": "帆船 is a civilian vessel used in recreation, athletics, and oceanic exploration, whereas 军舰 designates naval combat warships."}]}, "traps_and_cognates": {"look_alikes": [{"character": "佩", "pinyin": "pèi", "meaning_en": "admire; wear at waist", "distinction_note": "Has 亻 (person) radical on the left instead of 巾 (cloth)"}, {"character": "凡", "pinyin": "fán", "meaning_en": "ordinary; mundane", "distinction_note": "The root character without the 巾 (cloth) radical"}, {"character": "般", "pinyin": "bān", "meaning_en": "sort; manner; kind", "distinction_note": "Has 舟 on the left and 殳 on the right instead of 㕣"}, {"character": "舵", "pinyin": "duò", "meaning_en": "rudder; helm", "distinction_note": "Has 舟 on the left and 它 on the right"}], "etymological_cognates": [{"character": "帆布", "pinyin": "fān bù", "gloss_en": "canvas; sailcloth"}, {"character": "扬帆", "pinyin": "yáng fān", "gloss_en": "hoist sails; set sail"}, {"character": "船舶", "pinyin": "chuán bó", "gloss_en": "shipping; vessels; boats"}, {"character": "船只", "pinyin": "chuán zhī", "gloss_en": "ships; vessels (collective)"}]}, "id": "2", "hanzi": "帆船", "pinyin": "fān chuán", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a boat or ship propelled mainly or partly by sails", "definition_es": "embarcación propulsada principalmente o en parte por velas", "example_phrase": "驾驶帆船 (steer a sailboat)"}], "example_sentences": [{"id": "#1", "hanzi": "他毅然辞去了稳定的工作，买下一艘二手帆船，开启了长达数年的环球航行。", "pinyin": "Tā yìrán cíqù le wěndìng de gōngzuò, mǎi xià yì sōu èrshǒu fānchuán, kāiqǐ le chángdá shù nián de huánqiú hángxíng.", "en": "Resigning resolutely from his stable job, he bought a second-hand sailboat and embarked on a multi-year global voyage.", "es": "Renunciando con determinación a su trabajo estable, compró un velero de segunda mano e inició una vuelta al mundo de varios años."}, {"id": "#2", "hanzi": "国际帆船拉力赛吸引了全球数十支顶尖船队，在汹涌澎湃的海浪中展开激烈的技术角逐。", "pinyin": "Guójì fānchuán lālìsài xīyǐn le quánqiú shùshí zhī dǐngjiān chuánduì, zài xiōngyǒng péngpài de hǎilàng zhōng zhǎnkāi jīliè de jìshù juézhú.", "en": "The international sailing regatta attracted dozens of top teams from across the globe to compete fiercely in surging waves.", "es": "La regata internacional de veleros atrajo a decenas de equipos de élite mundial para librar una reñida competencia náutica entre olas impetuosas."}], "collocations": [{"hanzi": "一艘帆船", "en": "a sailing boat"}, {"hanzi": "驾驶帆船", "en": "sail / pilot a sailboat"}, {"hanzi": "帆船比赛", "en": "sailing competition / regatta"}, {"hanzi": "帆船运动", "en": "sailing sport"}, {"hanzi": "豪华帆船", "en": "luxury sailboat / yacht"}, {"hanzi": "帆船航行", "en": "sailboat navigation / cruising"}], "idioms": [{"hanzi": "一帆风顺", "pinyin": "yì fān fēng shùn", "meaning_en": "smooth sailing; proceed without a hitch"}, {"hanzi": "同舟共济", "pinyin": "tóng zhōu gòng jì", "meaning_en": "cross a river in the same boat; pull together in times of trouble"}, {"hanzi": "乘风破浪", "pinyin": "chéng fēng pò làng", "meaning_en": "ride the wind and cleave the waves; forge ahead fearlessly"}, {"hanzi": "风雨同舟", "pinyin": "fēng yǔ tóng zhōu", "meaning_en": "share weather and boat together; stand together through thick and thin"}], "character_decomposition": [{"character": "帆", "pinyin": "fān", "meaning_en": "sail; canvas", "meaning_es": "vela de barco; lienzo", "radical": "巾", "radical_meaning_en": "cloth / towel", "meaning_component": "巾 (canvas cloth used for catching wind)", "sound_component": "凡 (fán, phonetic marker and spreading contour)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: cloth (巾) spreading wide to catch sea breezes (凡) to propel watercraft.", "visual_mnemonic_story_en": "A tall sheet of strong woven cloth (巾) catching the vast ocean breeze (凡) to push a ship forward.", "visual_mnemonic_story_es": "Una gran tela resistente (巾) desplegada para atrapar la brisa marina (凡) e impulsar el barco.", "tone_mnemonic_anchor": "55", "cangjie": "LBHN", "traditional": ""}, {"character": "船", "pinyin": "chuán", "meaning_en": "boat; ship; vessel", "meaning_es": "barco; nave; embarcación", "radical": "舟", "radical_meaning_en": "boat / canoe", "meaning_component": "舟 (pictograph of a dugout canoe)", "sound_component": "㕣 (yǎn / 几+口 phonetic / hollow hull cavity)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: the boat radical (舟) paired with hull opening (㕣), indicating a floating water vessel.", "visual_mnemonic_story_en": "A buoyant wooden boat hull (舟) carrying travelers across the open water (㕣).", "visual_mnemonic_story_es": "El casco de madera de un barco (舟) que navega sobre las aguas abiertas (㕣).", "tone_mnemonic_anchor": "35", "cangjie": "HYNCR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "当夕阳的余晖洒满辽阔海面，白色帆船随微风轻轻荡漾。远离了陆地的嘈杂喧嚣，唯有海水拍打船舷的节律与海鸟清脆的鸣叫相伴。在纯净的蔚蓝世界里，心灵找到了久违的从容与自由。", "pinyin": "Dāng xīyáng de yúhuī sǎ mǎn liáokuò hǎimiàn, báisè fānchuán suí wēifēng qīngqīng dàngyàng. Yuǎnlí le lùdì de cáozá xuānxiāo, wéiyǒu hǎishuǐ pāidǎ chuánxián de jiélǜ yǔ hǎiniǎo qīngcuì de míngjiào xiāngbàn. Zài chúnjìng de wèilán shìjiè lǐ, xīnlíng zhǎodào le jiǔwéi de cóngròng yǔ zìyóu.", "en": "As sunset glow bathes the expansive sea, the white sailboat sways gently with the breeze. Far from terrestrial clamor, only the rhythmic lapping against the hull and seabird calls remain. In this pure azure expanse, the soul recovers its long-sought serenity and freedom.", "es": "Al teñirse el mar con los arreboles del ocaso, el velero blanco se mece suavemente con la brisa. Lejos del bullicio terrestre, solo acompaña el rítmico romper de las olas contra el casco y el trino de las aves marinas. En este puro mundo azul, el alma halla su ansiada libertad."}, {"id": "#2", "hanzi": "近年来，随着沿海城市海洋休闲产业的发展，民间帆船运动逐渐走入大众视野。参与者不仅能在航海中掌握水文与气象技能，更能磨砺团队协同作战与应对突发危机的意志力，展现了现代人挑战自然极限的体育精神。", "pinyin": "Jìnniánlái, suízhe yánhǎi chéngshì hǎiyáng xiūxián chǎnyè de fāzhǎn, mínjiān fānchuán yùndòng zhújiàn zǒurù dàzhòng shìyě. Cānyùzhě bùjǐn néng zài hánghǎi zhōng zhǎngwò shuǐwén yǔ qìxiàng jìnéng, gèng néng mólì tuánduì xiétóng zuòzhàn yǔ yìngduì tūfā wēijī de yìzhìlì, zhǎnxiàn le xiàndài rén tiǎozhàn zìrán jíxiàn de tǐyù jīngshén.", "en": "In recent years, with coastal marine recreation expanding, recreational sailing has entered mainstream vision. Sailors master hydrological and meteorological skills while forging teamwork and crisis-handling fortitude, embodying the modern athletic spirit of daring nature's limits.", "es": "En los últimos años, con el auge del ocio marino costero, la navegación a vela ha ganado popularidad. Quienes navegan aprenden hidrología y meteorología, templando a la vez la cooperación en equipo y la resolución de crisis, mostrando el valor contemporáneo de superación."}]}, {"meanings_summary": {"en": "classifier for boats, ships, and oceanic vessels", "es": "clasificador para barcos, buques y embarcaciones"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A vessel crafted from wood (舟) piloted by an elder captain (叟) is counted as one magnificent ship (艘).", "composite_memory_hook_es": "Una embarcación de madera (舟) guiada por un veterano capitán (叟) se cuenta como un majestuoso barco (艘).", "cultural_and_cognitive_roots": "In ancient classical Chinese, 'zhōu' (舟) denoted small craft while 'sōu' (艘) gradually specialized as the dedicated formal classifier for seafaring vessels of notable size.", "tone_sandhi_and_pitch_modulation": "High level 1st tone: sōu (55). When paired with '一' (yī), '一' changes to 4th tone: 'yì sōu' (51-55). Maintain a clear, steady vocal tone."}, "semantic_boundary_contrasts": {"core_nuance": "艘 is the formal, standard classifier reserved exclusively for motorized boats, sailing vessels, and naval ships.", "contrasts": [{"id": "1", "compared_word": "艘 vs. 只", "pinyin": "zhī", "analysis": "艘 is the formal classifier for boats and ships of any size (一艘船, 一艘航母), while 只 is colloquial and general, usually applied to smaller skiffs (一只小船)."}, {"id": "2", "compared_word": "艘 vs. 条", "pinyin": "tiáo", "analysis": "艘 applies to formal shipping vessels and ocean boats, whereas 条 is commonly used for long slender canoes or informal river boats (一条小舟, 一条渔船)."}, {"id": "3", "compared_word": "艘 vs. 架", "pinyin": "jià", "analysis": "艘 is strictly for aquatic craft, while 架 is the classifier for aircraft, airplanes, machinery, and framed items (一架飞机)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "艘", "pinyin": "sōu", "meaning_en": "classifier for ships", "distinction_note": "Has 舟 (boat) radical on the left"}, {"character": "搜", "pinyin": "sōu", "meaning_en": "search; seek", "distinction_note": "Has 扌 (hand) radical on the left instead of 舟"}, {"character": "嫂", "pinyin": "sǎo", "meaning_en": "elder brother's wife", "distinction_note": "Has 女 (woman) radical on the left instead of 舟"}, {"character": "瘦", "pinyin": "shòu", "meaning_en": "thin; lean", "distinction_note": "Has 疒 (sickness) radical enclosing 叟"}], "etymological_cognates": [{"character": "船舶", "pinyin": "chuán bó", "gloss_en": "watercraft; ships"}, {"character": "船只", "pinyin": "chuán zhī", "gloss_en": "vessels; fleet"}, {"character": "舟楫", "pinyin": "zhōu jí", "gloss_en": "boat and oars; shipping traffic"}, {"character": "巨轮", "pinyin": "jù lún", "gloss_en": "giant ocean liner; huge vessel"}]}, "id": "3", "hanzi": "艘", "pinyin": "sōu", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "standard numerical classifier for sea-going ships, warships, boats, and large vessels", "definition_es": "clasificador para embarcaciones marítimas y barcos", "example_phrase": "一艘轮船 (a steamship)"}], "example_sentences": [{"id": "#1", "hanzi": "港口里停泊着一艘艘远洋货轮，等待着工人们装卸来自五大洲的集装箱。", "pinyin": "Gǎngkǒu lǐ tíngbó zhe yì sōusōu yuǎnyáng huòlún, děngdài zhe gōngrénmen zhuāngxiè láizì wǔdàzhōu de jízhuāngxiāng.", "en": "Ocean-going cargo freighters were moored in the harbor, waiting for dockworkers to unload containers from five continents.", "es": "En el puerto descansaban buques de carga transoceánicos, a la espera de que los operarios descargaran contenedores llegados de los cinco continentes."}, {"id": "#2", "hanzi": "海军最新服役的一艘驱逐舰顺利完成了长达半年的护航与搜救演练任务。", "pinyin": "Hǎijūn zuìxīn fúyì de yì sōu qūzhújiàn shùnlì wánchéng le chángdá bàn nián de hùháng yǔ sōujiù yǎnliàn rènwu.", "en": "A newly commissioned navy destroyer successfully completed a half-year escort and search-and-rescue drill mission.", "es": "El flamante destructor incorporado por la marina completó con éxito una misión semestral de escolta y simulacros de salvamento marítimo."}], "collocations": [{"hanzi": "一艘船", "en": "a ship / boat"}, {"hanzi": "一艘军舰", "en": "a warship / naval vessel"}, {"hanzi": "一艘潜艇", "en": "a submarine"}, {"hanzi": "一艘货轮", "en": "a cargo freighter"}, {"hanzi": "一艘帆船", "en": "a sailboat"}, {"hanzi": "一艘快艇", "en": "a speedboat"}], "idioms": [{"hanzi": "共济同舟", "pinyin": "gòng jì tóng zhōu", "meaning_en": "cross in the same boat together; unite to overcome difficulties"}, {"hanzi": "木已成舟", "pinyin": "mù yǐ chéng zhōu", "meaning_en": "the wood is already a boat; what is done cannot be undone"}, {"hanzi": "沉舟破釜", "pinyin": "chén zhōu pò fǔ", "meaning_en": "sink boats and break cooking pots; burn bridges with resolve"}, {"hanzi": "顺水推舟", "pinyin": "shùn shuǐ tuī zhōu", "meaning_en": "push the boat along with the current; take advantage of an opportunity"}], "character_decomposition": [{"character": "艘", "pinyin": "sōu", "meaning_en": "classifier for boats", "meaning_es": "clasificador para barcos", "radical": "舟", "radical_meaning_en": "boat / canoe", "meaning_component": "舟 (boat hull)", "sound_component": "叟 (sǒu phonetic, elder)", "stroke_count": "15", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining boat (舟) with phonetic marker 叟 (elder), representing sea craft.", "visual_mnemonic_story_en": "An experienced old sailor (叟) at the helm of an ocean-going ship (舟) sailing through ocean foam.", "visual_mnemonic_story_es": "Un curtido marinero anciano (叟) al timón de una nave de alta mar (舟) sorteando las olas.", "tone_mnemonic_anchor": "55", "cangjie": "HYHXE", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "晨雾未散的江面上，一艘古旧的木船缓缓划破宁静的水面。老艄公手中的长篙在水中荡开圈圈涟漪，岁月仿佛在这无声的航程里放慢了脚步，让人忘却了尘世的浮躁与纷扰。", "pinyin": "Chénwù wèi sàn de jiāngmiàn shàng, yì sōu gùjiù de mùchuán huǎnhuǎn huàpò níngjìng de shuǐmiàn. Lǎo shāogōng shǒuzhōng de chánggāo zài shuǐzhōng dàng kāi quānquān liányī, suìyuè fǎngfú zài zhè wúshēng de hángchéng lǐ fàngmàn le jiǎobù, ràng rén wàngquè le chénshì de fúzào yǔ fēnrǎo.", "en": "On the river where morning mist had not yet cleared, an old wooden boat slowly cut through tranquil waters. Ripples expanded under the ferryman's pole; time seemed to slow in this quiet voyage, washing away mundane restlessness.", "es": "Sobre el río cubierto aún por la niebla matinal, un viejo barco de madera rasgaba despacio las aguas en calma. La pértiga del barquero trazaba ondas circulares; el tiempo parecía frenar su paso en este viaje sereno, disipando la inquietud terrenal."}, {"id": "#2", "hanzi": "伴随着一声嘹亮的汽笛，我国自主设计建造的万吨级科考船缓缓驶离母港。这艘现代化的先进科研巨轮搭载了深海勘探设备，将远赴极地海域执行多学科综合科学考察任务，展现了我国深蓝海洋科技的飞速跨越。", "pinyin": "Bànsuí zhe yì shēng liáoliàng de qìdí, wǒguó zìzhǔ shèjì jiànzào de wàndūnjí kěkǎochuán huǎnhuǎn shǐlí mǔgǎng. Zhè sōu xiàndàihuà de xiānjìn kēyán jùlún dāzài le shēnhǎi kāntàn shèbèi, jiāng yuǎnfù jídì hǎiyù zhíxíng duō xuékē zōnghé kēxué kǎochá rènwu, zhǎnxiàn le wǒguó shēnlán hǎiyáng kējì de fēisù kuàyuè.", "en": "With a resounding whistle, a ten-thousand-ton polar research vessel designed domestically set sail from its home port. Outfitted with deep-sea probes, this modern vessel journeys to polar waters for multidisciplinary expeditions, highlighting deep-sea technological leaps.", "es": "Entre el vibrante eco de una sirena, un buque científico de diez mil toneladas construido en el país zarpó de su puerto base. Esta moderna nave de investigación, dotada de sondas de aguas profundas, parte a los polos en misión multidisciplinar, reflejando el salto en tecnología marina."}]}, {"meanings_summary": {"en": "to sail; to navigate; to cruise by sea or air; voyage", "es": "navegar; surcar el mar o el aire; travesía náutica o aérea"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A ship (航) proceeding along a charted oceanic road (行) carries out a magnificent voyage of navigation (航行).", "composite_memory_hook_es": "Una embarcación (航) que avanza por una ruta trazada (行) emprende una maravillosa travesía de navegación (航行).", "cultural_and_cognitive_roots": "The character '航' originated with aquatic navigation and Zheng He's medieval maritime expeditions, later extended metaphorically in the 20th century to aeronautics (航空) and spaceflight (航天).", "tone_sandhi_and_pitch_modulation": "Two consecutive rising 2nd tones: háng xíng (35-35). Both rise smoothly without pitching too abruptly."}, "semantic_boundary_contrasts": {"core_nuance": "航行 specifically refers to long-distance motion through fluid mediums (water or air) along planned navigational tracks.", "contrasts": [{"id": "1", "compared_word": "航行 vs. 行驶", "pinyin": "xíngshǐ", "analysis": "航行 applies specifically to ships in water or aircraft in the air, while 行驶 typically applies to wheeled motor vehicles on land roads (汽车在公路上行驶)."}, {"id": "2", "compared_word": "航行 vs. 飞行", "pinyin": "fēixíng", "analysis": "航行 encompasses both sea voyage and air travel with an emphasis on navigational course, whereas 飞行 refers strictly to airborne travel or avian flight."}, {"id": "3", "compared_word": "航行 vs. 漂泊", "pinyin": "piāobó", "analysis": "航行 conveys purposeful, controlled movement guided by a helm, whereas 漂泊 emphasizes aimless drifting or wandering without a permanent home."}]}, "traps_and_cognates": {"look_alikes": [{"character": "航", "pinyin": "háng", "meaning_en": "sail; fly", "distinction_note": "Has 舟 (boat) on the left and 亢 on the right"}, {"character": "抗", "pinyin": "kàng", "meaning_en": "resist; combat", "distinction_note": "Has 扌 (hand) radical on the left with 亢"}, {"character": "坑", "pinyin": "kēng", "meaning_en": "pit; hole; defraud", "distinction_note": "Has 土 (earth) radical on the left with 亢"}, {"character": "炕", "pinyin": "kàng", "meaning_en": "heatable brick bed", "distinction_note": "Has 火 (fire) radical on the left with 亢"}], "etymological_cognates": [{"character": "航空", "pinyin": "háng kōng", "gloss_en": "aviation; aeronautics"}, {"character": "航天", "pinyin": "háng tiān", "gloss_en": "spaceflight; astronautics"}, {"character": "航班", "pinyin": "háng bān", "gloss_en": "scheduled flight; sailing schedule"}, {"character": "航线", "pinyin": "háng xiàn", "gloss_en": "air route; shipping sea lane"}]}, "id": "4", "hanzi": "航行", "pinyin": "háng xíng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to travel on water or through the air along a course", "definition_es": "navegar o desplazarse por agua o aire siguiendo una ruta", "example_phrase": "在大海上航行 (navigate upon the open sea)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Formal", "definition_en": "the act or course of navigating; cruising", "definition_es": "navegación; travesía náutica o aérea", "example_phrase": "安全航行 (safe navigation)"}], "example_sentences": [{"id": "#1", "hanzi": "经过长达三个月的艰难航行，考察船终于穿越了风暴肆虐的海峡，安全抵达南极科考站。", "pinyin": "Jīngguò chángdá sān gè yuè de jiānnán hángxíng, kǎocháchuán zhōngyú chuānyuè le fēngbào sìnüè de hǎixiá, ānquán dǐdá nánjí kěkǎozhàn.", "en": "After three months of arduous navigation, the expedition ship finally crossed the storm-ravaged strait and arrived safely at the Antarctic station.", "es": "Tras tres meses de difícil navegación, el buque científico cruzó al fin el estrecho azotado por temporales y arribó a salvo a la base antártica."}, {"id": "#2", "hanzi": "民航机长凭借精湛的飞行技能与敏锐的判断，保障了航班在恶劣雷雨天气下的平稳航行。", "pinyin": "Mínháng jīzhǎng píngjiè jīngzhàn de fēixíng jìnéng yǔ mǐnruì de pànduàn, bǎozhàng le hángbān zài èliè léiyǔ tiānqì xià de píngwěn hángxíng.", "en": "Relying on consummate piloting skills and keen judgment, the commercial airline captain ensured steady flight through severe thunderstorms.", "es": "Gracias a su destreza de pilotaje y agudo criterio, el comandante de aviación comercial garantizó un vuelo estable y seguro bajo severas tormentas."}], "collocations": [{"hanzi": "安全航行", "en": "safe navigation / cruising"}, {"hanzi": "航行路线", "en": "navigation route / course"}, {"hanzi": "远洋航行", "en": "ocean-going voyage"}, {"hanzi": "停止航行", "en": "suspend navigation"}, {"hanzi": "航行自由", "en": "freedom of navigation"}, {"hanzi": "昼夜航行", "en": "sail day and night"}], "idioms": [{"hanzi": "乘风破浪", "pinyin": "chéng fēng pò làng", "meaning_en": "ride the wind and break the waves; brave hardships boldly"}, {"hanzi": "扬帆起航", "pinyin": "yáng fān qǐ háng", "meaning_en": "hoist the sails and set out on a voyage"}, {"hanzi": "栈山航海", "pinyin": "zhàn shān háng hǎi", "meaning_en": "scale mountains and sail seas; endure arduous travels"}, {"hanzi": "梯山航海", "pinyin": "tī shān háng hǎi", "meaning_en": "scale cliffs and navigate oceans; travel from distant lands"}], "character_decomposition": [{"character": "航", "pinyin": "háng", "meaning_en": "navigate; sail; fly", "meaning_es": "navegar; cruzar aguas o aire", "radical": "舟", "radical_meaning_en": "boat / canoe", "meaning_component": "舟 (boat hull traversing water)", "sound_component": "亢 (kàng, phonetic / neck or high contour)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining boat (舟) with phonetic 亢, designating watercraft crossing open waters or air.", "visual_mnemonic_story_en": "A boat (舟) holding its bow high (亢) as it plows through oceanic waves.", "visual_mnemonic_story_es": "La proa de una nave (舟) levantada con orgullo (亢) mientras surca el oleaje marítimo.", "tone_mnemonic_anchor": "35", "cangjie": "HYYHN", "traditional": ""}, {"character": "行", "pinyin": "xíng", "meaning_en": "walk; go; travel", "meaning_es": "andar; marchar; desplazarse", "radical": "行", "radical_meaning_en": "crossroads / step", "meaning_component": "行 (pictograph of a four-way intersection)", "sound_component": "", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Ancient pictograph of a four-way road crossroads where people step forward and journey.", "visual_mnemonic_story_en": "Footsteps walking briskly through a wide four-way street intersection (行).", "visual_mnemonic_story_es": "Pasos decididos que avanzan a través de una encrucijada de caminos (行).", "tone_mnemonic_anchor": "35", "cangjie": "HONN", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "驾驶帆船在无垠的大洋中航行，是对水手意志与体魄的双重洗礼。当陆地彻底消失在地平线之外，唯有头顶的北极星指引前路。这种与风浪搏击的过程，让人深切领会到人类在自然面前的渺小与坚韧。", "pinyin": "Jiàshǐ fānchuán zài wúyín de dàyáng zhōng hángxíng, shì duì shuǐshǒu yìzhì yǔ tǐpò de shuāngchóng xǐlǐ. Dāng lùdì chèdǐ xiāoshī zài dìpíngxiàn zhīwài, wéiyǒu tóudǐng de běijíxīng zhǐyǐn qiánlù. Zhè zhǒng yǔ fēnglàng bójī de guòchéng, ràng rén shēnqiè lǐnghuì dào rénlèi zài zìrán miànqián de miǎoxiǎo yǔ jiānrèn.", "en": "Sailing a yacht across the boundless ocean is a baptism of both will and physical endurance. When land recedes past the horizon, only Polaris guides the vessel. Contending with waves reveals humanity's profound insignificance yet unyielding tenacity.", "es": "Navegar en velero por la inmensidad del océano bautiza el temple y el vigor físico del marinero. Al disiparse la costa en el horizonte, solo la Estrella Polar guía el rumbo. Luchar contra el temporal revela tanto la pequeñez humana como su indomable tenacidad."}, {"id": "#2", "hanzi": "现代卫星导航与气象雷达系统的普及，彻底革新了全球远洋航运产业的航行模式。海事部门能够实时监控航道水文变化与极端天气演变，精准规划避风路径，从而大幅降低了海上事故率，确保国际贸易大通道的安全畅通。", "pinyin": "Xiàndài wèixīng dǎoháng yǔ qìxiàng léidá xìtǒng de pǔjí, chèdǐ gēxīn le quánqiú yuǎnyáng hángyùn chǎnyè de hángxíng móshì. Hǎishì bùmén nénggòu shíshí jiānkòng hángdào shuǐwén biànhuà yǔ jíduān tiānqì yǎnbiàn, jīngzhǔn guīhuà bìfēng lùjìng, cóng'ér dàfú jiàngdī le hǎishàng shìgùlǜ, quèbǎo guójì màoyì dàtōngdào de ānquán chàngtōng.", "en": "The ubiquity of satellite navigation and weather radar has revolutionized ocean freight navigation models. Maritime authorities monitor real-time hydrological shifts and extreme storms to chart storm-evading courses, dramatically lowering maritime incidents.", "es": "La generalización del GPS por satélite y los radares meteorológicos ha revolucionado la navegación en el transporte marítimo mundial. Las autoridades marítimas monitorizan corrientes y tormentas para trazar rutas seguras, reduciendo siniestros y blindando el comercio."}]}, {"meanings_summary": {"en": "second-hand; pre-owned; indirect; dealing in used goods", "es": "de segunda mano; usado; indirecto; de ocasión"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An item that has passed into a second (二) person's hands (手) becomes a cherished second-hand possession (二手).", "composite_memory_hook_es": "Un artículo que ha pasado a manos de una segunda (二) persona (手) se convierte en una posesión de segunda mano (二手).", "cultural_and_cognitive_roots": "Metaphorically, 'first hand' (一手) represents direct origin or creation, while 'second hand' (二手) denotes intermediary transfer, resource circulation, and practical frugality in material culture.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone followed by a dipping 3rd tone: èr shǒu (51-214). 'èr' strikes sharply downwards before 'shǒu' dips deep into the lower vocal register."}, "semantic_boundary_contrasts": {"core_nuance": "二手 highlights that an item has undergone previous ownership or that information was acquired via an intermediary.", "contrasts": [{"id": "1", "compared_word": "二手 vs. 旧", "pinyin": "jiù", "analysis": "二手 emphasizes previous ownership and transactional transfer (二手车 may still be 90% new), while 旧 focuses purely on physical age, wear, or obsolescence (旧衣服, 旧社会)."}, {"id": "2", "compared_word": "二手 vs. 翻新", "pinyin": "fānxīn", "analysis": "二手 describes goods simply traded in their existing state, whereas 翻新 signifies that used items were reconditioned, repaired, or refurbished to look brand new."}, {"id": "3", "compared_word": "二手 vs. 一手", "pinyin": "yìshǒu", "analysis": "二手 indicates secondary acquisition through middlemen or prior owners, whereas 一手 denotes direct, pristine source acquisition from manufacturers (一手货源) or direct observation."}]}, "traps_and_cognates": {"look_alikes": [{"character": "二", "pinyin": "èr", "meaning_en": "two", "distinction_note": "Two simple horizontal strokes"}, {"character": "三", "pinyin": "sān", "meaning_en": "three", "distinction_note": "Three parallel horizontal strokes"}, {"character": "毛", "pinyin": "máo", "meaning_en": "hair; fur; feather", "distinction_note": "Extends the bottom curve rightward into a hook (乚) with an angled top stroke"}, {"character": "手", "pinyin": "shǒu", "meaning_en": "hand", "distinction_note": "Straight vertical hook with three horizontal crossing strokes"}], "etymological_cognates": [{"character": "一手", "pinyin": "yì shǒu", "gloss_en": "first-hand; single-handed; proficiency"}, {"character": "插手", "pinyin": "chā shǒu", "gloss_en": "poke one's nose into; intervene"}, {"character": "转手", "pinyin": "zhuǎn shǒu", "gloss_en": "resell; pass on through another hand"}, {"character": "帮手", "pinyin": "bāng shou", "gloss_en": "helper; assistant"}]}, "id": "5", "hanzi": "二手", "pinyin": "èr shǒu", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "previously owned or used by another person", "definition_es": "de segunda mano; usado previamente por otra persona", "example_phrase": "二手房 (pre-owned house / second-hand apartment)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "received indirectly or heard from intermediary sources", "definition_es": "de segunda mano; indirecto; no presenciado directamente", "example_phrase": "二手资料 (second-hand source material)"}], "example_sentences": [{"id": "#1", "hanzi": "为了实现环球航海的夙愿，翟峰夫妇变卖了家产，自费购置了一艘二手双体帆船。", "pinyin": "Wèile shíxiàn huánqiú hánghǎi de sùyuàn, Zhái Fēng fūfù biànmài le jiāchǎn, zìfèi gòuzhì le yì sōu èrshǒu shuāngtǐ fānchuán.", "en": "To realize their lifelong dream of circumnavigating the globe, Zhai Feng and his wife sold their belongings and purchased a used catamaran.", "es": "Para cumplir su anhelo de circunnavegar el planeta, Zhai Feng y su esposa vendieron sus bienes y compraron un catamarán de segunda mano."}, {"id": "#2", "hanzi": "近年来二手车交易平台蓬勃发展，通过透明的检测认证制度赢得了年轻消费群体的信赖。", "pinyin": "Jìnniánlái èrshǒuchē jiāoyì píngtái péngbó fāzhǎn, tōngguò tòumíng de jiǎncè rènzhèng zhìdù yíngdé le niánqīng xiāofèiqúntǐ de xìnlài.", "en": "In recent years, pre-owned car trading platforms have flourished, winning the trust of young consumers through transparent inspection systems.", "es": "En los últimos años, las plataformas de coches de ocasión han prosperado, ganándose la confianza de jóvenes compradores mediante revisiones transparentes."}], "collocations": [{"hanzi": "二手车", "en": "second-hand car; used car"}, {"hanzi": "二手房", "en": "pre-owned housing; second-hand apartment"}, {"hanzi": "二手市场", "en": "second-hand market; thrift market"}, {"hanzi": "二手书", "en": "second-hand book; used book"}, {"hanzi": "二手烟", "en": "second-hand smoke; passive smoking"}, {"hanzi": "二手交易", "en": "second-hand transaction"}], "idioms": [{"hanzi": "二话不说", "pinyin": "èr huà bù shuō", "meaning_en": "without saying another word; without hesitation"}, {"hanzi": "一手包办", "pinyin": "yì shǒu bāo bàn", "meaning_en": "take care of everything single-handedly"}, {"hanzi": "得心应手", "pinyin": "dé xīn yìng shǒu", "meaning_en": "what the heart wishes the hand can do; highly proficient"}, {"hanzi": "手足无措", "pinyin": "shǒu zú wú cuò", "meaning_en": "at a loss what to do with hands and feet; bewildered"}], "character_decomposition": [{"character": "二", "pinyin": "èr", "meaning_en": "two; secondary", "meaning_es": "dos; segundo; secundario", "radical": "二", "radical_meaning_en": "two / pair", "meaning_component": "二 (two parallel horizontal lines)", "sound_component": "", "stroke_count": "2", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient ideograph of two parallel strokes representing the cardinal number two and secondary rank.", "visual_mnemonic_story_en": "Two horizontal lines (二) stacked neatly representing a pair or the second in line.", "visual_mnemonic_story_es": "Dos trazos horizontales (二) que representan la dualidad o el segundo en orden sucesivo.", "tone_mnemonic_anchor": "51", "cangjie": "MM", "traditional": ""}, {"character": "手", "pinyin": "shǒu", "meaning_en": "hand; person doing action", "meaning_es": "mano; persona que ejecuta una acción", "radical": "手", "radical_meaning_en": "hand / palm", "meaning_component": "手 (pictograph of human hand and spread fingers)", "sound_component": "", "stroke_count": "4", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a human palm with five outstretched fingers and wrist line.", "visual_mnemonic_story_en": "A palm showing five distinct fingers (手) ready to grasp, hold, and pass down an object.", "visual_mnemonic_story_es": "Una palma con sus dedos abiertos (手) lista para asir, manipular y transferir un objeto.", "tone_mnemonic_anchor": "214", "cangjie": "F", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "逛周末二手旧书市集是许多读书人独特的雅趣。那些泛黄纸页间夹带的铅笔批注与旧书签，记录了前一位读者与文字对话的温度。一件二手物品，因承载了时间的印记而变得别具情调与生命力。", "pinyin": "Guàng zhōumò èrshǒu jiùshū shìjí shì xǔduō dúshūrén dútè de yǎqù. Nàxiē fànhuáng zhǐyè jiān jiādài de qiānbǐ pīzhù yǔ jiù shūqiān, jìlù le qián yí wèi dúzhě yǔ wénzì duìhuà de wēndù. Yí jiàn èrshǒu wùpǐn, yīn chéngzài le shíjiān de yìnjì ér biànde biéjù qíngdiào yǔ shēngmìnglì.", "en": "Browsing weekend used bookstores is a refined pleasure for bibliophiles. Penciled annotations and aged bookmarks between yellowed pages record the previous reader's intimate dialogue with words. A pre-owned artifact carries the patina of time, imbued with unique vitality.", "es": "Recorrer el mercadillo de libros usados de fin de semana es un deleite para los amantes de la lectura. Anotaciones a lápiz y marcapáginas olvidados entre hojas amarillentas conservan la huella del lector anterior. Un objeto de segunda mano atesora el alma del tiempo y cobra vida propia."}, {"id": "#2", "hanzi": "循环经济理念的深入推广，促使二手循环经济从边缘业态逐步迈向规范化、规模化发展轨道。建立完善的二手商品质量鉴定与信用溯源标准体系，不仅有效促进了资源的高效循环利用，也为践行低碳环保的生活方式提供了强有力的市场支撑。", "pinyin": "Xúnhuán jīngjì lǐniàn de shēnrù tuīguǎng, cùshǐ èrshǒu xúnhuán jīngjì cóng biānyuán yètài zhúbù màixiàng guīfànhuà, guīmóhuà fāzhǎn guǐdào. Jiànlì wánshàn de èrshǒu shāngpǐn zhìliàng jiàndìng yǔ xìnyòng sùyuán biāozhǔn tǐxì, bùjǐn yǒuxiào cùjìn le zīyuán de gāoxiào xúnhuán lìyòng, yě wèi jiànxíng dītàn huánbǎo de shēnghuó fāngshì tígōng le qiángyǒulì de shìchǎng zhīchēng.", "en": "Promoting the circular economy has driven second-hand markets from fringe commerce toward standardized, scaled development. Establishing quality certification and traceability standards facilitates efficient resource recycling while furnishing market support for low-carbon green living.", "es": "El fomento de la economía circular ha impulsado el mercado de segunda mano desde la periferia hacia la estandarización profesional. Trazar normas de peritaje y trazabilidad de artículos usados no solo optimiza recursos, sino que respalda firmemente un estilo de vida ecológico y bajo en carbono."}]}, {"meanings_summary": {"en": "rainbow; spectrum of colors in the sky", "es": "arco iris; arcoíris"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Radiant colors (彩) arch across the sky like a celestial serpent bridge (虹) forming a breathtaking rainbow (彩虹).", "composite_memory_hook_es": "Brillantes colores (彩) trazan un puente celestial serpenteante (虹) formando un hermoso arcoíris (彩虹).", "cultural_and_cognitive_roots": "Ancient Chinese meteorology viewed the rainbow as a mythical atmospheric creature (虹霓) bridging heaven and earth. In popular idioms, seeing a rainbow signifies hardship yielding to blessing ('不经历风雨，怎能见彩虹').", "tone_sandhi_and_pitch_modulation": "Dipping 3rd tone followed by a rising 2nd tone: cǎi hóng (214-35). 'cǎi' dips smoothly into pitch 21 before ascending cleanly into 'hóng' (35)."}, "semantic_boundary_contrasts": {"core_nuance": "彩虹 denotes the specific optical phenomenon of spectral color bands arched in the sky after moisture refractions.", "contrasts": [{"id": "1", "compared_word": "彩虹 vs. 彩霞", "pinyin": "cǎixiá", "analysis": "彩虹 is a curved spectral optical arc produced opposite the sun, while 彩霞 refers to the warm red, orange, and purple illuminated cloud banks at sunrise or sunset."}, {"id": "2", "compared_word": "彩虹 vs. 晕", "pinyin": "yùn", "analysis": "彩虹 forms via water droplet reflection/refraction with distinct multi-band colors, whereas 晕 (halo) refers to faint circular rings of diffused light around the sun or moon."}, {"id": "3", "compared_word": "彩虹 vs. 极光", "pinyin": "jíguāng", "analysis": "彩虹 occurs universally in lower atmospheres following rainfall, whereas 极光 (aurora) is an electromagnetic plasma luminescence restricted to polar nighttime skies."}]}, "traps_and_cognates": {"look_alikes": [{"character": "采", "pinyin": "cǎi", "meaning_en": "pick; gather", "distinction_note": "Lacks the three decorative brushstrokes 彡 on the right"}, {"character": "红", "pinyin": "hóng", "meaning_en": "red", "distinction_note": "Has 纟 (silk) radical on the left instead of 虫 (insect/creature)"}, {"character": "肛", "pinyin": "gāng", "meaning_en": "anus", "distinction_note": "Has 月 (flesh) radical on the left with 工"}, {"character": "扛", "pinyin": "káng", "meaning_en": "carry on shoulder", "distinction_note": "Has 扌 (hand) radical on the left with 工"}], "etymological_cognates": [{"character": "彩霞", "pinyin": "cǎi xiá", "gloss_en": "rosy evening clouds"}, {"character": "色彩", "pinyin": "sè cǎi", "gloss_en": "color; hue; flavor"}, {"character": "虹吸", "pinyin": "hóng xī", "gloss_en": "siphon; siphoning effect"}, {"character": "五彩", "pinyin": "wǔ cǎi", "gloss_en": "five colors; multi-colored"}]}, "id": "6", "hanzi": "彩虹", "pinyin": "cǎi hóng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an arc of spectral colors that appears in the sky opposite the sun after rain", "definition_es": "arco de colores que aparece en el cielo por la refracción solar en la lluvia", "example_phrase": "雨后彩虹 (rainbow after the rain)"}], "example_sentences": [{"id": "#1", "hanzi": "暴风雨过后，天边悬挂起一道绚丽的彩虹，给在海上漂泊数日的船员们带来了希望。", "pinyin": "Bàofēngyǔ guòhòu, tiānbiān xuánguà qǐ yí dào xuànlì de cǎihóng, gěi zài hǎishàng piāobó shù rì de chuányuánmen dài lái le xīwàng.", "en": "After the storm, a resplendent rainbow arched across the horizon, bringing renewed hope to sailors adrift for days.", "es": "Tras la tormenta, un resplandeciente arcoíris se dibujó en el horizonte, trayendo esperanza a los marineros tras días de travesía."}, {"id": "#2", "hanzi": "科学家利用高精度光学仪器，深入剖析了阳光穿透大气水滴形成双彩虹的物理机制。", "pinyin": "Kēxuéjiā lìyòng gāojīngdù guāngxué yíqì, shēnrù pōuxī le yángguāng chuāntòu dàqì shuǐdī xíngchéng shuāng cǎihóng de wùlǐ jīzhì.", "en": "Using precision optical instruments, scientists analyzed the physical mechanism of double rainbows formed by sunlight refracting through atmospheric droplets.", "es": "Con instrumentos ópticos de alta precisión, los científicos analizaron el mecanismo físico que genera un arcoíris doble mediante la refracción solar en gotas atmosféricas."}], "collocations": [{"hanzi": "一道彩虹", "en": "a rainbow"}, {"hanzi": "彩虹般的颜色", "en": "rainbow-like colors"}, {"hanzi": "雨后彩虹", "en": "rainbow after rain"}, {"hanzi": "绚丽的彩虹", "en": "gorgeous / resplendent rainbow"}, {"hanzi": "彩虹桥", "en": "rainbow bridge"}, {"hanzi": "七色彩虹", "en": "seven-colored rainbow"}], "idioms": [{"hanzi": "彩云易散", "pinyin": "cǎi yún yì sàn", "meaning_en": "colorful clouds easily disperse; beautiful illusions vanish quickly"}, {"hanzi": "光彩夺目", "pinyin": "guāng cǎi duó mù", "meaning_en": "brilliant and dazzling; of dazzling splendor"}, {"hanzi": "彩凤随鸦", "pinyin": "cǎi fèng suí yā", "meaning_en": "a colorful phoenix following a crow; a fine talent mismatched with someone inferior"}, {"hanzi": "五彩斑斓", "pinyin": "wǔ cǎi bān lán", "meaning_en": "multicoloured; gorgeously iridescent"}], "character_decomposition": [{"character": "彩", "pinyin": "cǎi", "meaning_en": "color; hue; prize", "meaning_es": "color; matiz; premio", "radical": "彡", "radical_meaning_en": "hair / bristle streaks", "meaning_component": "彡 (fine brushstrokes or luster)", "sound_component": "采 (cǎi phonetic / gather with hands)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: hand gathering foliage (采) adorned with lustrous radiant brushstrokes (彡).", "visual_mnemonic_story_en": "Hands gathering vibrant flowers (采) leave colorful brushstrokes (彡) across the canvas.", "visual_mnemonic_story_es": "Manos que cosechan flores (采) dejan hermosos trazos de colores vivos (彡) sobre el lienzo.", "tone_mnemonic_anchor": "214", "cangjie": "BDHH", "traditional": ""}, {"character": "虹", "pinyin": "hóng", "meaning_en": "rainbow", "meaning_es": "arcoíris", "radical": "虫", "radical_meaning_en": "insect / worm / serpent", "meaning_component": "虫 (mythological sky dragon/serpent drinking river water)", "sound_component": "工 (gōng phonetic / span bridge)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Ancient pictograph of a celestial two-headed dragon or serpent (虫) arching across the sky to drink river water (工).", "visual_mnemonic_story_en": "A celestial dragon serpent (虫) stretching an arching bridge (工) across the sky after rain.", "visual_mnemonic_story_es": "Un dragón celestial mitológico (虫) que tiende un puente combado (工) en el cielo tras la tormenta.", "tone_mnemonic_anchor": "35", "cangjie": "LIM", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "狂风暴雨洗净了海面上的尘霾，天际间缓缓浮现出一道壮丽的彩虹。七彩光晕连接着苍穹与碧波，宛如大自然写给远方游子的安慰。那一刻，航海途中的所有疲惫与凶险，都融化在这无与伦比的美丽之中。", "pinyin": "Kuángfēngbàoyǔ xǐjìng le hǎimiàn shàng de chénmái, tiānjì jiān huǎnhuǎn fúxiàn chū yí dào zhuànglì de cǎihóng. Qīcǎi guāngyùn liánjiē zhe cāngqióng yǔ bìbō, wǎnrú dàzìrán xiě gěi yuǎnfāng yóuzǐ de ānwèi. Nà yí kè, hánghǎi túzhōng de suǒyǒu píbèi yǔ xiōngxiǎn, dōu rónghuà zài zhè wúyǔlúnbǐ de měilì zhīzhōng.", "en": "Violent storms washed away oceanic haze, and a magnificent rainbow slowly materialized on the horizon. Seven-hued luminescence linked heaven and azure waves, nature's gentle solace for weary travelers. In that moment, all voyaging toil dissolved into unparalleled splendor.", "es": "La tormenta lavó la calima marina y un espléndido arcoíris surgió lentamente en el horizonte. Siete reflejos unían el firmamento y las olas azules, como un consuelo que la naturaleza brinda al viajero. En ese instante, fatigas y peligros del viaje se disolvieron en belleza pura."}, {"id": "#2", "hanzi": "气象光学原理证明，彩虹的形成源于阳光在球形雨滴内部发生的折射、全反射与色散过程。当空气湿度适宜且观测者背对光源时，便能清晰捕捉到这道美丽的自然光谱。现代科研人员借助这一光学机理，持续改进遥感监测与大气气溶胶分析模型。", "pinyin": "Qìxiàng guāngxué yuánlǐ zhèngmíng, cǎihóng de xíngchéng yuányú yángguāng zài qiúxíng yǔdī nèibù fāshēng de zhéshè, quánfǎnshè yǔ sèsàn guòchéng. Dāng kōngqì shīdù shìyí qiě guāncèzhě bèiduì guāngyuán shí, biàn néng qīngxī bǔzhuō dào zhè dào měilì de zìrán guāngpǔ. Xiàndài kēyán rényuán jièzhù zhè yí guāngxué jīlǐ, chíxù gǎijìn yáogǎn jiānkòng yǔ dàqì qìróngjiāo fēnxī móxíng.", "en": "Meteorological optics proves that rainbows originate from refraction, internal reflection, and dispersion within spherical raindrops. When humidity is optimal and observers face away from sunlight, this spectrum emerges cleanly, informing modern aerosol remote-sensing models.", "es": "La óptica meteorológica demuestra que el arcoíris surge de la refracción, reflexión interna y dispersión solar en gotas esféricas. Con humedad idónea y dando la espalda al sol, se contempla este nítido espectro, mecanismo aprovechado hoy en teledetección de aerosoles atmosféricos."}]}, {"meanings_summary": {"en": "comfortable; cozy; snug; easeful", "es": "cómodo; confortable; agradable; acogedor"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When your limbs can freely stretch (舒) along a fitting path of life (适), you experience complete relaxation and comfort (舒适).", "composite_memory_hook_es": "Cuando el cuerpo se estira relajado (舒) por un camino favorable (适), se disfruta de pleno confort y bienestar (舒适).", "cultural_and_cognitive_roots": "Ancient Daoist aesthetics connected '舒' (stretching without constriction) with '适' (harmonious adaptation to nature), forming an ideal balance between mind and bodily ease.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a sharp falling 4th tone: shū shì (55-51). Articulate 'shū' with smooth breath and conclude 'shì' decisively."}, "semantic_boundary_contrasts": {"core_nuance": "舒适 emphasizes an objective condition or environment providing pleasant, relaxing, high-quality sensory ease.", "contrasts": [{"id": "1", "compared_word": "舒适 vs. 舒服", "pinyin": "shūfu", "analysis": "舒适 is more formal and literary, commonly modifying environments, clothing, or designs (环境舒适, 舒适的床垫), while 舒服 is colloquial and describes both physical ease and bodily health (身体不舒服)."}, {"id": "2", "compared_word": "舒适 vs. 安逸", "pinyin": "ānyì", "analysis": "舒适 denotes enjoyable physical and atmospheric comfort, whereas 安逸 often carries a cautionary connotation of lazy complacency or avoiding life's challenges (贪图安逸)."}, {"id": "3", "compared_word": "舒适 vs. 自在", "pinyin": "zìzài", "analysis": "舒适 focuses on sensory ease from external surroundings, while 自在 describes mental freedom, unrestricted behavior, and psychological autonomy."}]}, "traps_and_cognates": {"look_alikes": [{"character": "舒", "pinyin": "shū", "meaning_en": "relax; stretch", "distinction_note": "Has 舍 on the left and 予 on the right"}, {"character": "野", "pinyin": "yě", "meaning_en": "wild; open country", "distinction_note": "Has 里 on the left and 予 on the right"}, {"character": "适", "pinyin": "shì", "meaning_en": "suitable; fit", "distinction_note": "Has 辶 radical enclosing 舌"}, {"character": "恬", "pinyin": "tián", "meaning_en": "calm; quiet", "distinction_note": "Has 忄 (heart) radical on the left with 舌"}], "etymological_cognates": [{"character": "舒服", "pinyin": "shū fu", "gloss_en": "comfortable; feel well"}, {"character": "合适", "pinyin": "hé shì", "gloss_en": "suitable; appropriate; fitting"}, {"character": "适应", "pinyin": "shì yìng", "gloss_en": "adapt to; adjust"}, {"character": "舒展", "pinyin": "shū zhǎn", "gloss_en": "unfold; extend; smooth out"}]}, "id": "7", "hanzi": "舒适", "pinyin": "shū shì", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "providing physical ease, relaxation, or pleasant well-being", "definition_es": "que produce bienestar físico, relajación o agrado", "example_phrase": "舒适的环境 (comfortable environment)"}], "example_sentences": [{"id": "#1", "hanzi": "他不愿一辈子过着安逸舒适的生活，而是渴望驾驶帆船去探索未知的辽阔世界。", "pinyin": "Tā bú yuàn yíbèizi guò zhe ānyì shūshì de shēnghuó, ér shì kěwàng jiàshǐ fānchuán qù tànsuǒ wèizhī de liáokuò shìjiè.", "en": "Unwilling to spend a lifetime in easy, comfortable ease, he yearned to pilot a sailboat to explore the vast unknown world.", "es": "Negándose a pasar toda la vida en una existencia plácida y cómoda, ansiaba tripular un velero para explorar la inmensidad del mundo ignoto."}, {"id": "#2", "hanzi": "该度假酒店以符合人体工学的设计理念改造客房，为跨国商旅人士打造出极致舒适的休憩体验。", "pinyin": "Gāi dùjià jiǔdiàn yǐ fúhé réntǐ gōngxué de shèjì lǐniàn gǎizào kèfáng, wèi kuàguó shānglǚ rénshì dǎzào chū jízhì shūshì de xiūqì tǐyàn.", "en": "The resort hotel renovated guest rooms using ergonomic design concepts, crafting an intensely comfortable resting experience for international business travelers.", "es": "El complejo hotelero remodeló sus habitaciones con criterios ergonómicos, creando una experiencia de descanso de máximo confort para viajeros de negocios globales."}], "collocations": [{"hanzi": "舒适的生活", "en": "comfortable life"}, {"hanzi": "环境舒适", "en": "comfortable environment"}, {"hanzi": "感到舒适", "en": "feel comfortable"}, {"hanzi": "舒适惬意", "en": "cozy and pleasant"}, {"hanzi": "舒适整洁", "en": "comfortable and tidy"}, {"hanzi": "舒适度", "en": "degree of comfort; comfort level"}], "idioms": [{"hanzi": "舒心惬意", "pinyin": "shū xīn qiè yì", "meaning_en": "comfortable and gratified; relaxed and at ease"}, {"hanzi": "心广体胖", "pinyin": "xīn guǎng tǐ pán", "meaning_en": "carefree mind and healthy plump body; comfortable peace of mind"}, {"hanzi": "安居乐业", "pinyin": "ān jū lè yè", "meaning_en": "live and work in peace and contentment"}, {"hanzi": "得心应手", "pinyin": "dé xīn yìng shǒu", "meaning_en": "handy and comfortable; skilled and smooth"}], "character_decomposition": [{"character": "舒", "pinyin": "shū", "meaning_en": "stretch; relax; leisurely", "meaning_es": "estirar; relajar; pausado", "radical": "舌", "radical_meaning_en": "tongue / speech", "meaning_component": "舍 (shè phonetic / lodge)", "sound_component": "予 (yú / stretch outward or give)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: giving (予) shelter in a dwelling (舍), allowing body and limbs to relax and stretch leisurely.", "visual_mnemonic_story_en": "Resting your head peacefully in a home lodge (舍) while freely stretching out (予) your limbs.", "visual_mnemonic_story_es": "Reposar con sosiego en un albergue (舍) extendiendo libremente (予) los brazos y el cuerpo.", "tone_mnemonic_anchor": "55", "cangjie": "OINN", "traditional": ""}, {"character": "适", "pinyin": "shì", "meaning_en": "suitable; proper; comfortable", "meaning_es": "apto; adecuado; cómodo", "radical": "辶", "radical_meaning_en": "walk / motion", "meaning_component": "辶 (walking path)", "sound_component": "舌 (shé phonetic / tongue or taste)", "stroke_count": "9", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ideogrammic compound: stepping forward along a smooth path (辶) where everything suits one's palate and senses (舌).", "visual_mnemonic_story_en": "Strolling smoothly along a paved path (辶) where every step feels completely natural and fitting (舌).", "visual_mnemonic_story_es": "Caminar a paso ligero por un sendero llano (辶) donde cada pisada resulta placentera y justa (舌).", "tone_mnemonic_anchor": "51", "cangjie": "YHR", "traditional": "適"}], "extended_reading_passages": [{"id": "#1", "hanzi": "很多人将舒适的居所视作终生奋斗的归宿，但过度的安稳有时也会磨灭探索未知的勇气。当我们在温暖的房间里待得太久，不妨推开窗户，感受一下荒野的风与海水的咸涩，重燃内心对生命的渴望。", "pinyin": "Hěnduō rén jiāng shūshì de jūsuǒ shìzuò zhōngshēng fèndòu de guīsù, dàn guòdù de ānwěn yǒushí yě huì mómiè tànsuǒ wèizhī de yǒngqì. Dāng wǒmen zài wēnnuǎn de fángjiān lǐ dài de tài jiǔ, bùfáng tuīkāi chuānghu, gǎnshòu yíxià huāngyě de fēng yǔ hǎishuǐ de xiánsè, chóngrán nèixīn duì shēngmìng de kěwàng.", "en": "Many consider a comfortable home the ultimate prize of lifelong struggle, yet excessive security can dull courage to explore. Lingering too long in warm rooms, we might open the window to taste wild wind and sea salt, rekindling thirst for existence.", "es": "Muchos ven en un hogar confortable la meta de una vida de esfuerzo, pero el acomodo excesivo puede adormecer la audacia exploradora. Tras permanecer mucho tiempo al abrigo del hogar, conviene abrir la ventana al viento agreste y la sal marina para avivar la sed vital."}, {"id": "#2", "hanzi": "现代工业设计越来越强调“以人为本”，在座椅研发中广泛引入空间力学与新材料科技，力求将人体工程学舒适度推向新高度。实验数据表明，优化办公环境的舒适水准不仅能显著缓解骨骼疲劳，更能提升脑力劳动者的长期专注度与工作效率。", "pinyin": "Xiàndài gōngyè shèjì yuèláiyuè qiángdiào \"yǐrénwéiběn\", zài zuòyǐ yánfā zhōng guǎngfàn yǐnrù kōngjiān lìxué yǔ xīn cáiliào kējì, lìqiú jiāng réntǐ gōngchéngxué shūshìdù tuīxiàng xīn gāodù. Shíyàn shùjù biǎomíng, yōuhuà bàngōng huánjìng de shūshì shuǐzhǔn bùjǐn néng xiǎnzhù huǎnjiě gǔgé píláo, gèng néng tíshēng nǎolì láodòngzhě de chángqī zhuānzhùdù yǔ gōngzuò xiàolǜ.", "en": "Contemporary industrial design emphasizes human-centric values, incorporating spatial ergonomics and modern materials into seating to elevate comfort. Empirical data confirms that optimizing workplace comfort mitigates musculoskeletal fatigue while boosting cognitive productivity.", "es": "El diseño industrial actual prima el principio humano, aplicando biomecánica y nuevos materiales al mobiliario para elevar el confort ergonómico. Los datos revelan que optimizar el confort en la oficina no solo alivia la fatiga física, sino que potencia la concentración intelectual."}]}, {"meanings_summary": {"en": "to resign; to quit one's job; to tender resignation", "es": "dimitir; renunciar al trabajo; presentar la dimisión"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Uttering formal words of farewell (辞) to relinquish your professional post (职) marks the bold decision to resign (辞职).", "composite_memory_hook_es": "Pronunciar palabras formales de despedida (辞) para desligarse del puesto asignado (职) sella la dimisión (辞职).", "cultural_and_cognitive_roots": "In imperial China, scholar-officials resigning to return home was celebrated as moral independence (辞官归隐), embodying the pursuit of personal integrity above material emolument.", "tone_sandhi_and_pitch_modulation": "Two consecutive rising 2nd tones: cí zhí (35-35). Rise smoothly and clearly on each syllable without dropping pitch in between."}, "semantic_boundary_contrasts": {"core_nuance": "辞职 emphasizes the employee's voluntary and unilateral choice to terminate an employment relationship.", "contrasts": [{"id": "1", "compared_word": "辞职 vs. 离职", "pinyin": "lízhí", "analysis": "辞职 highlights the employee's proactive, voluntary action to resign, whereas 离职 is an objective neutral term describing the fact of leaving a company (due to resignation, contract expiry, or transfer)."}, {"id": "2", "compared_word": "辞职 vs. 解雇", "pinyin": "jiěgù", "analysis": "辞职 is initiated voluntarily by the employee, whereas 解雇 (firing/dismissal) is an involuntary termination initiated by the employer."}, {"id": "3", "compared_word": "辞职 vs. 退休", "pinyin": "tuìxiū", "analysis": "辞职 represents leaving employment at any working age, whereas 退休 refers to retiring upon reaching statutory legal age after decades of service."}]}, "traps_and_cognates": {"look_alikes": [{"character": "辞", "pinyin": "cí", "meaning_en": "resign; words", "distinction_note": "Has 舌 on the left and 辛 on the right"}, {"character": "辩", "pinyin": "biàn", "meaning_en": "debate; argue", "distinction_note": "Has 辛 on both left and right enclosing 讠 (speech)"}, {"character": "职", "pinyin": "zhí", "meaning_en": "post; job", "distinction_note": "Has 耳 (ear) on the left and 只 on the right"}, {"character": "聪", "pinyin": "cōng", "meaning_en": "clever; acute hearing", "distinction_note": "Has 耳 (ear) on the left and 总 on the right"}], "etymological_cognates": [{"character": "辞退", "pinyin": "cí tuì", "gloss_en": "dismiss; discharge; fire"}, {"character": "辞别", "pinyin": "cí bié", "gloss_en": "say goodbye to; bid farewell"}, {"character": "职业", "pinyin": "zhí yè", "gloss_en": "occupation; profession"}, {"character": "职责", "pinyin": "zhí zé", "gloss_en": "duty; responsibility"}]}, "id": "8", "hanzi": "辞职", "pinyin": "cí zhí", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to voluntarily relinquish one's office, post, or employment", "definition_es": "renunciar voluntariamente a un empleo, cargo o puesto", "example_phrase": "递交辞职信 (submit a resignation letter)"}], "example_sentences": [{"id": "#1", "hanzi": "他在铁路部门工作了二十年，却为了追逐心中的航海梦想毅然决定辞职。", "pinyin": "Tā zài tiělù bùmén gōngzuò le èrshí nián, què wèile zhuīzhú xīnzhōng de hánghǎi mèngxiǎng yìrán juédìng cízhí.", "en": "Having worked in the railway department for twenty years, he resolutely decided to resign to pursue his dream of oceanic sailing.", "es": "Tras trabajar veinte años en el sector ferroviario, decidió renunciar con firmeza a su empleo para perseguir su sueño de navegar por los mares."}, {"id": "#2", "hanzi": "由于公司组织架构调整，多位高管相继提出辞职，引起了业界内外的广泛关注。", "pinyin": "Yóuyú gōngsī zǔzhī jiàgòu tiáozhěng, duō wèi gāoguǎn xiāngjì tíchū cízhí, yǐnqǐ le yèjiè nèiwài de guǎnfàn guānzhù.", "en": "Owing to organizational restructuring, several senior executives successively tendered their resignations, drawing widespread industry attention.", "es": "Debido a la reestructuración corporativa, varios altos directivos presentaron su dimisión de forma consecutiva, despertando gran expectación en el sector."}], "collocations": [{"hanzi": "辞职信", "en": "resignation letter"}, {"hanzi": "正式辞职", "en": "formally resign"}, {"hanzi": "提出辞职", "en": "submit one's resignation"}, {"hanzi": "决定辞职", "en": "decide to quit"}, {"hanzi": "被迫辞职", "en": "be forced to resign"}, {"hanzi": "辞职报告", "en": "resignation report / application"}], "idioms": [{"hanzi": "挂冠求去", "pinyin": "guà guān qiú qù", "meaning_en": "hang up one's official cap and seek retirement; resign from government office"}, {"hanzi": "解甲归田", "pinyin": "jiě jiǎ guī tián", "meaning_en": "take off armor and return to farmland; retire from military/service"}, {"hanzi": "各司其职", "pinyin": "gè sī qí zhí", "meaning_en": "each performs their respective duties"}, {"hanzi": "恪尽职守", "pinyin": "kè jìn zhí shǒu", "meaning_en": "scrupulously abide by one's duties"}], "character_decomposition": [{"character": "辞", "pinyin": "cí", "meaning_en": "words; bid farewell; resign", "meaning_es": "palabras; despedirse; renunciar", "radical": "舌", "radical_meaning_en": "tongue / speech", "meaning_component": "辛 (toil or punishment)", "sound_component": "司 / 舌 (words uttered in court or declaration)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "In ancient legal courts, uttering formal declarations (舌) regarding grievances or official departure.", "visual_mnemonic_story_en": "Taking the floor to utter parting words (舌) as you hand over painful labor (辛) to move on.", "visual_mnemonic_story_es": "Tomar la palabra (舌) para pronunciar la despedida formal y desligarse de un arduo deber (辛).", "tone_mnemonic_anchor": "35", "cangjie": "HTSJ", "traditional": "辭"}, {"character": "职", "pinyin": "zhí", "meaning_en": "duty; job; office", "meaning_es": "cargo; puesto; oficio", "radical": "耳", "radical_meaning_en": "ear / listen", "meaning_component": "耳 (ears listening attentively to orders)", "sound_component": "只 (zhǐ phonetic / capture)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: ears (耳) listening diligently to official commands and organizational responsibilities.", "visual_mnemonic_story_en": "A dutiful employee listening with focused ears (耳) to execute professional tasks faithfully (只).", "visual_mnemonic_story_es": "Un empleado aplicado que escucha con atención (耳) las directrices para cumplir cabalmente con su cometido (只).", "tone_mnemonic_anchor": "35", "cangjie": "SJRC", "traditional": "職"}], "extended_reading_passages": [{"id": "#1", "hanzi": "递交辞职信的那一刻，他感到一种前所未有的释怀。体制内的稳定与保障曾是他赖以生存的防线，但也悄悄禁锢了他的脚步。人生的真正意义不在于原地等待岁月的流逝，而在于勇敢地推开未知的大门。", "pinyin": "Dìjiāo cízhíxìn de nà yí kè, tā gǎndào yì zhǒng qiánsuǒwèiyǒu de shìhuái. Tǐzhì nèi de wěndìng yǔ bǎozhàng céng shì tā làiyǐ shēngcún de fángxiàn, dàn yě qiāoqiāo jìngù le tā de jiǎobù. Rénshēng de zhēnzhèng yìyì bú zàiyú yuándì děngdài suìyuè de liúshì, ér zàiyú yǒnggǎn de tuīkāi wèizhī de dàmén.", "en": "Handing in his resignation, he felt an unprecedented sense of release. Institutional stability had long been his shield, yet it quietly caged his spirit. Life's true significance lies not in idling away years, but in daring to push open unknown gates.", "es": "Al entregar su carta de renuncia sintió un alivio sin precedentes. La estabilidad institucional había sido su trinchera, pero también enjaulaba sus alas. El sentido de la vida no reside en aguardar el paso de los años, sino en empujar con valor las puertas de lo desconocido."}, {"id": "#2", "hanzi": "劳动力市场监测数据显示，随着青年就业观念的多元化转变，知识密集型行业的离职与辞职流动率呈现上升趋势。新生代专业人才更加看重个人价值的实现空间与工作生活平衡，这对现代企业的组织韧性与雇主品牌建设提出了更高要求。", "pinyin": "Láodònglì shìchǎng jiāncè shùjù biǎomíng, suízhe qīngnián jiùyè guānniàn de duōyuánhuà zhuǎnbiàn, zhīshi mìjíxíng hángyè de lízhí yǔ cízhí liúdònglǜ chéngxiàn shàngshēng qūshì. Xīnshēngdài zhuānyè réncái gèngjiā kànzhòng gèrén jiàzhí de shíxiàn kōngjiān yǔ gōngzuò shēnghuó pínghéng, zhè duì xiàndài qǐyè de zǔzhī rènxìng yǔ gùzhǔ pǐnpái jiànshè tíchū le gèng gāo yāoqiú.", "en": "Labor market data indicates that shifting youth employment values have raised voluntary resignation and turnover rates across knowledge-intensive sectors. Young professionals prioritize personal self-fulfillment and work-life balance, demanding organizational agility from modern corporate employers.", "es": "Los estudios laborales indican que el cambio de valores profesionales entre los jóvenes ha elevado las dimisiones en sectores de alta cualificación. El talento emergente prima la autorrealización y la conciliación, lo que exige a las empresas mayor flexibilidad organizativa y reputación laboral."}]}, {"meanings_summary": {"en": "treatment; reception; compensation; salary and perks", "es": "trato; retribución; remuneración; condiciones laborales"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The manner in which you are received (待) when you encounter (遇) life's circumstances defines your treatment and compensation (待遇).", "composite_memory_hook_es": "El modo en que te reciben (待) cuando te cruzas con las circunstancias (遇) define tu trato y retribución (待遇).", "cultural_and_cognitive_roots": "In ancient statecraft, '待' signified how sovereigns treated scholars (礼贤), while '遇' signified finding an appreciative monarch (知遇之恩). In modern times, it evolved to represent fair remuneration and working conditions.", "tone_sandhi_and_pitch_modulation": "Two consecutive falling 4th tones: dài yù (51-51). Pronounce each syllable with firm, descending pitch, giving equal weight to both."}, "semantic_boundary_contrasts": {"core_nuance": "待遇 spans both monetary compensation (pay, perks) and interpersonal or social treatment accorded to individuals.", "contrasts": [{"id": "1", "compared_word": "待遇 vs. 薪酬", "pinyin": "xīnchóu", "analysis": "薪酬 refers strictly to financial remuneration (salaries, wages, bonuses), whereas 待遇 is broader, incorporating health insurance, housing benefits, social prestige, and interpersonal courtesies."}, {"id": "2", "compared_word": "待遇 vs. 态度", "pinyin": "tàidù", "analysis": "待遇 refers to concrete tangible conditions or institutional treatment provided, while 态度 reflects the subjective emotional disposition or manner exhibited toward someone."}, {"id": "3", "compared_word": "待遇 vs. 报酬", "pinyin": "bàochóu", "analysis": "待遇 focuses on systematic, ongoing employee welfare packages, whereas 报酬 emphasizes direct remuneration paid for specific tasks or services rendered."}]}, "traps_and_cognates": {"look_alikes": [{"character": "待", "pinyin": "dài", "meaning_en": "treat; wait", "distinction_note": "Has 彳 (step) radical on the left and 寺 on the right"}, {"character": "侍", "pinyin": "shì", "meaning_en": "serve; attend upon", "distinction_note": "Has 亻 (person) radical on the left with 寺"}, {"character": "遇", "pinyin": "yù", "meaning_en": "meet; encounter", "distinction_note": "Has 辶 (walk) radical enclosing 禺"}, {"character": "偶", "pinyin": "ǒu", "meaning_en": "accidental; idol", "distinction_note": "Has 亻 (person) radical on the left with 禺"}], "etymological_cognates": [{"character": "对待", "pinyin": "duì dài", "gloss_en": "treat; deal with; adopt attitude toward"}, {"character": "招待", "pinyin": "zhāo dài", "gloss_en": "entertain; receive guests"}, {"character": "遇见", "pinyin": "yù jiàn", "gloss_en": "meet; run into"}, {"character": "遭遇", "pinyin": "zāo yù", "gloss_en": "encounter; run up against (hardship)"}]}, "id": "9", "hanzi": "待遇", "pinyin": "dài yù", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "remuneration, salary, benefits, and welfare received from employment", "definition_es": "remuneración, sueldo, beneficios sociales y prestaciones laborales", "example_phrase": "工资待遇 (salary and compensation)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "treatment, reception, or manner of dealing with individuals", "definition_es": "trato, acogida o consideración dispensada a alguien", "example_phrase": "享受特殊待遇 (enjoy special treatment)"}], "example_sentences": [{"id": "#1", "hanzi": "尽管原单位提供了优厚的薪酬待遇，但他依然选择放弃，投身到充满未知的远洋探险中。", "pinyin": "Jǐnguǎn yuándānwèi tígōng le yōuhòu de xīnchóu dàiyù, dàn tā yīrán xuǎnzé fàngqì, tóushēn dào chōngmǎn wèizhī de yuǎnyáng tànxiǎn zhōng.", "en": "Although his former employer provided generous pay and perks, he still chose to give them up and plunge into the ocean adventure.", "es": "Pese a que su anterior empresa le ofrecía una retribución generosa, decidió renunciar a ella para consagrarse a la aventura oceánica."}, {"id": "#2", "hanzi": "为了招揽顶尖科技研发人才，该创新园区为入驻专家提供了涵盖安居补贴与科研经费的全方位保障待遇。", "pinyin": "Wèile zhāolǎn dǐngjiān kējì yánfā réncái, gāi chuàngxīn yuánqū wèi rùzhù zhuānjiā tígōng le hángài ānjū bǔtiē yǔ kēyán jīngfèi de quánfāngwèi bǎozhàng dàiyù.", "en": "To attract top technological research talent, the innovation park offered resident experts comprehensive welfare, including housing subsidies and research funding.", "es": "A fin de atraer talentos de investigación punteros, el parque tecnológico ofreció a los expertos un completo paquete de remuneración con ayudas de vivienda y fondos."}], "collocations": [{"hanzi": "福利待遇", "en": "welfare benefits and perks"}, {"hanzi": "优厚待遇", "en": "generous compensation"}, {"hanzi": "工资待遇", "en": "salary and wage treatment"}, {"hanzi": "享受待遇", "en": "enjoy benefits / treatment"}, {"hanzi": "平等待遇", "en": "equal treatment"}, {"hanzi": "特别待遇", "en": "special treatment / privileged status"}], "idioms": [{"hanzi": "礼贤下士", "pinyin": "lǐ xián xià shì", "meaning_en": "treat worthy men of talent with courtesy and respect"}, {"hanzi": "一视同仁", "pinyin": "yí shì tóng rén", "meaning_en": "treat everyone equally without discrimination"}, {"hanzi": "待价而沽", "pinyin": "dài jià ér gū", "meaning_en": "wait for the right price to sell; await the right opportunity"}, {"hanzi": "待人接物", "pinyin": "dài rén jiē wù", "meaning_en": "manner of treating people and conducting oneself in society"}], "character_decomposition": [{"character": "待", "pinyin": "dài", "meaning_en": "treat; await; attend", "meaning_es": "tratar; esperar; atender", "radical": "彳", "radical_meaning_en": "step / walk slowly", "meaning_component": "彳 (interpersonal interaction or stride)", "sound_component": "寺 (sì phonetic / hall of service or measure)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: stepping up (彳) to an official hall (寺) to wait upon or receive guests courteously.", "visual_mnemonic_story_en": "Stepping forward respectfully (彳) into a grand reception hall (寺) to await and welcome honored visitors.", "visual_mnemonic_story_es": "Avanzar con respeto (彳) hacia el salón de recepción (寺) para atender y hospedar con esmero a los visitantes.", "tone_mnemonic_anchor": "51", "cangjie": "HOODI", "traditional": ""}, {"character": "遇", "pinyin": "yù", "meaning_en": "meet; encounter; opportunity", "meaning_es": "encontrar; toparse; trato", "radical": "辶", "radical_meaning_en": "walk / motion", "meaning_component": "辶 (advancing along a path)", "sound_component": "禺 (yù phonetic / corner or monkey ideogram)", "stroke_count": "12", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ideogrammic/phono-semantic compound: walking along a path (辶) and unexpectedly crossing paths with an acquaintance (禺).", "visual_mnemonic_story_en": "Walking briskly down an intersection (辶) and unexpectedly meeting (禺) an auspicious opportunity.", "visual_mnemonic_story_es": "Caminar por un sendero (辶) y toparse inesperadamente (禺) con una persona o coyuntura propicia.", "tone_mnemonic_anchor": "51", "cangjie": "YWLB", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "很多人终其一生都在追求更高的薪水与更体面的社会待遇，却往往忽略了内心真正的渴望。物质上的丰厚固然能带来短暂的欢愉，但唯有做自己真正热爱的事业，才能在灵魂深处获得长久的满足与安宁。", "pinyin": "Hěnduō rén zhōng qí yìshēng dōu zài zhuīqiú gèng gāo de xīnshuǐ yǔ gèng tǐmiàn de shèhuì dàiyù, què wǎngwǎng hūlüè le nèixīn zhēnzhèng de kěwàng. Wùzhì shàng de fēnghòu gùrán néng dài lái duǎnzàn de huányú, dàn wéiyǒu zuò zìjǐ zhēnzhèng rè'ài de shìyè, cáinéng zài línghún shēnchù huòdé chángjiǔ de mǎnzú yǔ ānníng.", "en": "Many spend their entire lives chasing higher wages and respectable treatment, yet often neglect genuine inner yearnings. While material opulence brings transient pleasure, only pursuing one's true passion delivers enduring solace and soul contentment.", "es": "Muchos consagran su vida a perseguir mejores sueldos y un estatus respetable, olvidando los anhelos del alma. La opulencia material depara dichas efímeras, pero solo entregarse a la verdadera vocación concede paz duradera y plenitud interior."}, {"id": "#2", "hanzi": "在全球高端产业竞争日趋白热化的背景下，企业仅靠提高薪资待遇已难以构建绝对的人才竞争壁垒。现代人力资本管理愈发强调优化职业发展通道、激发团队创造力，通过建立包容协作的组织文化来增强核心员工的归属感与黏性。", "pinyin": "Zài quánqiú gāoduān chǎnyè jìngzhēng rìqū báirèhuà de bèijǐng xià, qǐyè jǐn kào tígāo xīnzī dàiyù yǐ nányǐ gòujiàn juéduì de réncái jìngzhēng bìlěi. Xiàndài rénlì zīběn guǎnlǐ yùfā qiángdiào yōuhuà zhíyè fāzhǎn tōngdào, jīfā tuánduì chuàngzàolì, tōngguò jiànlì bāoróng xiézuò de zǔzhī wénhuà lái zēngqiáng héxīn yuángōng de guīshǔgǎn yǔ niánxìng.", "en": "Amid escalating competition across high-tech sectors, raising salaries and perks alone no longer builds impenetrable talent moats. Modern human capital management emphasizes refining career pathways, sparking innovation, and nurturing inclusive cultures to retain key talent.", "es": "Con la competencia global al rojo vivo, subir sueldos ya no basta para retener talento estratégico. La gestión de personas prima proyectar carreras motivadoras e inspirar creatividad, forjando culturas inclusivas que afiancen el sentido de pertenencia de los profesionales."}]}, {"meanings_summary": {"en": "to worry; to fret; to be anxious about; to be troubled", "es": "preocuparse; afligirse; estar inquieto; atribularse"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When autumn chill descends upon the heart (愁), emotional sighs burst forth (发), leading one to worry and fret (发愁).", "composite_memory_hook_es": "Cuando la nostalgia otoñal invade el corazón (愁), brotan los suspiros (发) y uno empieza a preocuparse (发愁).", "cultural_and_cognitive_roots": "In classical Chinese poetic imagery, autumn (秋) and sadness (愁) are inextricably linked: the seasonal decay of vegetation mirrors human anxiety over impermanence, aging, and worldly troubles.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a rising 2nd tone: fā chóu (55-35). Ensure 'fā' remains high before ascending smoothly into 'chóu'."}, "semantic_boundary_contrasts": {"core_nuance": "发愁 emphasizes the ongoing, brooding psychological anxiety caused by practical difficulties or lacking solutions.", "contrasts": [{"id": "1", "compared_word": "发愁 vs. 担心", "pinyin": "dānxīn", "analysis": "发愁 emphasizes being at a loss for how to solve an existing problem (为生活费发愁), whereas 担心 focuses on dreading that an adverse event might occur in the future (担心会下雨)."}, {"id": "2", "compared_word": "发愁 vs. 焦虑", "pinyin": "jiāolǜ", "analysis": "发愁 is an everyday oral expression describing practical fretting, while 焦虑 is a clinical/psychological term denoting deep, chronic emotional angst or agitation."}, {"id": "3", "compared_word": "发愁 vs. 难过", "pinyin": "nánguò", "analysis": "发愁 is directed toward unresolved hurdles and decisions, whereas 难过 expresses emotional sadness and heartache after a misfortune has already occurred."}]}, "traps_and_cognates": {"look_alikes": [{"character": "发", "pinyin": "fā", "meaning_en": "emit; hair", "distinction_note": "Five strokes with a diagonal slash and dot"}, {"character": "友", "pinyin": "yǒu", "meaning_en": "friend", "distinction_note": "Has 十 under top horizontal stroke without the dot"}, {"character": "愁", "pinyin": "chóu", "meaning_en": "worry; sad", "distinction_note": "Has 秋 on top and 心 (heart) at the bottom"}, {"character": "悉", "pinyin": "xī", "meaning_en": "know; all", "distinction_note": "Has 釆 on top and 心 at the bottom"}], "etymological_cognates": [{"character": "忧愁", "pinyin": "yōu chóu", "gloss_en": "worried; depressed; sorrowful"}, {"character": "愁苦", "pinyin": "chóu kǔ", "gloss_en": "distressed and miserable"}, {"character": "发火", "pinyin": "fā huǒ", "gloss_en": "get angry; lose temper"}, {"character": "发现", "pinyin": "fā xiàn", "gloss_en": "discover; find out"}]}, "id": "10", "hanzi": "发愁", "pinyin": "fā chóu", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to feel worried, burdened, or distressed about difficulties or uncertainty", "definition_es": "sentir preocupación, agobio o desazón ante dificultades o incertidumbre", "example_phrase": "为学费发愁 (worry about tuition fees)"}], "example_sentences": [{"id": "#1", "hanzi": "面对航行中淡水短缺和食物不足的严峻现实，全家人虽然发愁，但依然相互鼓励咬牙坚持。", "pinyin": "Miànduì hángxíng zhōng dànshuǐ duǎnquē hé shíwù bùzú de yánjùn xiànshí, quán jiārén suīrán fāchóu, dàn yīrán xiānghù gǔlì yǎoyá jiānchí.", "en": "Confronted with severe water shortages and dwindling food during the voyage, the family worried, yet encouraged each other to persevere.", "es": "Ante la escasez de agua dulce y víveres en plena travesía, la familia no pudo evitar afligirse, pero se animó mutuamente a resistir con entereza."}, {"id": "#2", "hanzi": "许多应届大学毕业生正在为找工作发愁，而职业规划导师建议他们拓宽思路，多尝试新兴业态。", "pinyin": "Xǔduō yīngjiè dàxué bìyèshēng zhèngzài wèi zhǎo gōngzuò fāchóu, ér zhíyè guīhuà dǎoshī jiànyì tāmen tuòkuān sīlù, duō chángshì xīnxīng yètài.", "en": "Many recent college graduates are fretting over job searches, while career mentors advise broadening horizons and trying emerging industries.", "es": "Muchos recién graduados universitarios se angustian buscando trabajo, mientras los orientadores laborales sugieren abrir la mente a nuevas industrias emergentes."}], "collocations": [{"hanzi": "为……发愁", "en": "worry about / fret over"}, {"hanzi": "不用发愁", "en": "no need to worry"}, {"hanzi": "令人发愁", "en": "make someone anxious; worrisome"}, {"hanzi": "暗自发愁", "en": "fret in secret"}, {"hanzi": "发愁叹气", "en": "fret and sigh"}, {"hanzi": "为钱发愁", "en": "worry about money"}], "idioms": [{"hanzi": "愁眉苦脸", "pinyin": "chóu méi kǔ liǎn", "meaning_en": "wear a worried frown; have a troubled countenance"}, {"hanzi": "借酒消愁", "pinyin": "jiè jiǔ xiāo chóu", "meaning_en": "drown one's sorrows in alcohol"}, {"hanzi": "多愁善感", "pinyin": "duō chóu shàn gǎn", "meaning_en": "prone to melancholy and sentimentality; overly sensitive"}, {"hanzi": "愁云惨雾", "pinyin": "chóu yún cǎn wù", "meaning_en": "gloom of sorrow and distressing clouds; atmosphere of gloom"}], "character_decomposition": [{"character": "发", "pinyin": "fā", "meaning_en": "emit; release; start", "meaning_es": "emitir; soltar; originar", "radical": "又", "radical_meaning_en": "hand / right hand", "meaning_component": "又 (hand releasing an arrow)", "sound_component": "癶 (bō / foot step)", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient ideograph of drawing a bow and releasing an arrow forward, extended to venting feelings outward.", "visual_mnemonic_story_en": "An archer's hand releasing an arrow (发) sending emotions bursting outward into the open.", "visual_mnemonic_story_es": "La mano del arquero que suelta la flecha (发), desatando las emociones contenidas hacia el exterior.", "tone_mnemonic_anchor": "55", "cangjie": "IVE", "traditional": "發"}, {"character": "愁", "pinyin": "chóu", "meaning_en": "worry; anxiety; gloom", "meaning_es": "preocupación; tristeza; desazón", "radical": "心", "radical_meaning_en": "heart / emotion", "meaning_component": "心 (the human heart and seat of emotions)", "sound_component": "秋 (qiū phonetic / autumn, season of fading leaves)", "stroke_count": "13", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound: autumn chill (秋) weighing heavy upon the sensitive heart (心), evoking sorrow and anxiety.", "visual_mnemonic_story_en": "As autumn winds (秋) strip the trees, a heavy chill settles upon your tender heart (心), stirring anxiety.", "visual_mnemonic_story_es": "Cuando el frío del otoño (秋) marchita las hojas, una nube de inquietud oprime el corazón (心).", "tone_mnemonic_anchor": "35", "cangjie": "HFP", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "生活中的许多烦恼，往往源于我们对未来的过度预设。与其为了明天的风浪暗自发愁，不如握紧当下的船桨，认真划好脚下的每一道水波。风雨终会过去，而勇敢行动的人永远不会被困境击倒。", "pinyin": "Shēnghuó zhōng de xǔduō fánnǎo, wǎngwǎng yuányú wǒmen duì wèilái de guòdù yùshè. Yǔqí wèile míngtiān de fēnglàng ànzì fāchóu, bùrú wòjǐn dāngxià de chuánjiǎng, rènzhēn huà hǎo jiǎoxià de měi yí dào shuǐbō. Fēngyǔ zhōng huì guòqù, ér yǒnggǎn xíngdòng de rén yǒngyuǎn bú huì bèi kùnjìng jīdǎo.", "en": "Many troubles stem from excessively fretting over hypothetical futures. Rather than worrying about tomorrow's squalls, we do better gripping present oars to stroke each passing wave. Tempests pass; the brave are never crushed by plight.", "es": "Muchas zozobras nacen de anticipar en exceso el porvenir. En vez de angustiarse por las tempestades del mañana, conviene empuñar los remos del presente y surcar cada ola con tesón. La tormenta pasará y quien actúa jamás sucumbe ante la adversidad."}, {"id": "#2", "hanzi": "消费心理学研究指出，面对宏观不确定性，居民更容易因预期收入波动而为家庭收支平衡发愁，从而引发防御性储蓄行为。建立多层次社会兜底救助机制与普惠金融体系，是平复公众焦虑心态、释放内需消费活力的重要制度保障。", "pinyin": "Xiāofèi xīnlǐxué yánjiū zhǐchū, miànduì hóngguān bùquèdìngxìng, jūmín gèng róngyì yīn yùqī shōurù bōdòng ér wèi jiātíng shōuzhī pínghéng fāchóu, cóng'ér yǐnfā fángyùxìng chǔxù xíngwéi. Jiànlì duōcéngcì shèhuì dōudǐ jiùzhù jīzhì yǔ pǔhuì jīnróng tǐxì, shì píngfù gōngzhòng jiāolǜ xīntài, shìfàng nèixū xiāofèi huólì de zhòngyào zhìdù bǎozhàng.", "en": "Studies in consumer psychology reveal that macroeconomic uncertainty prompts families to worry over household budgets, spurring defensive saving. Multi-tiered social safety nets and inclusive finance remain vital institutional buffers to soothe public anxieties and unleash domestic demand.", "es": "La psicología del consumo indica que ante la incertidumbre económica las familias se angustian por cuadrar el presupuesto doméstico, refugiándose en el ahorro preventivo. Robustecer la red de protección social y las finanzas inclusivas resulta decisivo para apaciguar el desasosiego popular."}]}, {"meanings_summary": {"en": "calm; peaceful; tranquil; serene; quiet", "es": "tranquilo; en calma; sereno; apacible; sosegado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When life's balance becomes level (平) and outer struggles quiet down (静), a deep inner stillness emerges (平静).", "composite_memory_hook_es": "Cuando la vida recupera el equilibrio llano (平) y las disputas callan (静), florece una profunda calma (平静).", "cultural_and_cognitive_roots": "Traditional Chinese philosophy views tranquility as water returning to a level mirror ('静水流深'). Serenity is not emptiness, but internal harmony unruffled by fleeting external winds.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone followed by a falling 4th tone: píng jìng (35-51). Articulate 'píng' smoothly upward before bringing 'jìng' firmly downward."}, "semantic_boundary_contrasts": {"core_nuance": "平静 describes the cessation of turbulent waves, commotion, or emotional agitation, restoring natural stillness.", "contrasts": [{"id": "1", "compared_word": "平静 vs. 安静", "pinyin": "ānjìng", "analysis": "平静 highlights the absence of internal turmoil, emotional agitation, or oceanic turbulence (心情平静, 海面平静), while 安静 focuses on the absence of sound or audible noise (请大家安静)."}, {"id": "2", "compared_word": "平静 vs. 宁静", "pinyin": "níngjìng", "analysis": "平静 describes recovering composure after a disturbance, whereas 宁静 evokes poetic, idyllic, and solemn serenity in natural landscapes or meditative states (宁静的夜晚)."}, {"id": "3", "compared_word": "平静 vs. 冷静", "pinyin": "lěngjìng", "analysis": "平静 reflects emotional peace and freedom from anxiety, while 冷静 emphasizes rational, analytical thinking and maintaining cool logic under high pressure."}]}, "traps_and_cognates": {"look_alikes": [{"character": "平", "pinyin": "píng", "meaning_en": "flat; peaceful", "distinction_note": "Single vertical stroke centered between two dots"}, {"character": "苹", "pinyin": "píng", "meaning_en": "apple", "distinction_note": "Has 艹 (grass) radical on top of 平"}, {"character": "静", "pinyin": "jìng", "meaning_en": "quiet; silent", "distinction_note": "Has 青 on the left and 争 on the right"}, {"character": "净", "pinyin": "jìng", "meaning_en": "clean; pure", "distinction_note": "Has 冫 (ice) radical on the left with 争"}], "etymological_cognates": [{"character": "平时", "pinyin": "píng shí", "gloss_en": "peacetime; ordinarily; at normal times"}, {"character": "平安", "pinyin": "píng ān", "gloss_en": "safe and sound; peaceful"}, {"character": "安静", "pinyin": "ān jìng", "gloss_en": "quiet; peaceful; silent"}, {"character": "宁静", "pinyin": "níng jìng", "gloss_en": "tranquil; serene; placid"}]}, "id": "11", "hanzi": "平静", "pinyin": "píng jìng", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "undisturbed, peaceful, and free from agitation (describing mood, mind, or expressions)", "definition_es": "tranquilo; sosegado; sereno en el ánimo o la expresión", "example_phrase": "心情平静 (calm and peaceful state of mind)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "smooth, still, and without waves or disturbances (describing water, sea, or atmosphere)", "definition_es": "en calma; apacible; sin oleaje ni alboroto", "example_phrase": "海面平静 (the sea surface is calm)"}], "example_sentences": [{"id": "#1", "hanzi": "暴风雨终于停歇，蔚蓝的大海重新恢复了平静，帆船在柔和的阳光下缓缓滑行。", "pinyin": "Bàofēngyǔ zhōngyú tíngxiē, wèilán de dàhǎi chóngxīn huìfù le píngjìng, fānchuán zài róuhé de yángguāng xià huǎnhuǎn huáxíng.", "en": "The storm finally subsided, the azure ocean regained its tranquility, and the sailboat glided gently beneath the soft sunlight.", "es": "La tempestad amainó por fin, el mar azul recobró la calma y el velero se deslizó suavemente bajo la tenue luz del sol."}, {"id": "#2", "hanzi": "面对突发的市场公关危机，公司发言人以异常平静的语调客观陈述事实，迅速稳定了舆论走向。", "pinyin": "Miànduì tūfā de shìchǎng gōngguān wēijī, gōngsī fāyánrén yǐ yìcháng píngjìng de yǔdiào kèguān chénshù shìshí, xùnsù wěndìng le yúlùn zǒuxiàng.", "en": "Facing a sudden public relations crisis, the company spokesperson presented facts in an unusually calm tone, swiftly steadying public opinion.", "es": "Ante una imprevista crisis de imagen corporativa, el portavoz expuso los hechos con un tono sereno, apaciguando con presteza el rumor público."}], "collocations": [{"hanzi": "心情平静", "en": "peaceful / calm mood"}, {"hanzi": "海面平静", "en": "calm sea surface"}, {"hanzi": "恢复平静", "en": "restore tranquility; calm down"}, {"hanzi": "平静的生活", "en": "peaceful life"}, {"hanzi": "十分平静", "en": "very calm / tranquil"}, {"hanzi": "平静的眼神", "en": "calm gaze / eyes"}], "idioms": [{"hanzi": "心平气和", "pinyin": "xīn píng qì hé", "meaning_en": "calm and even-tempered; serene and composed"}, {"hanzi": "平风静浪", "pinyin": "píng fēng jìng làng", "meaning_en": "calm wind and tranquil waves; peaceful sailing"}, {"hanzi": "风平浪静", "pinyin": "fēng píng làng jìng", "meaning_en": "the wind is calm and the waves are quiet; calm and tranquil"}, {"hanzi": "安之若素", "pinyin": "ān zhī ruò sù", "meaning_en": "bear hardship or change with composure; take things calmly"}], "character_decomposition": [{"character": "平", "pinyin": "píng", "meaning_en": "flat; level; peaceful", "meaning_es": "plano; nivelado; en paz", "radical": "干", "radical_meaning_en": "shield / pestle", "meaning_component": "于 / 丂 (breath spreading out evenly)", "sound_component": "八 (cleaving evenly in half)", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a scale beam or breath exhaled in smooth, balanced equilibrium.", "visual_mnemonic_story_en": "A horizontal level beam (一) perfectly balanced on both sides (八) without tipping.", "visual_mnemonic_story_es": "Una balanza perfectamente horizontal (一) con pesos idénticos a ambos lados (八).", "tone_mnemonic_anchor": "35", "cangjie": "MFI", "traditional": ""}, {"character": "静", "pinyin": "jìng", "meaning_en": "quiet; still; calm", "meaning_es": "quieto; silencioso; sereno", "radical": "青", "radical_meaning_en": "blue-green / nature", "meaning_component": "青 (clarity of green waters and clear skies)", "sound_component": "争 (zhèng phonetic / struggle settling down)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: azure clarity (青) subduing conflict and turbulence (争), yielding deep stillness.", "visual_mnemonic_story_en": "Lush emerald nature (青) absorbing all worldly commotion and striving (争) into serene quiet.", "visual_mnemonic_story_es": "El verdor puro de la naturaleza (青) apaciguando cualquier lucha o disputa (争) en un remanso de paz.", "tone_mnemonic_anchor": "51", "cangjie": "QBNS", "traditional": "靜"}], "extended_reading_passages": [{"id": "#1", "hanzi": "走过人生的坎坷波折，才明白最珍贵的莫过于内心的平静。外界的喧嚣与评价宛如掠过海面的季风，只要心底的水域足够深沉，任凭风吹浪打，也无法动摇那份沉稳与澄澈。", "pinyin": "Zǒuguò rénshēng de kǎnkě bōzhé, cái míngbai zuì zhēnguì de mòguòyú nèixīn de píngjìng. Wàijiè de xuānxiāo yǔ píngjià wǎnrú lüèguò hǎimiàn de jìfēng, zhǐyào xīndǐ de shuǐyù zúgòu shēnchén, rènpíng fēngchuīlàngdǎ, yě wúfǎ dòngyáo nà fèn chénwěn yǔ chéngchè.", "en": "Traversing life's jagged turns teaches that nothing surpasses inner tranquility. External clamor and judgments resemble monsoon gusts across the sea; if one's depths run deep enough, no wave can shake that crystalline clarity.", "es": "Superados los escollos del camino se comprende que nada supera la paz del corazón. El ruido ajeno es como el monzón sobre el mar: si las aguas interiores son hondas, ningún temporal perturbará su firmeza y limpidez."}, {"id": "#2", "hanzi": "现代认知心理学指出，长期高压环境会导致自主神经系统紊乱，而练习正念呼吸有助于个体在剧烈的情绪波动后迅速回归平静。保持自主神经系统的平衡状态，不仅能有效降低皮质醇水平，还能显著提高复杂决策环境下的抗压韧性。", "pinyin": "Xiàndài rènzhī xīnlǐxué zhǐchū, chángqī gāoyā huánjìng huì dǎozhì zìzhǔ shénjīng xìtǒng wěnluàn, ér liànxí zhèngniàn hūxī yǒuzhùyú gètǐ zài jùliè de qíngxù bōdòng hòu xùnsù huíguī píngjìng. Bǎochí zìzhǔ shénjīng xìtǒng de pínghéng zhuàngtài, bùjǐn néng yǒuxiào jiàngdī pízìchún shuǐpíng, hái néng xiǎnzhù tígāo fùzá juécè huánjìng xià de kàngyā rènxìng.", "en": "Cognitive psychology notes that chronic stress dysregulates the autonomic nervous system, whereas mindfulness breathing aids rapid return to calm after emotional shocks. Maintaining neural equilibrium curbs cortisol levels and fortifies resilience during complex decision-making.", "es": "La psicología cognitiva demuestra que el estrés crónico desajusta el sistema nervioso, mientras la atención plena ayuda a recobrar la calma tras crisis emocionales. Preservar el equilibrio neurovegetativo reduce el cortisol y apuntala la templanza para tomar decisiones complejas."}]}, {"meanings_summary": {"en": "savings; accumulated funds; to accumulate; to store up", "es": "ahorros; fondos acumulados; ahorrar; atesorar"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Stacking harvested grain (积) and storing livestock fodder (蓄) builds up a household's hard-earned savings (积蓄).", "composite_memory_hook_es": "Apilar el cereal cosechado (积) y almacenar forraje para el ganado (蓄) forma el fruto paciente de los ahorros (积蓄).", "cultural_and_cognitive_roots": "In ancient Chinese agricultural society, thrift and storing grain reserves for famine years ('丰年积蓄以防荒年') stood as the paramount virtue ensuring familial survival against unpredictable floods and droughts.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a falling 4th tone: jī xù (55-51). Articulate 'jī' with clear horizontal pitch before delivering 'xù' downward firmly."}, "semantic_boundary_contrasts": {"core_nuance": "积蓄 emphasizes the gradual, disciplined accumulation of money or energy over an extended duration.", "contrasts": [{"id": "1", "compared_word": "积蓄 vs. 储蓄", "pinyin": "chǔxù", "analysis": "积蓄 functions primarily as a noun referring to the total nest egg or saved wealth accumulated over time (花掉积蓄), whereas 储蓄 emphasizes the financial act or banking system of depositing money (储蓄银行, 储蓄业务)."}, {"id": "2", "compared_word": "积蓄 vs. 存款", "pinyin": "cúnkuǎn", "analysis": "积蓄 refers to total accumulated wealth across all assets, while 存款 refers specifically to cash held in bank deposit accounts."}, {"id": "3", "compared_word": "积蓄 vs. 财富", "pinyin": "cáifù", "analysis": "积蓄 denotes modest personal savings built through frugal labor, whereas 财富 encompasses broad, substantial riches, assets, and prosperity."}]}, "traps_and_cognates": {"look_alikes": [{"character": "积", "pinyin": "jī", "meaning_en": "accumulate; gather", "distinction_note": "Has 禾 (grain) on the left and 只 on the right"}, {"character": "和", "pinyin": "hé", "meaning_en": "harmonious; with", "distinction_note": "Has 禾 on the left and 口 (mouth) on the right"}, {"character": "蓄", "pinyin": "xù", "meaning_en": "store up; hoard", "distinction_note": "Has 艹 on top and 畜 at the bottom"}, {"character": "畜", "pinyin": "chù", "meaning_en": "livestock; domestic animal", "distinction_note": "Lacks the 艹 (grass) radical on top"}], "etymological_cognates": [{"character": "积极", "pinyin": "jī jí", "gloss_en": "positive; active; energetic"}, {"character": "积累", "pinyin": "jī lěi", "gloss_en": "accumulate; amass; gather"}, {"character": "储蓄", "pinyin": "chǔ xù", "gloss_en": "deposit; savings; bank savings"}, {"character": "蓄水", "pinyin": "xù shuǐ", "gloss_en": "water storage; impound water"}]}, "id": "12", "hanzi": "积蓄", "pinyin": "jī xù", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "money or resources accumulated and saved over a prolonged period", "definition_es": "ahorros acumulados o capital guardado a lo largo del tiempo", "example_phrase": "花光所有积蓄 (spend all one's savings)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to accumulate, store up, or save gradually (wealth, energy, strength)", "definition_es": "acumular, almacenar o atesorar gradualmente", "example_phrase": "积蓄力量 (gather and build up strength)"}], "example_sentences": [{"id": "#1", "hanzi": "为了圆全家人的航海梦想，翟峰拿出了工作半辈子积累下来的全部积蓄，买下了那艘帆船。", "pinyin": "Wèile yuán quán jiārén de hánghǎi mèngxiǎng, Zhái Fēng ná chū le gōngzuò bàn bèizi jīlěi xiàlái de quánbù jīxù, mǎi xià le nà sōu fānchuán.", "en": "To realize his family's sailing dream, Zhai Feng gathered all the savings accumulated over half a lifetime of work to purchase that sailboat.", "es": "Para hacer realidad el sueño marinero de su familia, Zhai Feng reunió todos los ahorros de media vida de trabajo y adquirió aquel velero."}, {"id": "#2", "hanzi": "面对突发的国际公共卫生事件，深厚的企业资本积蓄帮助该制造集团成功渡过了订单缩水的最艰难阶段。", "pinyin": "Miànduì tūfā de guójì gōnggòng wèishēng shìjiàn, shēnhòu de qǐyè zīběn jīxù bāngzhù gāi zhìzào jítuán chénggōng dùguò le dìngdān suōshuǐ de zuì jiānnán jiēduàn.", "en": "Confronted with sudden international public health emergencies, deep corporate capital reserves carried the manufacturing group through severe order contractions.", "es": "Ante una imprevista emergencia sanitaria internacional, los cuantiosos fondos de reserva ayudaron a la corporación industrial a capear la brusca caída de pedidos."}], "collocations": [{"hanzi": "多年积蓄", "en": "savings of many years"}, {"hanzi": "花光积蓄", "en": "spend all one's savings"}, {"hanzi": "微薄的积蓄", "en": "meager savings"}, {"hanzi": "积蓄力量", "en": "build up strength / reserves"}, {"hanzi": "一生积蓄", "en": "a lifetime of savings"}, {"hanzi": "动用积蓄", "en": "draw on one's savings"}], "idioms": [{"hanzi": "积少成多", "pinyin": "jī shǎo chéng duō", "meaning_en": "small sums add up to a tidy sum; many a little makes a mickle"}, {"hanzi": "日积月累", "pinyin": "rì jī yuè lěi", "meaning_en": "accumulate day by day and month by month; over time"}, {"hanzi": "厚积薄发", "pinyin": "hòu jī bó fā", "meaning_en": "amass deeply and release with control; prepare extensively before bursting forth"}, {"hanzi": "积劳成疾", "pinyin": "jī láo chéng jí", "meaning_en": "break down from accumulated overwork"}], "character_decomposition": [{"character": "积", "pinyin": "jī", "meaning_en": "accumulate; pile up", "meaning_es": "acumular; apilar; amontonar", "radical": "禾", "radical_meaning_en": "grain / crop", "meaning_component": "禾 (grain crops piled high in barns)", "sound_component": "只 (zhī phonetic / single bundle)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: stalks of harvested grain (禾) gradually stacked together into substantial mounds.", "visual_mnemonic_story_en": "Bundles of ripe grain (禾) piled patiently one by one into an abundant harvest stack (积).", "visual_mnemonic_story_es": "Gavillas de cereal maduro (禾) apiladas con paciencia una a una hasta formar una abundante cosecha (积).", "tone_mnemonic_anchor": "55", "cangjie": "HDRC", "traditional": "積"}, {"character": "蓄", "pinyin": "xù", "meaning_en": "store up; save; cherish", "meaning_es": "almacenar; atesorar; guardar", "radical": "艹", "radical_meaning_en": "grass / vegetation", "meaning_component": "艹 (hay and forage preserved for livestock)", "sound_component": "畜 (chù / livestock and pen)", "stroke_count": "13", "composition_type": "上下结构", "etymology_and_mnemonic": "Ideogrammic compound: gathering grass and fodder (艹) into storage to feed livestock (畜) through winter.", "visual_mnemonic_story_en": "Cutting and storing sweet grass (艹) in winter pens to feed livestock (畜) and preserve wealth.", "visual_mnemonic_story_es": "Cortar y almacenar forraje fresco (艹) en los corrales de ganado (畜) para subsistir al invierno y conservar capital.", "tone_mnemonic_anchor": "51", "cangjie": "TYVI", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "父母那一辈人的存折里，藏着他们一生勤俭节约的积蓄。每一笔微小的存入，都记录着他们对抗生活风雨的坚韧。对于他们而言，积蓄不仅是安身立命的保障，更是留给子女最深沉、最无私的爱。", "pinyin": "Fùmǔ nà yí bèi rén de cúnzhé lǐ, cáng zhe tāmen yìshēng qínjiǎnjiéyuē de jīxù. Měi yì bǐ wēixiǎo de cúnrù, dōu jìlù zhe tāmen duìkàng shēnghuó fēngyǔ de jiānrèn. Duìyú tāmen éryán, jīxù bùjǐn shì ānshēnlìmìng de bǎozhàng, gèng shì liú gěi zǐnǚ zuì shēnchén, zuì wúsī de ài.", "en": "Within our parents' bankbooks lie the frugal savings of a lifetime. Every modest deposit recorded their fortitude against life's bitter storms. To them, savings represented not only security, but profound, selfless love bequeathed to their children.", "es": "En las libretas bancarias de nuestros padres descansan los ahorros pacientes de toda una vida frugal. Cada modesto ingreso plasmaba su tesón ante los embates de la vida. Para ellos, ahorrar no era solo un resguardo, sino un acto de amor puro hacia sus hijos."}, {"id": "#2", "hanzi": "金融数据显示，居民家庭积蓄为经济建设提供了坚实的资金后盾。在新发展格局下，如何引导居民庞大的预防性积蓄转化为有效消费内需，已成为当前宏观经济调控的重要着力点。", "pinyin": "Jīnróng shùjù xiǎnshì, jūmín jiātíng jīxù wèi jīngjì jiànshè tígōng le jiānshí de zījīn hòudùn. Zài xīn fāzhǎn gégjú xià, rúhé yǐndǎo jūmín pángdà de yùfángxìng jīxù zhuǎnhuà wéi yǒuxiào xiāofèi nèixū, yǐ chéngwéi dāngqián hóngguān jīngjì tiáokòng de zhòngyào zhuólìdiǎn.", "en": "Financial data shows household savings provide a firm financial bedrock for economic construction. Under modern models, guiding vast precautionary savings into domestic consumption forms a crucial macroeconomic priority.", "es": "Las finanzas constatan que el ahorro familiar constituye un sólido respaldo económico. Orientar esos fondos de reserva preventivos hacia el consumo interno es hoy un reto clave de la política económica."}]}, {"meanings_summary": {"en": "to include; to comprise; to consist of; to encompass", "es": "incluir; abarcar; comprender; constar de"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Wrapping everything up in a package (包) and clasping it securely (括) ensures that all essential elements are included (包括).", "composite_memory_hook_es": "Envolverlo todo en un fardo (包) y sujetarlo con la mano (括) garantiza que todo quede incluido (包括).", "cultural_and_cognitive_roots": "Ancient Chinese philosophy valued comprehensive synthesis and holistic thinking ('兼容并包'). The compound '包括' embodies the conceptual metaphor of containment: a conceptual container holding varied parts into an organic unity.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a sharp falling 4th tone: bāo kuò (55-51). Pronounce 'bāo' smoothly and crisply transition downward into 'kuò'."}, "semantic_boundary_contrasts": {"core_nuance": "包括 denotes membership or containment within a collective whole, enumerating components or scope.", "contrasts": [{"id": "1", "compared_word": "包括 vs. 包含", "pinyin": "bāohán", "analysis": "包括 is practical and enumerative, listing tangible components, members, or fees (费用包括早餐), whereas 包含 emphasizes abstract, deeper meanings or emotional undertones (这句话包含深刻的道理)."}, {"id": "2", "compared_word": "包括 vs. 涉及", "pinyin": "shèjí", "analysis": "包括 defines internal membership within a set, while 涉及 describes reaching into, touching upon, or affecting outside domains (这个问题涉及到法律)."}, {"id": "3", "compared_word": "包括 vs. 涵盖", "pinyin": "hángài", "analysis": "包括 is standard everyday and formal vocabulary, whereas 涵盖 is high-level, literary discourse denoting sweeping, overarching coverage (涵盖多个研究领域)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "包", "pinyin": "bāo", "meaning_en": "wrap; bundle", "distinction_note": "Curving wrap enclosing 巳"}, {"character": "句", "pinyin": "jù", "meaning_en": "sentence", "distinction_note": "Encloses 口 (mouth) instead of 巳"}, {"character": "括", "pinyin": "kuò", "meaning_en": "include; bracket", "distinction_note": "Has 扌 (hand) radical on the left and 舌 on the right"}, {"character": "适", "pinyin": "shì", "meaning_en": "suitable; comfortable", "distinction_note": "Has 辶 (walk) radical enclosing 舌"}], "etymological_cognates": [{"character": "包装", "pinyin": "bāo zhuāng", "gloss_en": "pack; package; wrapping"}, {"character": "包含", "pinyin": "bāo hán", "gloss_en": "contain; embody; include"}, {"character": "概括", "pinyin": "gài kuò", "gloss_en": "summarize; generalize"}, {"character": "括号", "pinyin": "kuò hào", "gloss_en": "parenthesis; brackets"}]}, "id": "13", "hanzi": "包括", "pinyin": "bāo kuò", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to contain or encompass as part of a whole or category", "definition_es": "incluir o abarcar como parte integrante de un conjunto", "example_phrase": "包括各种费用 (include various expenses)"}], "example_sentences": [{"id": "#1", "hanzi": "这次跨洋航行的必备物资清单非常庞大，不仅包括充足的淡水与干粮，还涵盖了各类卫星通信设备。", "pinyin": "Zhè cì kuàyáng hángxíng de bìbèi wùzī qīngdān fēicháng pángdà, bùjǐn bāokuò chōngzú de dànshuǐ yǔ gānliáng, hái hángài le gèlèi wèixīng tōngxìn shèbèi.", "en": "The supply checklist for this transoceanic voyage was massive, including not only abundant freshwater and provisions, but various satellite communication devices.", "es": "La lista de provisiones esenciales para esta travesía transoceánica era inmensa, incluyendo agua potable y víveres secos, además de equipos de comunicación satelital."}, {"id": "#2", "hanzi": "该科技孵化器的扶持政策十分全面，包括提供免租办公场地、创业启动资金以及专业的知识产权法务咨询。", "pinyin": "Gāi kējì fūhuàqì de fúchí zhèngcè shífēn quánmiàn, bāokuò tígōng miǎnzū bàngōng chǎngdì, chuàngyè qǐdòng zījīn yǐjí zhuānyè de zhīshi chǎnquán fǎwù zīxún.", "en": "The technology incubator's support policy was comprehensive, including rent-free office spaces, startup capital, and professional intellectual property legal counsel.", "es": "La política de respaldo de la incubadora tecnológica era muy completa, incluyendo oficinas sin alquiler, capital semilla y asesoría legal sobre patentes."}], "collocations": [{"hanzi": "包括在内", "en": "included within; count in"}, {"hanzi": "不包括", "en": "not include; exclude"}, {"hanzi": "主要包括", "en": "mainly consist of; primarily include"}, {"hanzi": "费用包括", "en": "expenses include"}, {"hanzi": "其中包括", "en": "among which are included"}, {"hanzi": "包括以下方面", "en": "include the following aspects"}], "idioms": [{"hanzi": "无所不包", "pinyin": "wú suǒ bù bāo", "meaning_en": "all-inclusive; nothing omitted"}, {"hanzi": "兼收并蓄", "pinyin": "jiān shōu bìng xù", "meaning_en": "incorporate diverse elements; absorb all useful things"}, {"hanzi": "包罗万象", "pinyin": "bāo luó wàn xiàng", "meaning_en": "embrace everything in nature; all-embracing"}, {"hanzi": "囊括其中", "pinyin": "náng kuò qí zhōng", "meaning_en": "gather all into one's bag; encompass entirely"}], "character_decomposition": [{"character": "包", "pinyin": "bāo", "meaning_en": "wrap; pack; bundle", "meaning_es": "envolver; paquete; envoltorio", "radical": "勹", "radical_meaning_en": "wrap / embrace", "meaning_component": "勹 (curving arms wrapping an object)", "sound_component": "巳 (sì / fetus or embryo)", "stroke_count": "5", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ancient pictograph of a mother's womb wrapping and nurturing an unborn child (巳).", "visual_mnemonic_story_en": "Two curved maternal arms (勹) tenderly wrapping and embracing a tiny bundle (巳).", "visual_mnemonic_story_es": "Dos brazos protectores (勹) envolviendo con mimo un bulto tierno (巳).", "tone_mnemonic_anchor": "55", "cangjie": "PFU", "traditional": ""}, {"character": "括", "pinyin": "kuò", "meaning_en": "encompass; enclose; gather", "meaning_es": "abarcar; englobar; sujetar", "radical": "扌", "radical_meaning_en": "hand / action", "meaning_component": "扌 (hand gathering and clasping together)", "sound_component": "舌 (kuò/shé phonetic / draw tight)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: using hands (扌) to bundle and tie up loose items within boundaries (舌).", "visual_mnemonic_story_en": "A firm hand (扌) drawing an open cord tight around bundled items to encompass them all (舌).", "visual_mnemonic_story_es": "Una mano firme (扌) anudando la cuerda de un saco para englobarlo todo dentro (舌).", "tone_mnemonic_anchor": "51", "cangjie": "QHR", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "真正的生活从不只有眼前的繁琐，还包括对远方星空的凝望与探索。人生的旅途就像一本厚重的书，既包括欢笑与收获的章节，也包括泪水与挫折的考验。只有接纳全部的经历，生命才算真正完整。", "pinyin": "Zhēnzhèng de shēnghuó cóngbù zhǐyǒu yǎnqián de fánsuǒ, hái bāokuò duì yuǎnfāng xīngkōng de níngwàng yǔ tànsuǒ. Rénshēng de lǚtú jiù xiàng yì běn hòuzhòng de shū, jì bāokuò huānxiào yǔ shōuhuò de zhāngjié, yě bāokuò lèishuǐ yǔ cuòzhé de kǎoyàn. Zhǐyǒu jiēnà quánbù de jīnglì, shēngmìng cái suàn zhēnzhèng wánzhěng.", "en": "True living encompasses not just immediate mundanities, but contemplating distant starry skies. Life's journey resembles a dense volume, including joyful harvest chapters as well as trials of tears and setbacks. Embracing the whole renders existence complete.", "es": "Vivir no es solo lidiar con afanes cotidianos, sino alzar la mirada hacia las estrellas. El camino vital asemeja un libro denso que incluye risas y frutos, mas también lágrimas y pruebas amargas. Solo abrazando cada vivencia la existencia alcanza su plenitud."}, {"id": "#2", "hanzi": "联合国可持续发展目标构建了一个多元评估指标体系，核心内容不仅包括消除极端贫困与饥饿，更涵盖了促进性别平等、保护海洋生态以及应对全球气候变化等多重战略维度。这一综合框架为世界各国制定包容性公共治理政策确立了清晰的行动指南。", "pinyin": "Liánhéguó kěchíxù fāzhǎn mùbiāo gòujiàn le yí gè duōyuán pínggū zhǐbiāo tǐxì, héxīn nèiróng bùjǐn bāokuò xiāochú jíduān pínkùn yǔ jī'è, gèng hángài le cùjìn xìngbié píngděng, bǎohù hǎiyáng shēngtài yǐjí yìngduì quánqiú qìhòu biànhuà děng duōchóng zhànlüè wéidù. Zhè yí zōnghé kuàngjià wèi shìjiè gèguó zhìdìng bāoróngxìng gōnggòng zhìlǐ zhèngcè quèlì le qīngxī de xíngdòng zhǐnán.", "en": "The UN Sustainable Development Goals formulate a multidimensional metric system, including eradicating extreme poverty and hunger while advancing gender equality, marine preservation, and climate resilience. This framework furnishes clear roadmaps for inclusive public governance worldwide.", "es": "Los Objetivos de Desarrollo Sostenible de la ONU trazan un sistema de indicadores plural que incluye erradicar la pobreza y el hambre, abarcando la equidad de género, la protección marina y el cambio climático. Este marco global orienta políticas públicas inclusivas en todo el mundo."}]}, {"meanings_summary": {"en": "to drive; to pilot; to steer; to navigate a vehicle or vessel", "es": "conducir; pilotar; manejar; guiar un vehículo o barco"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Harnessing horses to a chariot (驾) and spurring them to gallop swiftly (驶) embodies skillful steering and driving (驾驶).", "composite_memory_hook_es": "Uncir caballos al carruaje (驾) y lanzarlos a galopar a buen paso (驶) representa el arte de conducir (驾驶).", "cultural_and_cognitive_roots": "Chariot driving (御) was one of the Six Classic Arts (六艺) of ancient Chinese noble education. '驾驶' evolved from ancient equine horsemanship into the universal term for vehicular and nautical pilotage.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone followed by a dipping 3rd tone: jià shǐ (51-214). Drop 'jià' sharply from pitch 5 to 1 before modulating 'shǐ' smoothly through 214."}, "semantic_boundary_contrasts": {"core_nuance": "驾驶 emphasizes the technical manipulation and control of machines, vehicles, aircraft, or ships by an operator.", "contrasts": [{"id": "1", "compared_word": "驾驶 vs. 开", "pinyin": "kāi", "analysis": "驾驶 is the formal, written, and technical term for operating any vehicle, boat, or plane (驾驶飞机, 驾驶员), whereas 开 is the colloquial everyday verb for driving or operating (开车)."}, {"id": "2", "compared_word": "驾驶 vs. 操纵", "pinyin": "cāozòng", "analysis": "驾驶 emphasizes navigation and steering a moving vessel, whereas 操纵 focuses on mechanical lever/button control, financial manipulation, or political pull."}, {"id": "3", "compared_word": "驾驶 vs. 航行", "pinyin": "hángxíng", "analysis": "驾驶 describes the specific operational actions of the pilot at the helm, whereas 航行 describes the overall travel movement of the vessel through water or air."}]}, "traps_and_cognates": {"look_alikes": [{"character": "驾", "pinyin": "jià", "meaning_en": "drive; harness", "distinction_note": "Has 加 on top and 马 (horse) at the bottom"}, {"character": "贺", "pinyin": "hè", "meaning_en": "congratulate; celebrate", "distinction_note": "Has 加 on top and 贝 (cowrie shell) at the bottom"}, {"character": "驶", "pinyin": "shǐ", "meaning_en": "drive; speed", "distinction_note": "Has 马 on the left and 史 on the right"}, {"character": "使", "pinyin": "shǐ", "meaning_en": "use; make; envoy", "distinction_note": "Has 亻 (person) on the left and 吏/史 on the right"}], "etymological_cognates": [{"character": "劳驾", "pinyin": "láo jià", "gloss_en": "excuse me; may I trouble you"}, {"character": "驶向", "pinyin": "shǐ xiàng", "gloss_en": "sail toward; head toward"}, {"character": "行驶", "pinyin": "xíng shǐ", "gloss_en": "drive; travel (of vehicles/ships)"}, {"character": "飞驶", "pinyin": "fēi shǐ", "gloss_en": "speed along; dart by"}]}, "id": "14", "hanzi": "驾驶", "pinyin": "jià shǐ", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to operate, control, and steer a motor vehicle, airplane, boat, or ship", "definition_es": "operar, guiar y controlar un vehículo de motor, aeronave o barco", "example_phrase": "驾驶汽车 (drive a car)"}], "example_sentences": [{"id": "#1", "hanzi": "他经过半年的刻苦训练，熟练掌握了复杂海况下操纵帆船的驾驶技巧。", "pinyin": "Tā jīngguò bàn nián de kèkǔ xùnliàn, shúliàn zhǎngwò le fùzá hǎikuàng xià cāozòng fānchuán de jiàshǐ jìqiǎo.", "en": "After six months of rigorous training, he skillfully mastered sailing piloting techniques under treacherous sea conditions.", "es": "Tras medio año de arduo entrenamiento, dominó con soltura las técnicas de gobierno del velero bajo complicadas condiciones marinas."}, {"id": "#2", "hanzi": "交通法规严厉惩处酒后驾驶行为，以最大限度保障道路公共交通的行车安全。", "pinyin": "Jiāotōng fǎguī yánlì chéngchǔ jiǔhòu jiàshǐ xíngwéi, yǐ zuìdà xiàndù bǎozhàng dàolù gōnggòng jiāotōng de xíngchē ānquán.", "en": "Traffic regulations strictly penalize drunk driving to maximize safety on public roads.", "es": "El código de circulación sanciona con severidad la conducción bajo los efectos del alcohol para garantizar la seguridad en las vías públicas."}], "collocations": [{"hanzi": "驾驶员", "en": "driver; pilot"}, {"hanzi": "驾驶执照", "en": "driver's license"}, {"hanzi": "酒后驾驶", "en": "drunk driving; drive under influence"}, {"hanzi": "自动驾驶", "en": "autonomous driving; autopilot"}, {"hanzi": "驾驶技巧", "en": "driving / piloting skills"}, {"hanzi": "熟练驾驶", "en": "drive / pilot skillfully"}], "idioms": [{"hanzi": "驾轻就熟", "pinyin": "jià qīng jiù shú", "meaning_en": "drive a light cart on a familiar road; do a job with ease from experience"}, {"hanzi": "并驾齐驱", "pinyin": "bìng jià qí qū", "meaning_en": "run neck and neck; keep pace with; match side by side"}, {"hanzi": "长驱直入", "pinyin": "cháng qū zhí rù", "meaning_en": "drive straight into deep enemy territory; advance without hindrance"}, {"hanzi": "东齐西驶", "pinyin": "dōng qí xī shǐ", "meaning_en": "drive eastward and sail westward; work toward conflicting directions"}], "character_decomposition": [{"character": "驾", "pinyin": "jià", "meaning_en": "harness; drive; chariot", "meaning_es": "uncir; conducir; carruaje", "radical": "马", "radical_meaning_en": "horse / steed", "meaning_component": "马 (steed harnessed to a cart)", "sound_component": "加 (jiā phonetic / add force or yoke)", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound: adding harnesses (加) onto spirited horses (马) to guide and steer chariots.", "visual_mnemonic_story_en": "Fastening the harness yoke (加) onto powerful horses (马) to steer the speeding chariot forward.", "visual_mnemonic_story_es": "Uncir el arnés (加) a briosos caballos (马) para guiar el carruaje al galope con destreza.", "tone_mnemonic_anchor": "51", "cangjie": "KSNVF", "traditional": "駕"}, {"character": "驶", "pinyin": "shǐ", "meaning_en": "speed; drive; sail fast", "meaning_es": "avanzar rápido; navegar; marchar", "radical": "马", "radical_meaning_en": "horse / steed", "meaning_component": "马 (horse running swiftly)", "sound_component": "史 (shǐ phonetic / scribe or official record)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: steed (马) speeding forward as swiftly as historical events recorded by a scribe (史).", "visual_mnemonic_story_en": "A galloping horse (马) racing across vast terrain, steering forward with focused direction (史).", "visual_mnemonic_story_es": "Un caballo al galope (马) que vuela por el camino marcando un rumbo veloz y certero (史).", "tone_mnemonic_anchor": "214", "cangjie": "NMSK", "traditional": "駛"}], "extended_reading_passages": [{"id": "#1", "hanzi": "独自在深夜的海面上驾驶帆船，需要超越常人的专注与勇气。四周是一片深邃的漆黑，唯有舵盘在掌心传递着波浪的震颤。这一刻，人与帆船融为一体，每一次对航向的微调，都是对生命的敬畏与担当。", "pinyin": "Dúzì zài shēnyè de hǎimiàn shàng jiàshǐ fānchuán, xūyào chāoyuè chángrén de zhuānzhù yǔ yǒngqì. Sìzhōu shì yí piàn shēnsuì de qīhēi, wéiyǒu duòpán zài zhǎngxīn chuándì zhe bōlàng de zhènchàn. Zhè yí kè, rén yǔ fānchuán róng wéi yītǐ, měi yí cì duì hángxiàng de wēitiáo, dōu shì duì shēngmìng de jìngwèi yǔ dāndāng.", "en": "Piloting a sailboat alone across night waters demands superhuman concentration and courage. Surrounded by inky darkness, only the helm vibrates against the palm. Man and vessel fuse; every micro-correction of heading honors life itself.", "es": "Pilotar un velero en la soledad de la noche marina exige un temple sobrehumano. En medio de la oscuridad absoluta, el timón transmite en la palma el pulso de las olas. Hombre y nave se funden; cada ajuste de rumbo es un tributo a la vida."}, {"id": "#2", "hanzi": "人工智能与高精度激光雷达传感器的飞速迭代，正深刻颠覆传统的机动车驾驶概念。具备高级别自主决策能力的自动驾驶算法系统，不仅能够大幅削减由于人为注意力分散而引发的道路交通事故，更将从底层重塑未来智慧城市的交通出行新范式。", "pinyin": "Réngōng zhìnéng yǔ gāojīngdù jīguāng léidá chuángǎnqì de fēisù jiédài, zhèng shēnkè diānfù chuántǒng de jīdòngchē jiàshǐ gǎiniàn. Jùbèi gāojíbié zìzhǔ juécè nénglì de zìdòng jiàshǐ suànfǎ xìtǒng, bùjǐn nénggòu dàfú xuējiǎn yóuyú rénwéi zhùyìlì fēnsǎn ér yǐnfā de dàolù jiāotōng shìgù, gèng jiāng cóng dǐcéng zhòngshù wèilái zhìhuì chéngshì de jiāotōng chūxíng xīn fànshì.", "en": "Rapid breakthroughs in artificial intelligence and LiDAR sensors are overturning conventional notions of vehicular driving. Autonomous driving algorithms possessing high-level decision autonomy mitigate human-error accidents and fundamentally reconfigure urban mobility paradigms.", "es": "Los avances en inteligencia artificial y sensores LiDAR revolucionan el concepto de conducir. Los algoritmos de conducción autónoma avanzada suprimen siniestros por distracciones humanas y remodelan desde la base el paradigma del transporte urbano inteligente."}]}, {"meanings_summary": {"en": "to bump against; to collide; to strike; to run into; to meet by chance", "es": "chocar; colisionar; tropezar; golpear; toparse con"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An energetic boy (童) barreling forward crashes into an outstretched hand (扌), producing a violent collision (撞).", "composite_memory_hook_es": "Un muchacho que corre desbocado (童) choca contra una mano extendida (扌), provocando una fuerte colisión (撞).", "cultural_and_cognitive_roots": "In Chinese cultural tradition, striking temple bronze bells (撞钟) was an ancient ritual signaling dawn and dusk. Metaphorically, '撞' evokes abrupt, jarring physical or psychological impact.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone: zhuàng (51). Deliver the syllable with a forceful, downward burst to phonetically mirror an abrupt impact."}, "semantic_boundary_contrasts": {"core_nuance": "撞 denotes sudden, violent physical contact or an unexpected coincidental meeting.", "contrasts": [{"id": "1", "compared_word": "撞 vs. 碰", "pinyin": "pèng", "analysis": "撞 carries much greater physical force, kinetic impact, and destructive potential (撞车, 巨浪撞击), whereas 碰 describes lighter contact, touching, or minor gentle bumps (碰了一下)."}, {"id": "2", "compared_word": "撞 vs. 打", "pinyin": "dǎ", "analysis": "撞 implies direct physical collisions between moving bodies, while 打 is an intentional act of hitting, punching, beating, or playing."}, {"id": "3", "compared_word": "撞 vs. 击", "pinyin": "jī", "analysis": "撞 emphasizes blunt-force bodily collision or crashes, whereas 击 is formal and literary, describing precision strikes, blows, or ballistic impacts (击中目标)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "撞", "pinyin": "zhuàng", "meaning_en": "collide; hit", "distinction_note": "Has 扌 (hand) radical on the left and 童 on the right"}, {"character": "憧", "pinyin": "chōng", "meaning_en": "yearn for; look forward", "distinction_note": "Has 忄 (heart) radical on the left with 童"}, {"character": "幢", "pinyin": "chuáng / zhuàng", "meaning_en": "banner; classifier for buildings", "distinction_note": "Has 巾 (cloth) radical on the left with 童"}, {"character": "瞳", "pinyin": "tóng", "meaning_en": "pupil of eye", "distinction_note": "Has 目 (eye) radical on the left with 童"}], "etymological_cognates": [{"character": "相撞", "pinyin": "xiāng zhuàng", "gloss_en": "crash into each other; collide"}, {"character": "撞伤", "pinyin": "zhuàng shāng", "gloss_en": "injure by collision"}, {"character": "冲击", "pinyin": "chōng jī", "gloss_en": "charge; impact; shock wave"}, {"character": "打击", "pinyin": "dǎ jī", "gloss_en": "strike; hit; crack down on"}]}, "id": "15", "hanzi": "撞", "pinyin": "zhuàng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to collide violently with or strike against an object or person", "definition_es": "chocar violentamente contra algo o alguien; colisionar", "example_phrase": "撞车 (car crash / collision)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Colloquial", "definition_en": "to meet, bump into, or coincide with by chance", "definition_es": "toparse por casualidad; coincidir de forma imprevista", "example_phrase": "撞见熟人 (bump into an acquaintance)"}], "example_sentences": [{"id": "#1", "hanzi": "狂暴的巨浪猛烈撞击着帆船的侧舷，船身剧烈摇晃，全家人紧紧抓牢甲板上的扶手。", "pinyin": "Kuángbào de jùlàng měngliè zhuàngjī zhe fānchuán de cèxián, chuánshēn jùliè yáohuàng, quán jiārén jǐnjǐn zhuāláo jiǎbǎn shàng de fúshǒu.", "en": "Savage monster waves slammed violently against the sailboat's flank, rocking the hull wildly as the family gripped the deck rails.", "es": "Olas descomunales embistieron el costado del velero, haciendo crujir el casco mientras la familia se aferraba con fuerza al pasamanos de cubierta."}, {"id": "#2", "hanzi": "两辆高速行驶的货车在十字路口发生碰撞，交警与救援人员迅速赶赴现场展开处置。", "pinyin": "Liǎng liàng gāosù xíngshǐ de huòchē zài shízì lùkǒu fāshēng pèngzhuàng, jiāojǐng yǔ jiùyuán rényuán xùnsù gǎnfù xiànchǎng zhǎnkāi chǔzhì.", "en": "Two fast-moving trucks collided at the intersection, prompting traffic police and rescue teams to rush to the scene.", "es": "Dos camiones que circulaban a gran velocidad colisionaron en la intersección; la policía de tráfico y los equipos de auxilio acudieron de inmediato."}], "collocations": [{"hanzi": "撞击", "en": "strike; impact; hit"}, {"hanzi": "碰撞", "en": "collide; clash"}, {"hanzi": "撞车", "en": "vehicle collision; clash of schedules"}, {"hanzi": "被撞", "en": "be hit; be struck"}, {"hanzi": "撞倒", "en": "knock down; bump over"}, {"hanzi": "横冲直撞", "en": "dash around wildly; barge about recklessly"}], "idioms": [{"hanzi": "横冲直撞", "pinyin": "héng chōng zhí zhuàng", "meaning_en": "dash around recklessly; barge about wildly"}, {"hanzi": "误打误撞", "pinyin": "wù dǎ wù zhuàng", "meaning_en": "score a lucky hit by mistake; stumble into success by accident"}, {"hanzi": "东奔西撞", "pinyin": "dōng bēn xī zhuàng", "meaning_en": "dash around in all directions; rush about blindly"}, {"hanzi": "撞钟引磬", "pinyin": "zhuàng zhōng yǐn qìng", "meaning_en": "strike bell to initiate chime; prompt subsequent responses"}], "character_decomposition": [{"character": "撞", "pinyin": "zhuàng", "meaning_en": "bump; collide; strike", "meaning_es": "chocar; golpear; topar", "radical": "扌", "radical_meaning_en": "hand / strike", "meaning_component": "扌 (hand striking with force)", "sound_component": "童 (tóng phonetic / youth or child standing)", "stroke_count": "15", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: a forceful hand (扌) delivering an impact like a running youth (童) colliding head-on.", "visual_mnemonic_story_en": "An outstretched arm (扌) trying to brace against an energetic youth (童) barreling into you head-on.", "visual_mnemonic_story_es": "Un brazo extendido (扌) que intenta frenar el choque frontal de un muchacho que corre desbocado (童).", "tone_mnemonic_anchor": "51", "cangjie": "QYTG", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "航行在大洋深处，最惊心动魄的莫过于深夜暗礁与风浪的撞击。狂风卷起数米高的黑色巨浪，一次次重重砸在甲板上。水手们在剧烈的震荡中咬紧牙关，因为他们深知，唯有坚守阵地，才能在自然伟力面前搏得一线生机。", "pinyin": "Hángxíng zài dàyáng shēnchù, zuì jīngxīndòupò de mòguòyú shēnyè ànjiāo yǔ fēnglàng de zhuàngjī. Kuángfēng juǎn qǐ shù mǐ gāo de hēisè jùlàng, yícìcì zhòngzhòng zá zài jiǎbǎn shàng. Shuǐshǒumen zài jùliè de zhèndàng zhōng yǎojǐn yáoguān, yīnwèi tāmen shēnzhī, wéiyǒu jiānshǒu zhèndì, cáinéng zài zìrán wěilì miànqián bó dé yíxiàn shēngjī.", "en": "Deep in the ocean, nothing strikes terror like colliding with nocturnal reefs and surging waves. Wind heaves multi-meter black rollers crashing upon decks. Bracing through jarring shuddering, sailors grit their teeth, knowing steadfast vigilance secures survival.", "es": "En alta mar nada sobrecoge más que el impacto nocturno contra arrecifes y olas monstruosas. El vendaval levanta crestas negras que azotan la cubierta. Entre sacudidas violentas la tripulación aprieta los dientes, consciente de que resistir es la única salvación."}, {"id": "#2", "hanzi": "汽车安全碰撞测试是衡量整车被动安全性能的核心标准。通过高精度传感器记录车辆在高速撞击瞬间的车身结构形变与吸能效果，工程研发团队能够针对性强化关键受力构件，并在毫秒级时间内优化气囊点火算法，筑牢驾乘人员的安全防线。", "pinyin": "Qìchē ānquán pèngzhuàng cèshì shì héngliáng zhěngchē bèidòng ānquán xìngnéng de héxīn biāozhǔn. Tōngguò gāojīngdù chuángǎnqì jìlù chēliàng zài gāosù zhuàngjī shùnjiān de chēshēn jiégòu xíngbiàn yǔ xīnnéng xiàoguǒ, gōngchéng yánfā tuánduì nénggòu zhēnduìxìng qiánghuà guānjiàn shòulì gòujiàn, bìng zài háomiǎojí shíjiān nèi yōuhuà qìnáng diǎnhuǒ suànfǎ, zhùláo jiàchéng rényuán de ānquán fángxiàn.", "en": "Automotive crash testing represents the definitive benchmark for evaluating vehicular passive safety. High-precision sensors record deformation and kinetic energy absorption during high-speed impacts, empowering engineers to reinforce structural pillars and calibrate millisecond airbag deployment.", "es": "Los ensayos de choque automovilístico evalúan la seguridad pasiva integral. Sensores de precisión registran la deformación y disipación energética en colisiones violentas, permitiendo reforzar pilares clave y optimizar el disparo de los airbags para salvar vidas."}]}, {"meanings_summary": {"en": "crazy; mad; insane; deranged; to go mad; to play wild", "es": "loco; chiflado; enloquecer; volverse loco; jugar desenfrenadamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An internal illness (疒) whipping up like wild stormy winds (风) drives a person completely mad (疯).", "composite_memory_hook_es": "Una dolencia febril (疒) agitada como un viento desbocado (风) hace enloquecer a cualquiera (疯).", "cultural_and_cognitive_roots": "Traditional Chinese medicine believed that external wind evil ('风邪') entering the body could cause convulsions and delirium (中风/疯癫). Culturally, deviating radically from conventional societal norms is often labeled '疯' before being recognized as genius.", "tone_sandhi_and_pitch_modulation": "High level 1st tone: fēng (55). Hold the pitch high and steady without inflection."}, "semantic_boundary_contrasts": {"core_nuance": "疯 represents extreme departure from sanity, conventional restraint, or rational bounds.", "contrasts": [{"id": "1", "compared_word": "疯 vs. 狂", "pinyin": "kuáng", "analysis": "疯 emphasizes medical madness, loss of mental lucidity, or foolish eccentricities (疯子, 气疯了), whereas 狂 denotes wild arrogance, fierce unbridled passion, or elemental fury (狂妄, 狂欢, 狂风)."}, {"id": "2", "compared_word": "疯 vs. 傻", "pinyin": "shǎ", "analysis": "疯 signifies mental derangement or hysterical abandon, while 傻 refers to slowness of wit, foolish simplicity, or gullibility."}, {"id": "3", "compared_word": "疯 vs. 呆", "pinyin": "dāi", "analysis": "疯 denotes hyperactive, irrational agitation, whereas 呆 indicates blank sluggishness, frozen stupor, or numbness."}]}, "traps_and_cognates": {"look_alikes": [{"character": "疯", "pinyin": "fēng", "meaning_en": "crazy; insane", "distinction_note": "Has 疒 (sickness) radical enclosing 风"}, {"character": "病", "pinyin": "bìng", "meaning_en": "disease; illness", "distinction_note": "Has 疒 enclosing 丙 instead of 风"}, {"character": "疼", "pinyin": "téng", "meaning_en": "ache; hurt", "distinction_note": "Has 疒 enclosing 冬"}, {"character": "痛", "pinyin": "tòng", "meaning_en": "pain; ache", "distinction_note": "Has 疒 enclosing 甬"}], "etymological_cognates": [{"character": "疯狂", "pinyin": "fēng kuáng", "gloss_en": "frantic; madness; crazy"}, {"character": "疯长", "pinyin": "fēng zhǎng", "gloss_en": "grow rampant; proliferate wildly"}, {"character": "装疯", "pinyin": "zhuāng fēng", "gloss_en": "feign madness; play the fool"}, {"character": "打疯", "pinyin": "dǎ fēng", "gloss_en": "play wildly with extreme gusto"}]}, "id": "16", "hanzi": "疯", "pinyin": "fēng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to lose mental balance or go mad; to become insane", "definition_es": "volverse loco; perder el juicio; enloquecer", "example_phrase": "气疯了 (driven mad with anger)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Colloquial", "definition_en": "wild, reckless, or completely unrestrained in enthusiasm", "definition_es": "loco; desenfrenado; desmedido", "example_phrase": "玩疯了 (having wild fun)"}], "example_sentences": [{"id": "#1", "hanzi": "得知翟峰辞掉公职卖掉房子买帆船出海，身边的很多亲友都以为他一定是疯了。", "pinyin": "Dézhī Zhái Fēng cídiào gōngzhí mài diào fángzi mǎi fānchuán chūhǎi, shēnbiān de hěnduō qīnyǒu dōu yǐwéi tā yídìng shì fēng le.", "en": "Learning that Zhai Feng had quit his job, sold his home, and bought a boat to sail away, many friends thought he had gone crazy.", "es": "Al enterarse de que Zhai Feng había dejado su empleo fijo y vendido su casa para comprar un velero, muchos allegados pensaron que se había vuelto loco."}, {"id": "#2", "hanzi": "股市在投机资金的疯狂推动下出现异常暴涨，理性投资者纷纷警示潜在的泡沫风险。", "pinyin": "Gǔshì zài tóujī zījīn de fēngkuáng tuīdòng xià chūxiàn yìcháng bàozhǎng, lǐxìng tóuzīzhě fēnfēn jǐngshì qiánzài de pàomò fēngxiǎn.", "en": "Driven by speculative frenzy, the stock market surged abnormally, prompting rational investors to warn of bubble risks.", "es": "Impulsada por una fiebre especulativa, la bolsa experimentó alzas desorbitadas, lo que llevó a inversores sensatos a advertir del riesgo de burbuja."}], "collocations": [{"hanzi": "疯子", "en": "madman; lunatic"}, {"hanzi": "疯狂", "en": "crazy; frantic; insane"}, {"hanzi": "气疯", "en": "driven mad with anger"}, {"hanzi": "玩疯了", "en": "having wild and crazy fun"}, {"hanzi": "发疯", "en": "go mad; lose one's mind"}, {"hanzi": "急疯了", "en": "driven frantic with worry"}], "idioms": [{"hanzi": "疯疯癫癫", "pinyin": "fēng fēng diān diān", "meaning_en": "acting crazy and frivolous; eccentric and unhinged"}, {"hanzi": "丧心病狂", "pinyin": "sàng xīn bìng kuáng", "meaning_en": "frenzied and perverse; completely devoid of conscience"}, {"hanzi": "狂风暴雨", "pinyin": "kuáng fēng bào yǔ", "meaning_en": "furious howling winds and violent rainstorms"}, {"hanzi": "发狂大叫", "pinyin": "fā kuáng dà jiào", "meaning_en": "scream hysterically like a maniac"}], "character_decomposition": [{"character": "疯", "pinyin": "fēng", "meaning_en": "crazy; mad; insane", "meaning_es": "loco; enloquecer; demente", "radical": "疒", "radical_meaning_en": "sickness / disease", "meaning_component": "疒 (illness or sickbed)", "sound_component": "风 (fēng phonetic / wind causing madness)", "stroke_count": "9", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ideogrammic/phono-semantic compound: sickbed radical (疒) with wind (风), evoking traditional medicine where pernicious pathogenic wind attacks the brain.", "visual_mnemonic_story_en": "A patient bound to a sickbed (疒) whose mind has been whipped into a frenzy by wild winds (风).", "visual_mnemonic_story_es": "Un enfermo encamado (疒) cuya mente ha quedado desquiciada por el vendaval delirante del viento (风).", "tone_mnemonic_anchor": "55", "cangjie": "KHNK", "traditional": "瘋"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在世俗的眼光里，放弃安稳舒适的日常生活去追逐不可预测的海洋探险，无异于一种疯狂的举动。然而，历史往往由那些敢于打破常规的疯子写就。当一个人坚信自己的航向时，外界的质疑终将化作远航的风帆。", "pinyin": "Zài shìsú de yǎnguāng lǐ, fàngqì ānwěn shūshì de rìcháng shēnghuó qù zhuīzhú bùkěyùcè de hǎiyáng tànxiǎn, wúyìyú yì zhǒng fēngkuáng de jǔdòng. Rán'ér, lìshǐ wǎngwǎng yóu nàxiē gǎnyú dǎpò chángguī de fēngzi xiějiù. Dāng yí gè rén jiānxìn zìjǐ de hángxiàng shí, wàijiè de zhìyí zhōng jiāng huàzuò yuǎnháng de fēngfān.", "en": "In conventional eyes, forfeiting mundane stability to chase volatile oceanic adventures seems utter madness. Yet history is inked by dreamers bold enough to defy norms. When one believes in their compass heading, skepticism becomes wind in the sails.", "es": "A los ojos convencionales, cambiar la rutina plácida por los azares del mar parece pura locura. Mas la historia la forjan aquellos audaces tachados de chiflados. Quien confía en su propio rumbo transforma los reproches en viento para sus velas."}, {"id": "#2", "hanzi": "社会心理学学者分析指出，群体狂热往往发端于信息闭塞与从众本能的叠加。在极端市场情绪诱导下，个体会不自觉地卷入非理性的投资热潮中。唯有强化独立思辨能力与金融风险意识，才能在狂热的市场中保持清醒，规避非理性投机带来的惨痛代价。", "pinyin": "Shèhuì xīnlǐxué xuézhě fēnxī zhǐchū, qúntǐ kuángrè wǎngwǎng fāduān yú xìnxī bìsè yǔ cóngzhòng běnnéng de diéjiā. Zài jíduān shìchǎng qíngxù yòudǎo xià, gètǐ huì bùzìjué de juǎnrù fēilǐxìng de tóuzī rècháo zhōng. Wéiyǒu qiánghuà dúlì sībiàn nénglì yǔ jīnróng fēngxiǎn yìshí, cáinéng zài kuángrè de shìchǎng zhōng bǎochí qīngxǐng, guībì fēilǐxìng tóujī dài lái de cǎntòng dàijià.", "en": "Social psychologists note that mass frenzy stems from coupled information deficits and herd mentality. Goaded by euphoria, individuals tumble into irrational speculative manias. Fostering critical discernment remains crucial for shielding oneself against devastating market collapses.", "es": "La psicología social explica que el furor colectivo brota de la desinformación y el instinto gregario. Seducidos por la euforia, los inversores se precipitan a fiebres especulativas irracionales. Solo el pensamiento crítico y la templanza permiten preservar la cordura y eludir la ruina."}]}, {"meanings_summary": {"en": "to fish with a hook and line; to angle for; to fish", "es": "pescar con caña; pescar con anzuelo; buscar ardilosamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A curved metal hook (钅) scooping up (勺) swimming fish from the water allows you to fish (钓).", "composite_memory_hook_es": "Un anzuelo de metal (钅) que recoge como una cuchara (勺) a los peces bajo el agua permite pescar (钓).", "cultural_and_cognitive_roots": "The ancient legend of Jiang Ziya fishing with a straight, unbarbed hook (愿者上钩) made angling a profound Chinese philosophical metaphor for waiting patiently for destiny rather than forcing outcomes.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone: diào (51). Deliver a clean, firm downward pitch contour from high to low."}, "semantic_boundary_contrasts": {"core_nuance": "钓 refers specifically to catching aquatic creatures using a hook and line or metaphorically luring someone.", "contrasts": [{"id": "1", "compared_word": "钓 vs. 捕", "pinyin": "bǔ", "analysis": "钓 is recreational or small-scale angling using hooks, lines, and bait, whereas 捕 involves active catching, netting, trapping, or arresting (捕鱼, 捕捞, 捕捉)."}, {"id": "2", "compared_word": "钓 vs. 捞", "pinyin": "lāo", "analysis": "钓 relies on enticing fish with bait on a hook, while 捞 means directly scooping up or dredging items from underwater using nets or hands."}, {"id": "3", "compared_word": "钓 vs. 捉", "pinyin": "zhuō", "analysis": "钓 is restricted to line fishing or covert luring, while 捉 describes physically seizing or grasping by hand (捉贼, 捉迷藏)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "钓", "pinyin": "diào", "meaning_en": "fish with hook", "distinction_note": "Has 钅 on the left and 勺 on the right"}, {"character": "钩", "pinyin": "gōu", "meaning_en": "hook; barb", "distinction_note": "Has 钅 on the left and 勾 on the right"}, {"character": "钓", "pinyin": "diào", "meaning_en": "fish with hook", "distinction_note": "Has 钅 and 勺 (with inner dot)"}, {"character": "的", "pinyin": "de / dì", "meaning_en": "possessive particle; target", "distinction_note": "Has 白 on the left with 勺"}], "etymological_cognates": [{"character": "钓具", "pinyin": "diào jù", "gloss_en": "fishing tackle; fishing gear"}, {"character": "钓手", "pinyin": "diào shǒu", "gloss_en": "angler; fisherman"}, {"character": "垂钓", "pinyin": "chuí diào", "gloss_en": "go angling; gentle fishing"}, {"character": "海钓", "pinyin": "hǎi diào", "gloss_en": "sea fishing; offshore angling"}]}, "id": "17", "hanzi": "钓", "pinyin": "diào", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to catch aquatic life using a hook, line, or rod", "definition_es": "pescar peces u otros animales acuáticos con caña o anzuelo", "example_phrase": "在海边钓鱼 (fish by the seashore)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Formal", "definition_en": "to fish or angle for something indirectly (fame, praise, wealth)", "definition_es": "buscar o pescar algo indirectamente como fama o favores", "example_phrase": "沽名钓誉 (angle for fame and social praise)"}], "example_sentences": [{"id": "#1", "hanzi": "航行在太平洋中央时，全家人常常坐在船尾钓鱼，新鲜的金枪鱼成了餐桌上最美味的补给。", "pinyin": "Hángxíng zài Tàipíngyáng zhōngyāng shí, quán jiārén chángcháng zuò zài chuánwěi diàoyú, xīnxiān de jīnqiāngyú chéng le cānzhuō shàng zuì měiwèi de bǔjǐ.", "en": "While sailing through the middle of the Pacific, the family often angled off the stern, fresh tuna becoming their tastiest provision.", "es": "Durante la travesía por el Pacífico, la familia solía pescar con caña en la popa; el atún fresco se convirtió en su más sabroso manjar."}, {"id": "#2", "hanzi": "周末清晨，许多垂钓爱好者来到静谧的湖畔，在悠闲的等待中享受远离城市喧嚣的宁静时光。", "pinyin": "Zhōumò qīngchén, xǔduō chuídiào àihàozhě lái dào jìngmì de húpàn, zài yōuxián de děngdài zhōng xiǎngshòu yuǎnlí chéngshì xuānxiāo de níngjìng shíguāng.", "en": "On weekend mornings, angling enthusiasts gather by the tranquil lakeshore, savoring serene hours away from urban clamor through leisurely waiting.", "es": "En las mañanas de fin de semana, aficionados a la pesca acuden a la orilla del lago para disfrutar de un sosiego ajeno al ajetreo urbano mediante la espera paciente."}], "collocations": [{"hanzi": "钓鱼", "en": "fish with a hook and line; go fishing"}, {"hanzi": "钓竿", "en": "fishing rod"}, {"hanzi": "钓钩", "en": "fishhook"}, {"hanzi": "垂钓", "en": "angle; fish with rod"}, {"hanzi": "钓鱼岛", "en": "Diaoyu Islands"}, {"hanzi": "钓饵", "en": "bait; lure"}], "idioms": [{"hanzi": "沽名钓誉", "pinyin": "gū míng diào yù", "meaning_en": "fish for fame and angle for compliments; seek unmerited recognition"}, {"hanzi": "姜太公钓鱼", "pinyin": "Jiāng Tàigōng diào yú", "meaning_en": "Jiang Taigong fishing with a straight hook; willing victims bite of their own accord"}, {"hanzi": "钓游之地", "pinyin": "diào yóu zhī dì", "meaning_en": "places where one fished and played in childhood; fondly remembered old haunts"}, {"hanzi": "太公钓鱼", "pinyin": "tài gōng diào yú", "meaning_en": "Jiang Taigong fishing; willing fish stepping into the net willingly"}], "character_decomposition": [{"character": "钓", "pinyin": "diào", "meaning_en": "fish with hook", "meaning_es": "pescar con anzuelo", "radical": "钅", "radical_meaning_en": "metal / gold", "meaning_component": "钅 (metal fishhook)", "sound_component": "勺 (sháo phonetic / curved spoon or hook shape)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: a sharp metal barb (钅) shaped like a small curved scoop (勺) to catch fish.", "visual_mnemonic_story_en": "A glittering metal barb (钅) curving like a tiny curved spoon (勺) dangling into deep water.", "visual_mnemonic_story_es": "Un afilado anzuelo de metal brillante (钅) curvado como una diminuta cuchara (勺) para atrapar peces.", "tone_mnemonic_anchor": "51", "cangjie": "CPY", "traditional": "釣"}], "extended_reading_passages": [{"id": "#1", "hanzi": "坐在平静的船舷边钓鱼，与其说是在等待水下的收获，不如说是在与自己的心灵对话。浮漂在微波间起伏，所有的焦虑与急躁都在无声的守候中渐渐平息。懂得等待的人，才能真正领会大自然赋予的静谧与从容。", "pinyin": "Zuò zài píngjìng de chuánxián biān diàoyú, yǔqí shuō shì zài děngdài shuǐxià de shōuhuò, bùrú shuō shì zài yǔ zìjǐ de xīnlíng duìhuà. Fúpiāo zài wēibō jiān qǐfú, suǒyǒu de jiāolǜ yǔ jízào dōu zài wúshēng de shǒuhòu zhōng jiànjiàn píngxī. Dǒngde děngdài de rén, cáinéng zhēnzhèng lǐnghuì dàzìrán fùyǔ de jìngmì yǔ cóngròng.", "en": "Angling beside a tranquil gunwale is less about awaiting a catch than dialoguing with one's soul. As the bobber bobs among ripples, anxieties quiet in the vigil. Only those versed in waiting truly grasp nature's stillness and grace.", "es": "Sentarse a pescar junto a la borda tranquila es más un coloquio íntimo con el alma que el anhelo de una presa. El flotador baila en el agua y las inquietudes se apaciguan en la espera. Quien domina la paciencia saborea el sosiego que la naturaleza brinda."}, {"id": "#2", "hanzi": "生态保护政策推动了水域治理转型，规范化的休闲垂钓逐渐成为生态渔业的新形态。通过限定钓具规格与渔获放生标准，水生系统得以有效休养生息，实现了生态修复与休闲生活的有机融合。", "pinyin": "Shēngtài bǎohù zhèngcè tuīdòng le shuǐyù zhìlǐ zhuǎnxíng, guīfànhuà de xiūxián chuídiào zhújiàn chéngwéi shēngtài yúyè de xīn xíngtài. Tōngguò xiàndìng diàojù guīgé yǔ yúhuò fàngshēng biāozhǔn, shuǐshēng xìtǒng déyǐ yǒuxiào xiūyǎngxēngxī, shíxiàn le shēngtài xiūfù yǔ xiūxián shēnghuó de yǒujī rónghé.", "en": "Conservation policies have transformed aquatic governance, establishing regulated recreational angling as a sustainable model. Setting tackle limits and catch-and-release rules lets aquatic biomes recover while harmonizing ecology with leisure.", "es": "Las políticas ambientales han transformado la gestión de las aguas, haciendo de la pesca deportiva un modelo sostenible. Fijar normas de aparejos y captura y suelta permite regenerar la fauna acuática aunando ecología y recreo."}]}, {"meanings_summary": {"en": "do not; never; don't (formal/imperative negative particle)", "es": "no; no haga; absténgase de (partícula prohibitiva formal)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A signaling banner waved briskly (勿) marks an urgent command: \"Do not proceed!\" (勿).", "composite_memory_hook_es": "Una bandera de señales ondeada con vigor (勿) marca una orden tajante: \"¡No haga eso!\" (勿).", "cultural_and_cognitive_roots": "The Confucian Golden Rule '己所不欲，勿施于人' from the Analects cemented '勿' as the classical moral marker of negative restraint, emphasizing ethical self-discipline over coercive punishment.", "tone_sandhi_and_pitch_modulation": "Sharp falling 4th tone: wù (51). Deliver the syllable with a short, authoritative downward snap."}, "semantic_boundary_contrasts": {"core_nuance": "勿 is a formal, written negative imperative marker used for polite public rules, notices, and classical admonitions.", "contrasts": [{"id": "1", "compared_word": "勿 vs. 别", "pinyin": "bié", "analysis": "勿 is formal, written, and solemn, standard on signs and rules (请勿吸烟, 切勿盲从), whereas 别 is the colloquial spoken form for daily speech (别去, 别客气)."}, {"id": "2", "compared_word": "勿 vs. 不", "pinyin": "bù", "analysis": "勿 is exclusively imperative/prohibitive (\"do not!\"), whereas 不 is the universal grammatical negation (\"not / does not / will not\")."}, {"id": "3", "compared_word": "勿 vs. 莫", "pinyin": "mò", "analysis": "勿 is standard in modern formal public signs, while 莫 is a literary classical negative particle seen in idioms and poetry (莫生气, 莫过于)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "勿", "pinyin": "wù", "meaning_en": "do not", "distinction_note": "Four strokes with two slanted internal strokes"}, {"character": "匆", "pinyin": "cōng", "meaning_en": "hurried; rushed", "distinction_note": "Has an extra dot inside: 匆"}, {"character": "匀", "pinyin": "yún", "meaning_en": "even; uniform", "distinction_note": "Has 冫/二 inside: 匀"}, {"character": "刃", "pinyin": "rèn", "meaning_en": "blade; knife edge", "distinction_note": "Single dot on the left of 刀"}], "etymological_cognates": [{"character": "切勿", "pinyin": "qiè wù", "gloss_en": "by no means; make sure not to"}, {"character": "勿用", "pinyin": "wù yòng", "gloss_en": "do not use; abstain from"}, {"character": "莫", "pinyin": "mò", "gloss_en": "do not; none (classical negative)"}, {"character": "别", "pinyin": "bié", "gloss_en": "do not (colloquial imperative)"}]}, "id": "18", "hanzi": "勿", "pinyin": "wù", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Formal", "definition_en": "used in public signs, notices, and formal imperatives expressing prohibition or polite warning", "definition_es": "partícula prohibitiva formal usada en avisos, normas y advertencias", "example_phrase": "请勿吸烟 (please do not smoke / no smoking)"}], "example_sentences": [{"id": "#1", "hanzi": "船长在航行日志中郑重警告：恶劣天气下全员务必系好安全绳，切勿擅自踏上湿滑的前甲板。", "pinyin": "Chuánzhǎng zài hángxíng rìzhì zhōng zhèngzhòng jǐnggào: èliè tiānqì xià quányuán wùbì jì hǎo ānquánshéng, qiè wù shànzì tà shàng shīhuá de qián jiǎbǎn.", "en": "The captain recorded a stern warning in the ship's log: during bad weather, all must fasten lifelines and must not step onto the slippery foredeck alone.", "es": "El capitán advirtió con firmeza en el diario de navegación: con mal tiempo es obligatorio fijar los arneses y no adentrarse jamás sin permiso en la cubierta mojada."}, {"id": "#2", "hanzi": "博物馆在珍贵文物展厅前设立了清晰的提示标牌，明确提醒参观人员“请勿拍照”与“请勿喧哗”。", "pinyin": "Bówùguǎn zài zhēnguì wénwù zhǎntīng qián shèlì le qīngxī de tíshì biāopái, míngquè tíxǐng cānguān rényuán \"qǐng wù pāizhào\" yǔ \"qǐng wù xuānhuá\".", "en": "The museum posted clear signs before precious relic galleries, explicitly reminding visitors \"do not photograph\" and \"do not make noise.\"", "es": "El museo instaló carteles informativos ante las vitrinas de valiosas reliquias, recordando a los visitantes la prohibición de fotografiar y hacer ruido."}], "collocations": [{"hanzi": "请勿", "en": "please do not (used on polite public signs)"}, {"hanzi": "切勿", "en": "by no means; be sure not to"}, {"hanzi": "勿忘", "en": "do not forget; never forget"}, {"hanzi": "非请勿入", "en": "no admittance except on business; staff only"}, {"hanzi": "勿轻视", "en": "do not take lightly"}, {"hanzi": "请勿吸烟", "en": "no smoking"}], "idioms": [{"hanzi": "己所不欲，勿施于人", "pinyin": "jǐ suǒ bú yù, wù shī yú rén", "meaning_en": "what you do not wish for yourself, do not do unto others"}, {"hanzi": "宁缺勿滥", "pinyin": "nìng quē wù làn", "meaning_en": "rather go without than accept inferior substitutes"}, {"hanzi": "勿谓言之不预", "pinyin": "wù wèi yán zhī bú yù", "meaning_en": "do not say you were not forewarned"}, {"hanzi": "贪多务得，细大不捐", "pinyin": "tān duō wù dé, xì dà bù juān", "meaning_en": "avidly seek knowledge without neglecting any detail"}], "character_decomposition": [{"character": "勿", "pinyin": "wù", "meaning_en": "do not; prohibitive marker", "meaning_es": "no; prohibido", "radical": "勹", "radical_meaning_en": "wrap / embrace", "meaning_component": "勹 (enclosure or boundary)", "sound_component": "丿 / 彡 (crossed lines of negation or waving banner)", "stroke_count": "4", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a multicolored signaling banner waved back and forth to prohibit or halt troops.", "visual_mnemonic_story_en": "A signaling flag (勿) waving vigorously back and forth to command soldiers: \"Stop! Do not advance!\"", "visual_mnemonic_story_es": "Una bandera de señales (勿) ondeando con energía para ordenar a las tropas: \"¡Alto! ¡No avancéis!\".", "tone_mnemonic_anchor": "51", "cangjie": "PSH", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "面对浩瀚无垠的星空与变幻莫测的海洋，人类切勿心怀傲慢。大自然的规律威严而神圣，只有常怀敬畏之心，在顺应自然节律中谨慎前行，才能在风云变幻的世界里走得更加长远与安稳。", "pinyin": "Miànduì hàohàn wúyín de xīngkōng yǔ biànhuànmòcè de hǎiyáng, rénlèi qiè wù xīnhuái àomàn. Dàzìrán de guīlǜ wēiyán ér shénshèng, zhǐyào cháng huái jìngwèi zhī xīn, zài shùnyìng zìrán jiélǜ zhōng jǐnshèn qiánxíng, cáinéng zài fēngyún biànhuàn de shìjiè lǐ zǒu de gèngjiā chángyuǎn yǔ ānwěn.", "en": "Facing the starry canopy and volatile seas, humanity must never harbor arrogance. Nature's laws are majestic and sacred; only by nurturing reverence and moving with its rhythms can one navigate life's shifting tempests with enduring grace.", "es": "Ante la inmensidad del cielo estrellado y el mar indómito, el hombre jamás debe pecar de soberbia. Las leyes naturales son sagradas; solo obrando con humilde respeto y siguiendo sus ciclos se navega seguro por los azares del mundo."}, {"id": "#2", "hanzi": "公共空间治理规范明确要求，公民在享有公共文化设施便利的同时，切勿损害公共利益。相关法规通过设定清晰的行为红线，强化对破坏公共设施和扰乱秩序行为的惩戒力度，旨在通过柔性引导与刚性约束相结合，营造文明有序的社会风尚。", "pinyin": "Gōnggòng kōngjiān zhìlǐ guīfàn míngquè yāoqiú, gōngmín zài xiǎngyǒu gōnggòng wénhuà shèshī biànlì de tóngshí, qiè wù sǔnhài gōnggòng lìyì. Xiāngguān fǎguī tōngguò shèdìng qīngxī de xíngwéi hóngxiàn, qiánghuà duì pòhuài gōnggòng shèshī hé rǎoluàn zhìxù xíngwéi de chéngjiè lìdù, zhǐzài tōngguò róuxìng yǐndǎo yǔ gāngxìng yuēshù xiāng jiéhé, yíngzào wénmíng yǒuxù de shèhuì fēngshàng.", "en": "Public governance codes mandate that citizens enjoying cultural facilities must never compromise the public good. Statutes draw clear boundaries and enforce penalties against vandalism or disruption, combining courteous guidance with binding rules to nurture civic decorum.", "es": "Las normas cívicas exigen que la ciudadanía, al disfrutar de equipamientos culturales, evite menoscabar el bien común. Las leyes fijan líneas rojas claras y sancionan desperfectos, aunando la persuasión pedagógica con la firmeza legal para afianzar la convivencia civilizada."}]}, {"meanings_summary": {"en": "to leak; to seep; to leave out; to omit; water clock; loophole", "es": "gotear; filtrarse; fugarse; omitir; descuidar; fuga; gotera"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Rainwater (氵) seeping through a cracked rooftop (屚) creates an annoying household leak (漏).", "composite_memory_hook_es": "El agua de lluvia (氵) que se cuela por el tejado agrietado (屚) provoca una molesta gotera o fuga (漏).", "cultural_and_cognitive_roots": "Ancient China used water clocks ('铜壶滴漏') where water dripping at a steady rate measured nighttime hours. The character metaphorically evolved to denote time passing, secrets escaping, or systemic oversights.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone: lòu (51). Deliver a sharp, clean descending pitch from high to low."}, "semantic_boundary_contrasts": {"core_nuance": "漏 emphasizes unwanted escape or seepage through a crack or flaw, or unintended omission in records.", "contrasts": [{"id": "1", "compared_word": "漏 vs. 渗", "pinyin": "shèn", "analysis": "漏 implies visible water dripping or streaming rapidly through a hole or crack (水管漏水), whereas 渗 describes slow, microscopic moisture absorbing or permeating through porous surfaces (渗透, 渗血)."}, {"id": "2", "compared_word": "漏 vs. 泄", "pinyin": "xiè", "analysis": "漏 is physical leakage or clerical omission, whereas 泄 emphasizes venting gas/fluids under pressure or deliberately divulging secrets (发泄, 泄密)."}, {"id": "3", "compared_word": "漏 vs. 掉", "pinyin": "diào", "analysis": "漏 suggests passive omission through oversight, while 掉 denotes falling, dropping, or discarding."}]}, "traps_and_cognates": {"look_alikes": [{"character": "漏", "pinyin": "lòu", "meaning_en": "leak; omit", "distinction_note": "Has 氵 (water) on the left and 屚 on the right"}, {"character": "涸", "pinyin": "hé", "meaning_en": "dry up; exhausted", "distinction_note": "Has 氵 on the left and 固 on the right"}, {"character": "溯", "pinyin": "sù", "meaning_en": "trace back; go upstream", "distinction_note": "Has 氵 on the left and 朔 on the right"}, {"character": "澜", "pinyin": "lán", "meaning_en": "billows; surging waves", "distinction_note": "Has 氵 on the left and 阑 on the right"}], "etymological_cognates": [{"character": "泄露", "pinyin": "xiè lòu", "gloss_en": "leak out; divulge"}, {"character": "渗漏", "pinyin": "shèn lòu", "gloss_en": "seepage; seep through"}, {"character": "脱漏", "pinyin": "tuō lòu", "gloss_en": "omission; slip through"}, {"character": "遗漏", "pinyin": "yí lòu", "gloss_en": "omit; overlook accidentally"}]}, "id": "19", "hanzi": "漏", "pinyin": "lòu", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to escape or penetrate through a hole, fissure, or flaw (of liquid, gas, or light)", "definition_es": "gotear o filtrarse por una hendidura o grieta (líquido, gas, luz)", "example_phrase": "船舱漏水 (the ship's cabin leaks water)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to omit, leave out accidentally, or reveal confidential information", "definition_es": "omitir o pasar por alto por descuido; filtrar información confidencial", "example_phrase": "漏掉一个字 (omit a word)"}], "example_sentences": [{"id": "#1", "hanzi": "帆船在触礁后船底开始严重漏水，翟峰临危不乱，迅速组织全家合力进行紧急堵漏排水。", "pinyin": "Fānchuán zài chùjiāo hòu chuándǐ kāishǐ yánzhòng lòushuǐ, Zhái Fēng lín wēi bú luàn, xùnsù zǔzhī quán jiā hélì jìnxíng jǐnjí dǔlòu páishuǐ.", "en": "After scraping a reef, the sailboat hull began leaking severely; keeping his head, Zhai Feng quickly organized emergency plugging and bailing.", "es": "Tras rozar un arrecife, el casco del velero comenzó a hacer agua gravemente; Zhai Feng mantuvo la calma y organizó el taponamiento y achique urgente."}, {"id": "#2", "hanzi": "在提交重要申报材料之前，项目负责人反复逐项核对，以防漏掉任何关键的财务审计数据。", "pinyin": "Zài tíjiāo zhòngyào shēnbào cáiliào zhīqián, xiàngmù fùzérén fǎnfù zhúxiàng héduì, yǐ fáng lòudiào rènhé guānjiàn de cáiwù shěnjì shùjù.", "en": "Before submitting key application dossiers, the project director verified items repeatedly to avoid omitting crucial financial auditing figures.", "es": "Antes de entregar el expediente de solicitud, el director del proyecto revisó cada apartado para evitar la omisión de datos de auditoría financiera esenciales."}], "collocations": [{"hanzi": "漏水", "en": "leak water; water leakage"}, {"hanzi": "漏洞", "en": "loophole; leak; security flaw"}, {"hanzi": "走漏消息", "en": "leak news / secret"}, {"hanzi": "漏掉", "en": "leave out; omit accidentally"}, {"hanzi": "捡漏", "en": "pick up a bargain by chance"}, {"hanzi": "补漏", "en": "repair a leak; plug a leak"}], "idioms": [{"hanzi": "天网恢恢，疏而不漏", "pinyin": "tiān wǎng huī huī, shū ér bú lòu", "meaning_en": "the net of heaven has large meshes, but lets nothing slip through"}, {"hanzi": "滴水不漏", "pinyin": "dī shuǐ bú lòu", "meaning_en": "not a drop of water leaks; watertight; airtight"}, {"hanzi": "点滴不漏", "pinyin": "diǎn dī bú lòu", "meaning_en": "completely watertight; meticulous without omission"}, {"hanzi": "挂一漏万", "pinyin": "guà yī lòu wàn", "meaning_en": "list one and omit ten thousand; far from comprehensive"}], "character_decomposition": [{"character": "漏", "pinyin": "lòu", "meaning_en": "leak; seep; water clock", "meaning_es": "gotear; filtrarse; clepsidra", "radical": "氵", "radical_meaning_en": "water / liquid", "meaning_component": "氵 (water drops seeping through)", "sound_component": "屚 (lòu / 尸 roof/shelter dripping rain 雨)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: water drops (氵) penetrating through the leaky roof of a shelter (屚 = 尸 + 雨).", "visual_mnemonic_story_en": "Raindrops (氵) dripping through a cracked roof tile (尸) into the living room below (雨).", "visual_mnemonic_story_es": "Gotas de lluvia (氵) que se cuelan por el tejado agrietado (尸) y caen sin cesar en la habitación (雨).", "tone_mnemonic_anchor": "51", "cangjie": "EMOB", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "房屋漏雨的夜晚，听着雨滴落在搪瓷盆里的清脆声响，总能勾起童年清贫而温馨的记忆。母亲在昏暗的煤油灯下忙着挪动盆钵，父亲则披着雨衣爬上屋顶修补破瓦。那些简陋生活里的细致守护，成了抵御岁月风寒的最暖屏障。", "pinyin": "Fángwū lòuyǔ de yèwǎn, tīng zhe yǔdī luò zài tángcípén lǐ de qīngcuì shēngxiǎng, zǒng néng gōuqǐ tóngnián qīngpín ér wēnxīn de jìyì. Mǔqīn zài hūn'àn de méiyóudēng xià máng zhe nuódòng pénbō, fùqīn zé pī zhe yǔyī pá shàng wūdǐng xiūbǔ pòwǎ. Nàxiē jiǎnlòu shēnghuó lǐ de xìzhì shǒuhù, chéng le dǐyù suìyuè fēnghán de zuì nuǎn píngzhàng.", "en": "Nights when rain leaked indoors, the crisp ping of drops in enamel basins stirred warm childhood recollections. Mother moved buckets under the dim lamp while father scaled the roof in his raincoat. Tender vigilance amid humble poverty became an enduring shield against cold.", "es": "En las noches de goteras, el tintineo de la lluvia en los barreños evocaba memorias entrañables de la niñez. Mi madre movía recipientes a la luz del candil y mi padre subía al tejado a reparar tejas. Aquel desvelo en la escasez fue un cálido escudo frente al rigor de los años."}, {"id": "#2", "hanzi": "随着数字化转型的推进，网络安全边界日益拓展。细微的代码漏洞一旦被恶意利用，就可能危及核心数据资产。因此，定期开展动态漏洞排查与系统加固，是维护数字信息安全的必要举措。", "pinyin": "Suízhe shùzìhuà zhuǎnxíng de tuījìn, wǎngluò ānquán biānjiè rìyì tuòzhǎn. Xìwēi de dàimǎ lòudòng yídàn bèi èyì lìyòng, jiù kěnéng wēijí héxīn shùjù zīchǎn. Yīncǐ, dìngqī zhǎnkāi dòngtài lòudòng páichá yǔ xìtǒng jiāgù, shì wéihù shùzì xìnxī ānquán de bìyào jǔcuò.", "en": "As digital transformation advances, cybersecurity perimeters expand continuously. Once minor code vulnerabilities are exploited, core data assets are endangered. Conducting regular vulnerability scans and hardening remains essential.", "es": "Con el avance de la digitalización, la frontera de la ciberseguridad se expande. Una mínima brecha de código maliciosa puede comprometer datos clave. Por ello, auditar vulnerabilidades periódicamente y blindar los sistemas resulta una medida imperativa."}]}, {"meanings_summary": {"en": "to strike; to hit; to beat; to attack; to beat back", "es": "golpear; pegar; asestar; atacar; abatir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A heavy mallet striking downward with precision force (击) delivers a crushing blow that can defeat any foe.", "composite_memory_hook_es": "Un mazo que desciende con fuerza e impacto certero (击) asesta un golpe decisivo capaz de batir al rival.", "cultural_and_cognitive_roots": "In ancient martial arts and percussion music, '击' carried both the cultural resonance of rhythmically striking ritual bronze drums and bells (击钟叩磐) and martial combat prowess.", "tone_sandhi_and_pitch_modulation": "High level 1st tone: jī (55). Pronounce with high, ringing, sustained vocal pitch."}, "semantic_boundary_contrasts": {"core_nuance": "击 highlights focused, sharp, targeted kinetic impact or military and competitive victory.", "contrasts": [{"id": "1", "compared_word": "击 vs. 打", "pinyin": "dǎ", "analysis": "击 is formal, literary, and precise, standard in written compounds (攻击, 击败, 目击), while 打 is the versatile everyday spoken verb for hitting, beating, or playing."}, {"id": "2", "compared_word": "击 vs. 撞", "pinyin": "zhuàng", "analysis": "击 implies an intentional or ballistic strike against a target, whereas 撞 focuses on physical collisions, bumps, or running into things."}, {"id": "3", "compared_word": "击 vs. 拍", "pinyin": "pāi", "analysis": "击 delivers heavy concussive force, while 拍 describes a flat, broad, or gentle slapping/patting motion (拍手, 拍球)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "击", "pinyin": "jī", "meaning_en": "strike; hit", "distinction_note": "Five strokes with a vertical line extending through"}, {"character": "出", "pinyin": "chū", "meaning_en": "exit; go out", "distinction_note": "Composed of two stacked mountain shapes (山)"}, {"character": "陆", "pinyin": "lù", "meaning_en": "land; shore", "distinction_note": "Has 阝 (mound) on the left and 击 on the right"}, {"character": "缶", "pinyin": "fǒu", "meaning_en": "earthen jar; pottery", "distinction_note": "The traditional phonetic component of 擊"}], "etymological_cognates": [{"character": "攻击", "pinyin": "gōng jī", "gloss_en": "attack; assault; accuse"}, {"character": "点击", "pinyin": "diǎn jī", "gloss_en": "click (mouse / link)"}, {"character": "游击", "pinyin": "yóu jī", "gloss_en": "guerrilla warfare; hit-and-run"}, {"character": "抗击", "pinyin": "kàng jī", "gloss_en": "resist; fight back against"}]}, "id": "20", "hanzi": "击", "pinyin": "jī", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to hit or strike an object or target with sharp physical force", "definition_es": "golpear o asestar un impacto con fuerza sobre un blanco", "example_phrase": "猛烈击打 (strike violently)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Formal", "definition_en": "to attack, defeat, or strike down militarily or competitively", "definition_es": "atacar, batir o asestar un golpe decisivo", "example_phrase": "击败对手 (defeat an opponent)"}], "example_sentences": [{"id": "#1", "hanzi": "巨浪以千钧之力重重击打在帆船前甲板上，激起数米高的白色水花，发出震耳欲聋的轰鸣。", "pinyin": "Jùlàng yǐ qiānjūn zhī lì zhòngzhòng jīdǎ zài fānchuán qián jiǎbǎn shàng, jīqǐ shù mǐ gāo de báisè shuǐhuā, fāchū zhèn'ěryùlóng de hōngmíng.", "en": "Massive breakers slammed onto the foredeck with crushing momentum, kicking up tall white spray with a deafening roar.", "es": "Una ola gigantesca golpeó la proa con demoledora potencia, levantando metros de espuma blanca con un rugido ensordecedor."}, {"id": "#2", "hanzi": "在国际网球公开赛决赛中，年轻选手凭借出色的发球与沉着的心态，最终连胜两盘击败强劲对手。", "pinyin": "Zài guójì wǎngqiú gōngkāisài juésài zhōng, niánqīng xuǎnshǒu píngjiè chūsè de fāqiú yǔ chénzhuó de xīntài, zuìzhōng liánshèng liǎng pán jībài qiángjìn duìshǒu.", "en": "In the international tennis open finals, the young contender relied on brilliant serves and poise to defeat a formidable rival in straight sets.", "es": "En la final del abierto internacional de tenis, el joven jugador desplegó un saque magistral y gran aplomo para batir a su formidable rival en dos sets consecutivos."}], "collocations": [{"hanzi": "击败", "en": "defeat; beat; overcome"}, {"hanzi": "打击", "en": "hit; strike; crack down on"}, {"hanzi": "击中", "en": "hit the target; strike home"}, {"hanzi": "目击", "en": "witness with one's own eyes"}, {"hanzi": "重击", "en": "heavy strike; heavy blow"}, {"hanzi": "反击", "en": "counterattack; strike back"}], "idioms": [{"hanzi": "不堪一击", "pinyin": "bù kān yì jī", "meaning_en": "cannot withstand a single blow; collapse at first touch"}, {"hanzi": "声东击西", "pinyin": "shēng dōng jī xī", "meaning_en": "make a feint to the east and attack in the west"}, {"hanzi": "乘胜追击", "pinyin": "chéng shèng zhuī jī", "meaning_en": "follow up a victory and pursue retreating foes"}, {"hanzi": "迎头痛击", "pinyin": "yíng tóu tòng jī", "meaning_en": "deliver a head-on devastating blow; strike back squarely"}], "character_decomposition": [{"character": "击", "pinyin": "jī", "meaning_en": "strike; beat; attack", "meaning_es": "golpear; atacar; batir", "radical": "十", "radical_meaning_en": "ten / cross", "meaning_component": "十 (interlocking lines of impact)", "sound_component": "缶 / 手 (hand wielding a stick striking a target)", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient ideograph of an arm wielding a wooden stick to strike down upon an earthen jar (缶).", "visual_mnemonic_story_en": "A clenched hand driving a mallet downward (击) to strike squarely against a wooden drum.", "visual_mnemonic_story_es": "Una mano empuñando un mazo (击) que golpea con fuerza certera sobre un tambor de madera.", "tone_mnemonic_anchor": "55", "cangjie": "QU", "traditional": "擊"}], "extended_reading_passages": [{"id": "#1", "hanzi": "生命的成长往往伴随着严酷风雨的击打。只有经历过疾风暴雨的洗礼，幼苗才能将根须深深扎进泥土深处。那些曾经看似无法承受的重击，终将成为岁月馈赠的铠甲，赋予我们直面人生波涛的从容与底气。", "pinyin": "Shēngmìng de chéngzhǎng wǎngwǎng bànsuí zhe yánkù fēngyǔ de jīdǎ. Zhǐyǒu jīnglì guò jífēngbàoyǔ de xǐlǐ, yòumiáo cáinéng jiāng gēnxū shēnshēn zhā jìn nítǔ shēnchù. Nàxiē céngjīng kànsì wúfǎ chéngshòu de zhòngjī, zhōng jiāng chéngwéi suìyuè kuìzèng de kǎijiǎ, fùyǔ wǒmen zhímiàn rénshēng bōtāo de cóngròng yǔ dǐqì.", "en": "Growth is ever forged by the battering of fierce tempests. Only weathered by harsh storms can saplings sink deep roots into bedrock soil. Those once unbearable impacts ultimately harden into armor, bestowing poise to face life's waves.", "es": "Crecer implica encajar el azote del temporal. Solo curtido por las lluvias torrenciales el brote hunde sus raíces en la tierra profunda. Los golpes otrora insoportables se tornan armadura que forja el aplomo para surcar las aguas bravas de la vida."}, {"id": "#2", "hanzi": "宏观经济运行难免遭遇外部冲击。面对全球产业链供应链断裂风险，相关监管部门实施精准有力的财政与货币逆周期调控，严厉打击各类市场投机炒作行为，有效化解系统性金融风险，保障了国民经济平稳健康运行与宏观大局稳定。", "pinyin": "Hóngguān jīngjì yùnxíng nánmiǎn zāoyù wàibù chōngjī. Miànduì quánqiú chǎnyèliàn gōngyìngliàn duànliè fēngxiǎn, xiāngguān jiānguǎn bùmén shíshī jīngzhǔn yǒulì de cáizhèng yǔ huòbì nìzhōuqī tiáokòng, yánlì dǎjī gèlèi shìchǎng tóujī chǎozuò xíngwéi, yǒuxiào huàjiě xìtǒngxìng jīnróng fēngxiǎn, bǎozhàng le guómín jīngjì píngwěn jiànkāng yùnxíng yǔ hóngguān dàjú wěndìng.", "en": "Macroeconomic cycles inevitably absorb external shocks. Confronting global supply chain disruptions, regulators deploy countercyclical fiscal and monetary levers, cracking down on speculative volatility to dissolve systemic risks and secure stable economic progress.", "es": "La economía sufre periódicos impactos externos. Ante el riesgo de ruptura en las cadenas de suministro mundiales, los reguladores aplican políticas anticíclicas y combaten la especulación financiera, conjurando riesgos sistémicos para asegurar un crecimiento sano y estable."}]}, {"meanings_summary": {"en": "classifier for meals, reproaches, or beatings; to pause; sudden; immediately", "es": "clasificador para comidas, reprimendas o palizas; pausar; de pronto; de repente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Halting one's journey to bow the head (页) and rest at a tavern (屯) offers a welcome pause and a satisfying meal (顿).", "composite_memory_hook_es": "Detener el camino para inclinar la cabeza (页) en la posada (屯) regala una merecida pausa y una rica comida (顿).", "cultural_and_cognitive_roots": "In ancient ritual etiquette, '顿首' represented kowtowing with head touching ground. It extended sequentially to pauses in movement, rhythmic caesuras in speech, and daily meal intervals.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone: dùn (51). When paired with '一' (yī), '一' changes to 2nd tone: 'yí dùn' (35-51). Pronounce with crisp, distinct falling pitch."}, "semantic_boundary_contrasts": {"core_nuance": "顿 serves as a discrete event classifier for complete dining sessions, episodic scoldings, or momentary pauses.", "contrasts": [{"id": "1", "compared_word": "顿 vs. 餐", "pinyin": "cān", "analysis": "顿 is the versatile everyday oral classifier for meals (吃了一顿饭), while 餐 is formal and combines into nouns for meal types (一日三餐, 早餐, 西餐)."}, {"id": "2", "compared_word": "顿 vs. 番", "pinyin": "fān", "analysis": "顿 modifies episodic meals or confrontations (训了一顿), whereas 番 classifies prolonged cognitive processes, investigations, or soul-searching (一番思考, 一番苦心)."}, {"id": "3", "compared_word": "顿 vs. 阵", "pinyin": "zhèn", "analysis": "顿 implies a complete single episode from start to finish, while 阵 designates intermittent, gusting bursts of wind, rain, or laughter."}]}, "traps_and_cognates": {"look_alikes": [{"character": "顿", "pinyin": "dùn", "meaning_en": "meal; pause", "distinction_note": "Has 屯 on the left and 页 on the right"}, {"character": "领", "pinyin": "lǐng", "meaning_en": "lead; collar", "distinction_note": "Has 令 on the left and 页 on the right"}, {"character": "预", "pinyin": "yù", "meaning_en": "in advance; anticipate", "distinction_note": "Has 予 on the left and 页 on the right"}, {"character": "顶", "pinyin": "dǐng", "meaning_en": "crown; top", "distinction_note": "Has 丁 on the left and 页 on the right"}], "etymological_cognates": [{"character": "顿时", "pinyin": "dùn shí", "gloss_en": "immediately; at once"}, {"character": "顿悟", "pinyin": "dùn wù", "gloss_en": "sudden enlightenment; epiphany"}, {"character": "整顿", "pinyin": "zhěng dùn", "gloss_en": "reorganize; consolidate; overhaul"}, {"character": "停顿", "pinyin": "tíng dùn", "gloss_en": "pause; standstill"}]}, "id": "21", "hanzi": "顿", "pinyin": "dùn", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "classifier for meals, dining occasions, or culinary feasts", "definition_es": "clasificador para comidas, platos o banquetes", "example_phrase": "吃一顿大餐 (eat a sumptuous meal)"}, {"sense_number": "2", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "classifier for bouts of scolding, beating, or reprimand", "definition_es": "clasificador para reprimendas, riñas o golpes", "example_phrase": "挨了一顿训斥 (received a severe reprimand)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Formal", "definition_en": "to pause, halt briefly, or stamp one's foot", "definition_es": "hacer una pausa breve; detenerse; dar una patada en el suelo", "example_phrase": "停顿了一下 (paused for a moment)"}], "example_sentences": [{"id": "#1", "hanzi": "经过数日的艰苦航行，全家人终于靠岸休整，在海港小镇上痛快地吃了一顿丰盛的海鲜大餐。", "pinyin": "Jīngguò shù rì de jiānkǔ hángxíng, quán jiārén zhōngyú kào'àn xiūzhěng, zài hǎigǎng xiǎozhèn shàng tòngkuai de chī le yí dùn fēngshèng de hǎixiān dàcān.", "en": "After days of arduous sailing, the family finally docked to rest, heartily enjoying a lavish seafood meal in the coastal town.", "es": "Tras días de dura travesía la familia atracó para descansar y disfrutó de una copiosa comida marinera en el pueblo costero."}, {"id": "#2", "hanzi": "演讲者在谈及核心数据时稍作停顿，吸引了全场观众的专注目光，随后条分缕析地展开阐述。", "pinyin": "Yǎnjiǎngzhě zài tánjí héxīn shùjù shí shāo zuò tíngdùn, xīyǐn le quánchǎng guānzhòng de zhuānzhù mùguāng, suíhòu tiáofēnlǚxī de zhǎnkāi chǎnshù.", "en": "The speaker paused briefly when touching upon core metrics, drawing the audience's focused gaze before expounding in detail.", "es": "El ponente hizo una breve pausa al citar las cifras clave, captando la atención de la sala antes de desgranar su exposición con rigor."}], "collocations": [{"hanzi": "一顿饭", "en": "a meal"}, {"hanzi": "一顿美餐", "en": "a delicious meal"}, {"hanzi": "停顿", "en": "pause; halt"}, {"hanzi": "整顿", "en": "rectify; reorganize; consolidate"}, {"hanzi": "安顿", "en": "settle down; arrange accommodation"}, {"hanzi": "挨一顿打", "en": "suffer a beating"}], "idioms": [{"hanzi": "茅塞顿开", "pinyin": "máo sè dùn kāi", "meaning_en": "suddenly enlightened; murky thoughts cleared away in an instant"}, {"hanzi": "顿开茅塞", "pinyin": "dùn kāi máo sè", "meaning_en": "suddenly have one's mind opened; sudden flash of insight"}, {"hanzi": "抑扬顿挫", "pinyin": "yì yáng dùn cuò", "meaning_en": "modulated cadence and rhythm; rising and falling cadences of voice"}, {"hanzi": "顿足捶胸", "pinyin": "dùn zú chuí xiōng", "meaning_en": "stamp feet and beat breast in deep grief or fury"}], "character_decomposition": [{"character": "顿", "pinyin": "dùn", "meaning_en": "pause; meal classifier; bow head", "meaning_es": "pausar; clasificador de comidas; inclinar cabeza", "radical": "页", "radical_meaning_en": "head / face", "meaning_component": "页 (head bowing down to the ground)", "sound_component": "屯 (tún phonetic / camp or gather)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: bowing one's head (页) repeatedly to the ground in ceremonial pause or greeting.", "visual_mnemonic_story_en": "A weary traveler resting his head (页) at a military camp (屯) to enjoy a hearty meal and brief pause.", "visual_mnemonic_story_es": "Un viajero fatigado que inclina la cabeza (页) en el campamento (屯) para saborear una reconfortante comida.", "tone_mnemonic_anchor": "51", "cangjie": "PUMBO", "traditional": "頓"}], "extended_reading_passages": [{"id": "#1", "hanzi": "漂泊海外的游子，最魂牵梦绕的永远是母亲亲手做的一顿家常便饭。那缕从厨房飘出的热气，不仅仅是食物的滋味，更是一整座故乡的温存。无论身在何方，那一顿饭的温暖总能抚慰心头所有的漂泊与风尘。", "pinyin": "Piāobó hǎiwài de yóuzǐ, zuì húnqiānmèngrào de yǒngyuǎn shì mǔqīn qīnshǒu zuò de yí dùn jiāchángbiànfàn. Nà lǚ cóng chúfáng piāochū de rèqì, bù zhǐzhǐ shì shíwù de zīwèi, gèng shì yì zhěng zuò gùxiāng de wēncún. Wúlùn shēn zài héfāng, nà yí dùn fàn de wēnnuǎn zǒng néng fǔwèi xīntóu suǒyǒu de piāobó yǔ fēngchén.", "en": "For wanderers overseas, nothing haunts dreams like a home-cooked meal prepared by mother. Kitchen aromas bring not just flavor, but the warmth of an entire homeland. Wherever one roams, that meal's comfort consoles all weary drifting.", "es": "Para el viajero en ultramar, nada puebla los sueños como una comida casera preparada por su madre. El vapor del fogón no es mero sustento, sino el calor de la tierra natal que consuela fatigas y nostalgias en cualquier rincón del mundo."}, {"id": "#2", "hanzi": "宏观监管部门针对平台经济领域的不正当竞争行为展开了专项整顿。通过设立清晰合规指引与反垄断执法，依法依规促使相关企业全面自查整改。这一轮市场整顿不仅有效遏制了资本无序扩张，也为中小微创新企业营造了公平竞争的营商环境。", "pinyin": "Hóngguān jiānguǎn bùmén zhēnduì píngtái jīngjì lǐngyù de búzhengdàng jìngzhēng xíngwéi zhǎnkāi le zhuānxiàng zhěngdùn. Tōngguò shèlì qīngxī héguī zhǐyǐn yǔ fǎnlǒngduàn zhífǎ, yīfǎ yīguī cùshǐ xiāngguān qǐyè quánmiàn zìchá zhěnggǎi. Zhè yì lún shìchǎng zhěngdùn bùjǐn yǒuxiào èzhì le zīběn wúxù kuòzhāng, yě wèi zhōngxiǎowēi chuàngxīn qǐyè yíngzào le gōngpíng jìngzhēng de yíngshāng huánjìng.", "en": "Regulatory bodies launched targeted rectifications targeting unfair platform competition. Anti-monopoly compliance frameworks guided corporate self-corrections, checking disorderly capital expansion while fostering equitable market terrain for innovative small and medium enterprises.", "es": "Los reguladores iniciaron inspecciones sectoriales contra la competencia desleal en plataformas digitales. La supervisión antimonopolio frenó la especulación del capital y procuró un entorno de libre concurrencia equitativo para las pequeñas empresas innovadoras."}]}, {"meanings_summary": {"en": "to take turns; to rotate; in turn; alternately", "es": "turnarse; alternar; por turnos; sucesivamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Like a revolving carriage wheel (轮) flowing smoothly down a river (流), people step up to take turns (轮流).", "composite_memory_hook_es": "Como una rueda que gira (轮) y el agua que fluye continua (流), las personas se suceden al turnarse (轮流).", "cultural_and_cognitive_roots": "Traditional Chinese cosmology viewed cycles as rotating wheels ('风水轮流转'). In communal living, cooperative task-sharing through turns ensured collective survival and fairness.", "tone_sandhi_and_pitch_modulation": "Two consecutive rising 2nd tones: lún liú (35-35). Modulate both syllables with a balanced, upward vocal rise."}, "semantic_boundary_contrasts": {"core_nuance": "轮流 stresses cyclic, orderly alternation among multiple individuals to execute a shared duty.", "contrasts": [{"id": "1", "compared_word": "轮流 vs. 交替", "pinyin": "jiāotì", "analysis": "轮流 specifically emphasizes people taking turns for shifts or tasks in orderly sequence (轮流守夜), whereas 交替 is more abstract and formal, describing natural alternating cycles (新旧交替, 昼夜交替)."}, {"id": "2", "compared_word": "轮流 vs. 轮番", "pinyin": "lúnfān", "analysis": "轮流 denotes regular, cooperative task sharing, whereas 轮番 often describes aggressive, intense, repeated onslaughts or rounds (轮番轰炸, 轮番上阵)."}, {"id": "3", "compared_word": "轮流 vs. 依次", "pinyin": "yīcì", "analysis": "轮流 emphasizes rotation over time, whereas 依次 denotes static spatial or ordinal succession (依次入场)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "轮", "pinyin": "lún", "meaning_en": "wheel; turn", "distinction_note": "Has 车 (cart) on the left and 仑 on the right"}, {"character": "论", "pinyin": "lùn", "meaning_en": "discuss; discourse", "distinction_note": "Has 讠 (speech) on the left with 仑"}, {"character": "流", "pinyin": "liú", "meaning_en": "flow; drift", "distinction_note": "Has 氵 (water) on the left"}, {"character": "梳", "pinyin": "shū", "meaning_en": "comb", "distinction_note": "Has 木 (wood) on the left with 㐬"}], "etymological_cognates": [{"character": "轮子", "pinyin": "lún zi", "gloss_en": "wheel; caster"}, {"character": "轮换", "pinyin": "lún huàn", "gloss_en": "rotate; take turns substituting"}, {"character": "流动", "pinyin": "liú dòng", "gloss_en": "flow; circulate; mobile"}, {"character": "流程", "pinyin": "liú chéng", "gloss_en": "workflow; technological process"}]}, "id": "22", "hanzi": "轮流", "pinyin": "lún liú", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to take turns in succession; to do something alternately in cyclical rotation", "definition_es": "turnarse; alternar en una tarea o función de forma rotativa", "example_phrase": "轮流值班 (take turns on duty)"}], "example_sentences": [{"id": "#1", "hanzi": "在漫长而危险的夜间航行中，夫妻俩轮流掌舵守夜，确保帆船始终保持在正确的航道上。", "pinyin": "Zài màncháng ér wēixiǎn de yèjiān hángxíng zhōng, fūqī liǎ lúnliú zhǎngduò shǒuyè, quèbǎo fānchuán shǐzhōng bǎochí zài zhèngquè de hángdào shàng.", "en": "During treacherous night sailing, the couple took turns at the helm to keep watch, ensuring the yacht stayed on its course.", "es": "En la peligrosa navegación nocturna, los esposos se turnaban al timón para hacer guardia y mantener el velero en el rumbo exacto."}, {"id": "#2", "hanzi": "为了保障二十四小时不间断技术支持，数据运维团队成员轮流在节假日留守值班。", "pinyin": "Wèile bǎozhàng èrshísì xiǎoshí bú jiànduàn jìshù zhīchí, shùjù yùnwéi tuánduì chéngyuán lúnliú zài jiérìjià qī liúshǒu zhíbān.", "en": "To ensure uninterrupted 24-hour technical support, data operations members take turns staffing shifts over holidays.", "es": "Para garantizar asistencia técnica continua las veinticuatro horas, el equipo de soporte se turna en guardias durante los días festivos."}], "collocations": [{"hanzi": "轮流值日", "en": "take turns on daily duty"}, {"hanzi": "轮流发言", "en": "speak in turn"}, {"hanzi": "轮流照顾", "en": "take turns caring for"}, {"hanzi": "轮流掌舵", "en": "take turns at the helm"}, {"hanzi": "轮流休息", "en": "take turns resting"}, {"hanzi": "轮流坐庄", "en": "take turns being banker / hosting"}], "idioms": [{"hanzi": "风水轮流转", "pinyin": "fēng shuǐ lún liú zhuàn", "meaning_en": "fortune turns like a wheel; times change and fortunes rotate"}, {"hanzi": "川流不息", "pinyin": "chuān liú bù xī", "meaning_en": "flowing like an endless river; non-stop stream"}, {"hanzi": "源远流长", "pinyin": "yuán yuǎn liú cháng", "meaning_en": "having a long history; flowing from a distant source"}, {"hanzi": "随波逐流", "pinyin": "suí bō zhú liú", "meaning_en": "drift with the waves; blindly follow the crowd"}], "character_decomposition": [{"character": "轮", "pinyin": "lún", "meaning_en": "wheel; rotate; turn", "meaning_es": "rueda; rotar; turno", "radical": "车", "radical_meaning_en": "cart / vehicle", "meaning_component": "车 (wheeled cart rolling)", "sound_component": "仑 (lún phonetic / order or sequence)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: cart wheels (车) revolving in sequential succession (仑).", "visual_mnemonic_story_en": "A rolling cart wheel (车) completing orderly revolutions (仑) turn after turn.", "visual_mnemonic_story_es": "Una rueda de carro (车) que gira sin cesar en rotación sucesiva y ordenada (仑).", "tone_mnemonic_anchor": "35", "cangjie": "KQOP", "traditional": "輪"}, {"character": "流", "pinyin": "liú", "meaning_en": "flow; stream; drift", "meaning_es": "fluir; corriente; circular", "radical": "氵", "radical_meaning_en": "water / liquid", "meaning_component": "氵 (flowing water currents)", "sound_component": "㐬 (liú phonetic / child newborn head down or hair flowing)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Ancient pictograph of water ripples (氵) streaming along without obstruction like flowing hair (㐬).", "visual_mnemonic_story_en": "Clear mountain water (氵) streaming effortlessly down a rocky brook (流).", "visual_mnemonic_story_es": "Agua cristalina (氵) que fluye dócil e ininterrumpida por el lecho de un arroyo (流).", "tone_mnemonic_anchor": "35", "cangjie": "EYIU", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在茫茫大海上漂泊的日子里，全家三口人轮流坚守在狭窄的驾驶舱中。当夜幕降临，风浪渐起，一人掌舵，一人观察雷达，一人抓紧时间在后舱休息。这种风雨同舟的默契与协作，让孤独的航程充满了无尽的温情。", "pinyin": "Zài mángmáng dàhǎi shàng piāobó de rìzi lǐ, quán jiā sān kǒu rén lúnliú jiānshǒu zài xiázǎi de jiàshǐcāng zhōng. Dāng yèmù jiànglín, fēnglàng jiàn qǐ, yì rén zhǎngduò, yì rén guānchá léidá, yì rén zhuājǐn shíjiān zài hòucāng xiūxi. Zhè zhǒng fēngyǔtóngzhōu de mòqì yǔ xiézuò, ràng gūdú de hángchéng chōngmǎn le wújìn de wēnqíng.", "en": "Drifting upon the boundless main, the family of three took turns manning the cockpit. As night fell and swells arose, one held the helm, one watched radar, and one rested. Such unspoken solidarity warmed an otherwise lonely voyage.", "es": "A merced del océano inmenso, la familia de tres se turnaba en la cabina de mando. Al caer la noche y crecer las olas, uno gobernaba, otro vigilaba el radar y el tercero descansaba. Esa complicidad hermanada colmó de ternura la solitaria travesía."}, {"id": "#2", "hanzi": "现代应急管理机制强调跨部门协同作战。在应对台风等极端气象灾害时，气象、水利与交通部门建立了轮流值守与实时会商制度。通过不间断的数据共享与应急响应联动，各部门能够精准研判汛情演化，全面提升灾害防御处置效能。", "pinyin": "Xiàndài yìngjí guǎnlǐ jīzhì qiángdiào kuàbùmén xiétóng zuòzhàn. Zài yìngduì táifēng děng jíduān qìxiàng zāihài shí, qìxiàng, shuǐlì yǔ jiāotōng bùmén jiànlì le lúnliú zhíshǒu yǔ shíshí huìshāng zhìdù. Tōngguò bújiànduàn de shùjù gòngxiǎng yǔ yìngjí xiǎngyìng liándòng, gè bùmén nénggòu jīngzhǔn yánpàn xùnqíng yǎnhuà, quánmiàn tíshēng zāihài fángyù chǔzhì xiàonéng.", "en": "Emergency management highlights inter-departmental synergy. In battling typhoons, meteorological, water, and transit bureaus establish rotating watches and joint sessions. Seamless data-sharing and linked responses enable precise flood assessment and robust disaster mitigation.", "es": "La gestión de emergencias exige sinergia entre departamentos. Frente a tifones y desastres, los servicios meteorológicos, hidráulicos y de tráfico establecen guardias rotatorias y consultas conjuntas, blindando la capacidad de respuesta y mitigación de catástrofes."}]}, {"meanings_summary": {"en": "seafood; ocean delicacies; edible marine animals", "es": "marisco; mariscos; frutos del mar; viandas marinas"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Savoring marine delicacies harvested from the deep ocean (海) that combine fish and meat flavors (鲜) defines delicious seafood (海鲜).", "composite_memory_hook_es": "Saborear viandas cosechadas en el mar profundo (海) que conjugan pescado y exquisitez (鲜) define el rico marisco (海鲜).", "cultural_and_cognitive_roots": "In Chinese gastronomy, '鲜' (xiān) is the fifth fundamental taste alongside sweet, sour, bitter, and salty. Coastal dwellers regarded ocean bounty as heaven-sent sustenance celebrated through seasonal banquets.", "tone_sandhi_and_pitch_modulation": "Dipping 3rd tone followed by a high level 1st tone: hǎi xiān (214-55). Dip 'hǎi' down smoothly before sustaining 'xiān' steadily at high pitch."}, "semantic_boundary_contrasts": {"core_nuance": "海鲜 specifically denotes edible marine fauna (fish, shrimp, crabs, clams) harvested from saltwater environments.", "contrasts": [{"id": "1", "compared_word": "海鲜 vs. 水产", "pinyin": "shuǐchǎn", "analysis": "海鲜 refers specifically to saltwater food delicacies for human dining, whereas 水产 is an industrial/agricultural umbrella term encompassing freshwater and marine aquaculture (水产业)."}, {"id": "2", "compared_word": "海鲜 vs. 鱼类", "pinyin": "yúlèi", "analysis": "海鲜 includes mollusks, crustaceans, squid, and shellfish in culinary dining, while 鱼类 is a biological classification restricted exclusively to finned fish."}, {"id": "3", "compared_word": "海鲜 vs. 野味", "pinyin": "yěwèi", "analysis": "海鲜 denotes marine aquatic foods, whereas 野味 refers specifically to wild game animals hunted from forests and land habitats."}]}, "traps_and_cognates": {"look_alikes": [{"character": "海", "pinyin": "hǎi", "meaning_en": "sea; ocean", "distinction_note": "Has 氵 (water) on the left and 每 on the right"}, {"character": "梅", "pinyin": "méi", "meaning_en": "plum tree", "distinction_note": "Has 木 (wood) on the left with 每"}, {"character": "鲜", "pinyin": "xiān / xiǎn", "meaning_en": "fresh; rare", "distinction_note": "Has 鱼 on the left and 羊 on the right"}, {"character": "群", "pinyin": "qún", "meaning_en": "crowd; group", "distinction_note": "Has 君 on top/left with 羊"}], "etymological_cognates": [{"character": "海洋", "pinyin": "hǎi yáng", "gloss_en": "ocean; maritime waters"}, {"character": "海港", "pinyin": "hǎi gǎng", "gloss_en": "seaport; harbor"}, {"character": "新鲜", "pinyin": "xīn xiān", "gloss_en": "fresh; novel; new"}, {"character": "鲜美", "pinyin": "xiān měi", "gloss_en": "delicious; savory; luscious"}]}, "id": "23", "hanzi": "海鲜", "pinyin": "hǎi xiān", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "edible fish, shellfish, crabs, and aquatic organisms caught from the sea", "definition_es": "animales marinos comestibles (peces, mariscos, crustáceos)", "example_phrase": "吃海鲜 (eat seafood)"}], "example_sentences": [{"id": "#1", "hanzi": "经过数星期的远洋航行，帆船停靠在热带小岛港湾，一家人品尝到了刚捕捞上来的鲜美海鲜。", "pinyin": "Jīngguò shù xīngqī de yuǎnyáng hángxíng, fānchuán tíngkào zài rèdài xiǎodǎo gǎngwān, yì jiā rén pǐncháng dào le gāng bǔlāo shànglái de xiānměi hǎixiān.", "en": "Following weeks of ocean cruising, the sailboat docked in a tropical lagoon, where the family relished succulent freshly caught seafood.", "es": "Tras semanas de singladura oceánica, el velero atracó en la bahía de una isla tropical, donde la familia degustó marisco fresco recién capturado."}, {"id": "#2", "hanzi": "沿海城市依托冷链物流与深海养殖基地，将优质活体海鲜在二十四小时内高效配送至内陆核心商圈。", "pinyin": "Yánhǎi chéngshì yītuō lěngliàn wùliú yǔ shēnhǎi yǎngzhí jīdì, jiāng yōuzhì huótǐ hǎixiān zài èrshísì xiǎoshí nèi gāoxiào pèisòng zhì nèilù héxīn shāngquān.", "en": "Coastal hubs leverage cold-chain logistics and mariculture farms to dispatch live seafood to inland commercial districts within 24 hours.", "es": "Las ciudades costeras aprovechan la cadena de frío y la acuicultura marina para suministrar marisco vivo a las urbes del interior en 24 horas."}], "collocations": [{"hanzi": "吃海鲜", "en": "eat seafood"}, {"hanzi": "海鲜大餐", "en": "seafood feast"}, {"hanzi": "新鲜海鲜", "en": "fresh seafood"}, {"hanzi": "海鲜市场", "en": "seafood market"}, {"hanzi": "海鲜火锅", "en": "seafood hotpot"}, {"hanzi": "海鲜过敏", "en": "seafood allergy"}], "idioms": [{"hanzi": "屡见不鲜", "pinyin": "lǚ jiàn bù xiān", "meaning_en": "seen so often as to be no longer novel; common occurrence"}, {"hanzi": "数见不鲜", "pinyin": "shuò jiàn bù xiān", "meaning_en": "common sight; nothing new"}, {"hanzi": "鲜为人知", "pinyin": "xiǎn wéi rén zhī", "meaning_en": "rarely known to people; little known"}, {"hanzi": "海晏河清", "pinyin": "hǎi yàn hé qīng", "meaning_en": "the sea is calm and the river clear; profound national peace"}], "character_decomposition": [{"character": "海", "pinyin": "hǎi", "meaning_en": "ocean; sea", "meaning_es": "mar; océano", "radical": "氵", "radical_meaning_en": "water / liquid", "meaning_component": "氵 (vast bodies of water)", "sound_component": "每 (měi phonetic / mother wearing hairpins or fertile abundance)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: water (氵) of motherly maternal immensity (每) that accepts every stream and river.", "visual_mnemonic_story_en": "Boundless rolling blue water (氵) nurturing countless living creatures like an all-giving mother (每).", "visual_mnemonic_story_es": "La inmensidad azul del agua (氵) que engendra y nutre la vida como una madre prolífica (每).", "tone_mnemonic_anchor": "214", "cangjie": "EOWY", "traditional": ""}, {"character": "鲜", "pinyin": "xiān", "meaning_en": "fresh; delicious; seafood", "meaning_es": "fresco; delicioso; vianda marina", "radical": "鱼", "radical_meaning_en": "fish", "meaning_component": "鱼 (fresh swimming fish)", "sound_component": "羊 (yáng phonetic / tender mutton or umami flavor)", "stroke_count": "14", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogrammic compound: pairing delicate fish (鱼) with savory lamb (羊), creating the quintessential Chinese definition of delicious umami.", "visual_mnemonic_story_en": "Combining fresh marine fish (鱼) with tender prairie lamb (羊) yields peak gastronomic freshness and flavor (鲜).", "visual_mnemonic_story_es": "La unión del pescado fresco (鱼) y el cordero tierno (羊) simboliza el culmen del sabor umami y la frescura (鲜).", "tone_mnemonic_anchor": "55", "cangjie": "NMTQ", "traditional": "鮮"}], "extended_reading_passages": [{"id": "#1", "hanzi": "黄昏的渔港总是弥漫着咸涩的海风与刚靠岸海鲜的鲜甜气息。渔民们满载而归，甲板上银鳞闪烁的鱼虾活蹦乱跳。支起一口铁锅，用最简单的清蒸烹制刚出海的美味，那是大海对辛劳耕海者最纯粹的慷慨馈赠。", "pinyin": "Huánghūn de yúgǎng zǒngshì mímàn zhe xiánsè de hǎifēng yǔ gāng kào'àn hǎixiān de xiāntián qìxī. Yúmínmen mǎnzài ér guī, jiǎbǎn shàng yínlín shǎnshuò de yúxiā huóbèngluàntiào. Zhī qǐ yì kǒu tiěguō, yòng zuì jiǎndān de qīngzhēng pēngzhì gāng chūhǎi de měiwèi, nà shì dàhǎi duì xīnláo gēnghǎizhě zuì chúncuì de kāngkǎi kuìzèng.", "en": "Twilight fishing ports brim with salty sea breezes and the sweet aroma of freshly landed seafood. Fishermen return laden, silvery scales leaping on decks. Steaming catch in an iron pot delivers the sea's purest, generous reward for maritime toil.", "es": "El puerto al atardecer huele a brisa salina y al aroma del marisco recién desembarcado. Los pescadores regresan con la bodega llena de peces que platean la cubierta. Cocer la pesca al vapor en una olla de hierro es el premio más generoso que el mar reserva a sus faenadores."}, {"id": "#2", "hanzi": "随着冷链物流技术的迭代升级与远洋捕捞产业的规范化发展，高品质生鲜海鲜实现了从深海捕捞船到内陆百姓餐桌的端到端保鲜直达。这一现代生鲜供应链体系不仅显著降低了物流损耗率，也极大丰富了大众的膳食营养结构。", "pinyin": "Suízhe lěngliàn wùliú jìshù de jiédài shēngjí yǔ yuǎnyáng bǔlāo chǎnyè de guīfànhuà fāzhǎn, gāopǐnzhì shēngxiān hǎixiān shíxiàn le cóng shēnhǎi bǔlāochuán dào nèilù bǎixìng cānzhuō de duāndàoduān bǎoxiān zhídá. Zhè yí xiàndài shēngxiān gōngyìngliàn tǐxì bùjǐn xiǎnzhù jiàngdī le wùliú sǔnhàolǜ, yě jídà fēngfù le dàzhòng de shànshí yíngyǎng jiégòu.", "en": "Upgrades in cold-chain logistics and distant-water fishing enable fresh seafood to transit swiftly from ocean vessels to inland tables. This cold-chain supply pipeline minimizes cargo spoilage while diversifying dietary nutrition for the general public.", "es": "La modernización logística de la cadena de frío y la pesca de altura permiten trasladar marisco fresco del barco a la mesa del interior en tiempo récord. Esta red de distribución reduce mermas y enriquece la nutrición y variedad de la dieta popular."}]}, {"meanings_summary": {"en": "towards evening; dusk; nightfall; twilight; sunset", "es": "al atardecer; al anochecer; crepúsculo; atardecer; caída de la tarde"}, "mnemonics_and_roots": {"composite_memory_hook_en": "As the sun begins to depart and draw near (傍) the evening hours (晚), twilight paints the sky at dusk (傍晚).", "composite_memory_hook_es": "Cuando la luz se arrima (傍) a las horas tardías de la noche (晚), el crepúsculo despide el día (傍晚).", "cultural_and_cognitive_roots": "In classical poetry, twilight ('暮' or '傍晚') is the quintessential reflective hour when farm plows rest, birds return to woods (倦鸟归林), and wandering poets contemplate home and the transient passage of time.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone followed by a dipping 3rd tone: bàng wǎn (51-214). Drop 'bàng' briskly from 5 to 1 before allowing 'wǎn' to dip down into 214."}, "semantic_boundary_contrasts": {"core_nuance": "傍晚 specifically pinpoints the transitional twilight window when daylight fades before darkness falls completely.", "contrasts": [{"id": "1", "compared_word": "傍晚 vs. 晚上", "pinyin": "wǎnshang", "analysis": "傍晚 denotes specifically dusk/sunset transition (roughly 5 PM to 7 PM), whereas 晚上 covers the entire nocturnal span from sunset until midnight or sleep."}, {"id": "2", "compared_word": "傍晚 vs. 黄昏", "pinyin": "huánghūn", "analysis": "傍晚 is an objective everyday time term, while 黄昏 carries rich, evocative literary, melancholic, and romantic poetic atmosphere (黄昏时分)."}, {"id": "3", "compared_word": "傍晚 vs. 午后", "pinyin": "wǔhòu", "analysis": "傍晚 refers to the sun dipping below the horizon at dusk, whereas 午后 refers broadly to the bright early hours following midday."}]}, "traps_and_cognates": {"look_alikes": [{"character": "傍", "pinyin": "bàng", "meaning_en": "near; draw near", "distinction_note": "Has 亻 (person) on the left and 旁 on the right"}, {"character": "旁", "pinyin": "páng", "meaning_en": "beside; side", "distinction_note": "Standalone character without 亻"}, {"character": "晚", "pinyin": "wǎn", "meaning_en": "evening; late", "distinction_note": "Has 日 (sun) on the left and 免 on the right"}, {"character": "挽", "pinyin": "wǎn", "meaning_en": "pull; draw back;挽救", "distinction_note": "Has 扌 (hand) on the left with 免"}], "etymological_cognates": [{"character": "依傍", "pinyin": "yī bàng", "gloss_en": "depend on; rely upon"}, {"character": "傍近", "pinyin": "bàng jìn", "gloss_en": "draw near to; approach"}, {"character": "晚上", "pinyin": "wǎn shang", "gloss_en": "evening; night"}, {"character": "夜晚", "pinyin": "yè wǎn", "gloss_en": "night; nighttime"}]}, "id": "24", "hanzi": "傍晚", "pinyin": "bàng wǎn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the period of the day when the sun is setting and darkness begins to fall; twilight", "definition_es": "momento del día en que el sol se pone y cae la noche; crepúsculo", "example_phrase": "傍晚时分 (at dusk / around twilight)"}], "example_sentences": [{"id": "#1", "hanzi": "每当傍晚来临，夕阳将整片洋面染成金红，全家人便站在帆船甲板上静静欣赏这壮丽的日落。", "pinyin": "Měi dāng bàngwǎn láilín, xīyáng jiāng zhěng piàn yángmiàn rǎn chéng jīnhóng, quán jiārén biàn zhàn zài fānchuán jiǎbǎn shàng jìngjìng xīnshǎng zhè zhuànglì de rìluò.", "en": "Whenever dusk arrived and the setting sun dyed the ocean gold and crimson, the family stood on deck quietly admiring the majestic sunset.", "es": "Al caer el atardecer y teñir el sol poniente el mar de dorado y grana, la familia contemplaba en silencio la grandiosa puesta de sol desde la cubierta."}, {"id": "#2", "hanzi": "气象监测站通常在每天傍晚汇总全天的卫星云图数据，为港口作业船只提供精准的夜间通航预报。", "pinyin": "Qìxiàng jiānkèzhàn tōngcháng zài měitiān bàngwǎn huìzǒng quántiān de wèixīng yúntú shùjù, wèi gǎngkǒu zuòyè chuánzhī tígōng jīngzhǔn de yèjiān tōngháng yùbào.", "en": "The meteorological station aggregates satellite cloud imagery every evening at dusk, delivering accurate nocturnal transit forecasts for harbor vessels.", "es": "La estación meteorológica consolida al anochecer las imágenes satelitales de la jornada para emitir partes precisos de navegación nocturna para los buques del puerto."}], "collocations": [{"hanzi": "傍晚时分", "en": "at twilight; toward evening"}, {"hanzi": "接近傍晚", "en": "approaching dusk"}, {"hanzi": "临近傍晚", "en": "nearing nightfall"}, {"hanzi": "傍晚的微风", "en": "evening breeze"}, {"hanzi": "在傍晚散步", "en": "take a walk at dusk"}, {"hanzi": "傍晚的天空", "en": "twilight sky"}], "idioms": [{"hanzi": "日薄西山", "pinyin": "rì bó xī shān", "meaning_en": "the sun is setting over the western hills; nearing the end of one's days"}, {"hanzi": "朝云暮雨", "pinyin": "zhāo yún mù yǔ", "meaning_en": "morning clouds and evening rain; fleeting amorous encounters"}, {"hanzi": "暮色苍茫", "pinyin": "mù sè cāng máng", "meaning_en": "dusk gathers hazy and deep; twilight shades envelop the landscape"}, {"hanzi": "夕阳西下", "pinyin": "xī yáng xī xià", "meaning_en": "the sun sets in the west; end of day"}], "character_decomposition": [{"character": "傍", "pinyin": "bàng", "meaning_en": "near; close to; draw near", "meaning_es": "arrimarse; acercarse; bordear", "radical": "亻", "radical_meaning_en": "person / human", "meaning_component": "亻 (person drawing near or leaning against)", "sound_component": "旁 (páng phonetic / side or lateral flank)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: a person (亻) standing beside or leaning near another's side (旁), extended to time approaching.", "visual_mnemonic_story_en": "A traveler (亻) leaning patiently by the side of the road (旁) as daylight begins to approach its end.", "visual_mnemonic_story_es": "Un caminante (亻) arrimado a la orilla del camino (旁) viendo cómo las horas del día se agotan.", "tone_mnemonic_anchor": "51", "cangjie": "OYBS", "traditional": ""}, {"character": "晚", "pinyin": "wǎn", "meaning_en": "evening; late; night", "meaning_es": "tarde; anochecer; noche", "radical": "日", "radical_meaning_en": "sun / day", "meaning_component": "日 (sun setting and light fading)", "sound_component": "免 (miǎn phonetic / take off or escape)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: the bright sun (日) taking leave and departing (免) from the sky, ushering in the evening.", "visual_mnemonic_story_en": "The blazing sun (日) taking off its fiery cloak (免) to rest quietly beneath the horizon.", "visual_mnemonic_story_es": "El sol radiante (日) despojándose de su manto de fuego (免) para reposar tras la línea del horizonte.", "tone_mnemonic_anchor": "214", "cangjie": "ANAU", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "乡村的傍晚最富诗意。当最后一抹夕阳滑落山脊，缕缕炊烟在晚霞中袅袅升起。牧童骑着水牛踏着暮色归家，劳作一天的农人扛着锄头走在田埂上。这幅平凡而安详的图景，洗去了世间所有的疲惫与浮华。", "pinyin": "Xiāngcūn de bàngwǎn zuì fù shīyì. Dāng zuìhòu yì mǒ xīyáng huáluò shānjǐ, lǚlǚ chuīyān zài wǎnxiá zhōng niǎoniǎo shēngqǐ. Mùtóng qí zhe shuǐniú tà zhe mùsè guījiā, láozuò yì tiān de nóngrén káng zhe chútou zǒu zài tiángěng shàng. Zhè fú píngfán ér ānxiáng de tújǐng, xǐqù le shìjiān suǒyǒu de píbèi yǔ fúhuá.", "en": "Rural dusk holds purest poetry. As final daylight glides behind ridges, hearth smoke spirals into sunset clouds. Cowherds ride buffaloes home while weary farmers tread ridges with hoes. This serene tableau gently cleanses worldly vanity and toil.", "es": "El atardecer rural encierra la máxima poesía. Al ocultarse el último rayo tras la loma, el humo del hogar sube hacia el arrebol. Pastores regresan con sus búfalos y labradores fatigosos cargan la azada. Esta estampa apacible lava las fatigas y vanidades del mundo."}, {"id": "#2", "hanzi": "城市生态环境微气候研究表明，傍晚时段往往是城市地表热岛效应与大气湍流交换最为活跃的交汇节点。合理规划城市通风廊道与水体绿地布局，能有效促进傍晚空气对流散热，缓解夏季高温积聚，全面提升居民夜间户外生活的宜居品质。", "pinyin": "Chéngshì shēngtài huánjìng wēiqìhòu yánjiū biǎomíng, bàngwǎn shíduàn wǎngwǎng shì chéngshì dìbiǎo rèdǎoxiàoyìng yǔ dàqì tuānliú jiāohuàn zuìwéi huóyuè de jiāohuì jiédiǎn. Hélǐ guīhuà chéngshì tōngfēng lángdào yǔ shuǐtǐ lǜdì bùjú, néng yǒuxiào cùjìn bàngwǎn kōngqì duìliú sànrè, huǎnjiě xiàjì gāowēn jījù, quánmiàn tíshēng jūmín yèjiān hùwài shēnghuó de yíjū pǐnzhì.", "en": "Microclimate studies show dusk marks peak heat-island mitigation and turbulence exchange in urban environments. Designing municipal ventilation corridors and greenbelts promotes twilight convective cooling, mitigating thermal buildup to enhance nighttime outdoor livability for city residents.", "es": "Estudios de microclima urbano revelan que el atardecer concentra el intercambio térmico de la isla de calor. Trazar corredores de viento y zonas verdes favorece la convección al caer la tarde, aliviando las temperaturas para asegurar una mejor calidad de vida nocturna."}]}, {"meanings_summary": {"en": "to look forward to; to long for; to yearn; eager expectation", "es": "anhelar; esperar con ilusión; ansiar; añorar; esperanza ilusionada"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Turning hopeful eyes (盼) to gaze into the distance (望) captures the feeling of longing and looking forward to reunion (盼望).", "composite_memory_hook_es": "Dirigir la mirada (盼) hacia el horizonte lejano (望) evoca el ardiente anhelo de ver cumplida una ilusión (盼望).", "cultural_and_cognitive_roots": "In classical poetry, climbing heights to gaze afar ('登高远望') connects the physical eye with spiritual yearning. '盼望' expresses the emotional tension between physical absence and mental anticipation.", "tone_sandhi_and_pitch_modulation": "Two consecutive falling 4th tones: pàn wàng (51-51). Articulate both syllables with decisive downward intensity."}, "semantic_boundary_contrasts": {"core_nuance": "盼望 denotes enthusiastic, focused, emotionally warm anticipation for an expected positive outcome.", "contrasts": [{"id": "1", "compared_word": "盼望 vs. 希望", "pinyin": "xīwàng", "analysis": "盼望 emphasizes the eager emotional waiting for an impending event (盼望假期, 盼望团聚), whereas 希望 is a general cognitive desire or aspiration for a future possibility (希望明天不下雨)."}, {"id": "2", "compared_word": "盼望 vs. 期望", "pinyin": "qīwàng", "analysis": "盼望 conveys personal emotional longing, while 期望 carries formal social, institutional, or parental expectations placed on someone's performance (父母的期望)."}, {"id": "3", "compared_word": "盼望 vs. 渴望", "pinyin": "kěwàng", "analysis": "盼望 focuses on waiting with hopeful anticipation, whereas 渴望 denotes a burning, desperate, visceral thirst or craving for something lacking."}]}, "traps_and_cognates": {"look_alikes": [{"character": "盼", "pinyin": "pàn", "meaning_en": "gaze; yearn", "distinction_note": "Has 目 (eye) on the left and 分 on the right"}, {"character": "份", "pinyin": "fèn", "meaning_en": "portion; share", "distinction_note": "Has 亻 (person) on the left with 分"}, {"character": "望", "pinyin": "wàng", "meaning_en": "gaze; hope", "distinction_note": "Has 亡 and 月 on top and 王 at the bottom"}, {"character": "忘", "pinyin": "wàng", "meaning_en": "forget", "distinction_note": "Has 亡 on top and 心 (heart) at the bottom"}], "etymological_cognates": [{"character": "企盼", "pinyin": "qǐ pàn", "gloss_en": "eagerly await; look forward"}, {"character": "期盼", "pinyin": "qī pàn", "gloss_en": "expect; look forward with hope"}, {"character": "希望", "pinyin": "xī wàng", "gloss_en": "hope; wish"}, {"character": "渴望", "pinyin": "kě wàng", "gloss_en": "thirst for; long for"}]}, "id": "25", "hanzi": "盼望", "pinyin": "pàn wàng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to wait with eager anticipation or keen longing for someone or something", "definition_es": "anhelar o aguardar con ilusión y vehemencia", "example_phrase": "盼望早日团聚 (look forward to an early reunion)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "earnest hope, expectation, or longing", "definition_es": "anhelo; esperanza ferviente; ilusión", "example_phrase": "充满盼望 (filled with eager hope)"}], "example_sentences": [{"id": "#1", "hanzi": "在茫茫大海上漂泊了数周后，全家人日夜盼望看到陆地的影子，那是重归人间的渴望。", "pinyin": "Zài mángmáng dàhǎi shàng piāobó le shù zhōu hòu, quán jiārén rìyè pànwàng kàndào lùdì de yǐngzi, nà shì chóngguī rénjiān de kěwàng.", "en": "Having drifted weeks on boundless waters, the family longed day and night for land, thirsting to step back onto earth.", "es": "Tras semanas a la deriva en el mar inmenso, la familia anhelaba día y noche avistar tierra firme, ansiosa por volver al mundo habitado."}, {"id": "#2", "hanzi": "广大科研人员多年如一日潜心攻关，终于迎来了盼望已久的核心技术重大突破。", "pinyin": "Guǎngdà kēyán rényuán duōnián rú yírì qiánxīn gōngguān, zhōngyú yínglái le pànwàng yǐ jiǔ de héxīn jìshù zhòngdà tūpò.", "en": "Toiling day after day over years, research scientists finally ushered in the long-anticipated breakthrough in core technologies.", "es": "Investigando con tenacidad durante años, los científicos alcanzaron al fin el ansiado avance decisivo en tecnologías clave."}], "collocations": [{"hanzi": "盼望已久", "en": "long-awaited; long anticipated"}, {"hanzi": "热切盼望", "en": "eagerly look forward to"}, {"hanzi": "盼望归来", "en": "yearn for return"}, {"hanzi": "心中的盼望", "en": "longing / hope in one's heart"}, {"hanzi": "殷切盼望", "en": "earnestly look forward to"}, {"hanzi": "默默盼望", "en": "quietly yearn for"}], "idioms": [{"hanzi": "望眼欲穿", "pinyin": "wàng yǎn yù chuān", "meaning_en": "gaze till one's eyes are strained; yearn with longing"}, {"hanzi": "翘首以盼", "pinyin": "qiáo shǒu yǐ pàn", "meaning_en": "raise one's head and look forward with eager longing"}, {"hanzi": "望穿秋水", "pinyin": "wàng chuān qiū shuǐ", "meaning_en": "gaze through autumn waters; gaze with longing for one's beloved"}, {"hanzi": "枯苗望雨", "pinyin": "kū miáo wàng yǔ", "meaning_en": "parched seedlings yearning for rain; long desperately for relief"}], "character_decomposition": [{"character": "盼", "pinyin": "pàn", "meaning_en": "look at; gaze; hope", "meaning_es": "mirar; otear; anhelar", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "目 (gazing eyes looking into distance)", "sound_component": "分 (fēn phonetic / divide or clear pupil)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: clear eyes (目) with distinct iris and white (分) gazing intently into the horizon.", "visual_mnemonic_story_en": "Alert eyes (目) focusing across dividing terrain (分) to spot an approaching dear friend.", "visual_mnemonic_story_es": "Ojos atentos y limpios (目) que otean el horizonte divisorio (分) esperando ver aparecer a un ser querido.", "tone_mnemonic_anchor": "51", "cangjie": "BUCS", "traditional": ""}, {"character": "望", "pinyin": "wàng", "meaning_en": "look into distance; hope; full moon", "meaning_es": "mirar a lo lejos; esperar; luna llena", "radical": "月", "radical_meaning_en": "moon", "meaning_component": "亡 (wáng phonetic / perish) + 臣 (servant eye looking wide)", "sound_component": "王 (tǐng / raised earth mound)", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient ideograph of a person standing on an elevated mound gazing up with wide eyes at the full moon.", "visual_mnemonic_story_en": "Standing upon a high mountain ridge gazing toward the glowing full moon (月) with deep longing.", "visual_mnemonic_story_es": "Subir a un cerro elevado para contemplar la luna llena (月) en el cielo con profunda nostalgia.", "tone_mnemonic_anchor": "51", "cangjie": "YTB", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "故乡的老母亲总是在每一个节日临近时，倚在门框边长久地盼望。山路上扬起的每一阵尘土，都曾点燃她心头的欢喜。那种对儿女归来的殷切盼望，是一根穿透千里风霜的丝线，永远系在远方游子的心头。", "pinyin": "Gùxiāng de lǎo mǔqīn zǒngshì zài měi yí gè jiérì línjìn shí, yǐ zài ménkuàng biān chángjiǔ de pànwàng. Shānlù shàng yángqǐ de měi yí zhèn chéntǔ, dōu céng diǎnrán tā xīntóu de huānxǐ. Nà zhǒng duì énnǚ guīlái de yīnqiè pànwàng, shì yì gēn chuāntòu qiānlǐ fēngshuāng de sīxiàn, yǒngyuǎn jì zài yuǎnfāng yóuzǐ de xīntóu.", "en": "An aging mother in the hometown leans against the doorframe whenever holidays near. Dust puffs on mountain trails kindle spark after spark of joy in her heart. That yearning for her children's return forms a tether spanning thousands of miles.", "es": "La anciana madre se asoma al quicio de la puerta al acercarse cada fiesta. El polvo que levantan los caminos aviva la ilusión en su pecho. El tierno anhelo de abrazar a los hijos es un hilo invisible que desafía mil leguas de distancia."}, {"id": "#2", "hanzi": "国际气候治理峰会承载了全球各国的殷切盼望。面对频发的极端天气与环境恶化挑战，各代表团本着对人类未来高度负责的科学态度，聚焦减排路线图展开磋商，力求在资金支持与技术转让领域达成具有实质约束力的多边合作成果。", "pinyin": "Guójì qìhòu zhìlǐ fēnghuì chéngzài le quánqiú gèguó de yīnqiè pànwàng. Miànduì pínfā de jíduān tiānqì yǔ huánjìng èhuà tiǎozhàn, gè dàibiǎotuán běnzhe duì rénlèi wèilái gāodù fùzé de kēxué tàidù, jùjiāo jiǎnpái lùxiàntú zhǎnkāi cuōshāng, lìqiú zài zījīn zhīchēng yǔ jìshù zhuǎnràng lǐngyù dáchéng jùyǒu shízhì yuēshùlì de duōbiān hézuò chéngguǒ.", "en": "The international climate summit shoulders the earnest hopes of nations worldwide. Addressing extreme weather shocks, delegations confer responsibly over emission-reduction roadmaps, striving to forge binding multilateral compacts on finance and green technology transfers.", "es": "La cumbre climática internacional concita la ferviente esperanza de los pueblos. Ante los desastres ecológicos, las delegaciones negocian con rigor planes de descarbonización para lograr pactos vinculantes en financiación verde y transferencia tecnológica."}]}, {"meanings_summary": {"en": "land; dry land (as opposed to sea or water)", "es": "tierra firme; tierra (en oposición al mar o agua)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Rising plateaus (陆) anchored in rich continental soil (地) form the stable dry land where humans dwell (陆地).", "composite_memory_hook_es": "Montículos elevados (陆) sobre tierra firme (地) forman el suelo continental donde la vida echa raíces (陆地).", "cultural_and_cognitive_roots": "Traditional cosmology divided the world into heaven, earth, and waters ('普天之下，莫非王土'). Seafarers viewed stepping onto land as an emotional rebirth and return to the ancestral element.", "tone_sandhi_and_pitch_modulation": "Two consecutive falling 4th tones: lù dì (51-51). Articulate both syllables with a firm, anchored downward cadence."}, "semantic_boundary_contrasts": {"core_nuance": "陆地 specifically contrasts the solid geological ground surface against the liquid ocean, sea, or airspace.", "contrasts": [{"id": "1", "compared_word": "陆地 vs. 大陆", "pinyin": "dàlù", "analysis": "陆地 contrasts with oceans or waterways (e.g. 告别陆地出海), whereas 大陆 denotes a vast geographical continent (如亚欧大陆) or mainland regions."}, {"id": "2", "compared_word": "陆地 vs. 地面", "pinyin": "dìmiàn", "analysis": "陆地 is the planetary-scale solid ground surface opposed to water, whereas 地面 refers locally to the immediate floor or outdoor ground beneath one's feet."}, {"id": "3", "compared_word": "陆地 vs. 土地", "pinyin": "tǔdì", "analysis": "陆地 focuses on terrestrial geography, whereas 土地 refers to arable farm fields, territorial sovereignty, or real estate soil."}]}, "traps_and_cognates": {"look_alikes": [{"character": "陆", "pinyin": "lù", "meaning_en": "land; continent", "distinction_note": "Has 阝 (mound) on the left and 击 on the right"}, {"character": "阵", "pinyin": "zhèn", "meaning_en": "battle array; burst", "distinction_note": "Has 阝 on the left and 车 on the right"}, {"character": "地", "pinyin": "dì", "meaning_en": "earth; land", "distinction_note": "Has 土 (soil) on the left and 也 on the right"}, {"character": "池", "pinyin": "chí", "meaning_en": "pool; pond", "distinction_note": "Has 氵 (water) on the left with 也"}], "etymological_cognates": [{"character": "大陆", "pinyin": "dà lù", "gloss_en": "continent; mainland"}, {"character": "着陆", "pinyin": "zhuó lù", "gloss_en": "land; touch down"}, {"character": "地面", "pinyin": "dì miàn", "gloss_en": "ground surface; terrain"}, {"character": "地球", "pinyin": "dì qiú", "gloss_en": "planet Earth; the globe"}]}, "id": "26", "hanzi": "陆地", "pinyin": "lù dì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the solid part of the surface of the earth not covered by water", "definition_es": "parte sólida de la superficie terrestre no cubierta por agua", "example_phrase": "登上陆地 (step onto land)"}], "example_sentences": [{"id": "#1", "hanzi": "在浩瀚的大洋上航行了整整一个月后，当第一座海岛的陆地轮廓出现在眼前时，全船欢呼雀跃。", "pinyin": "Zài hàohàn de dàyáng shàng hángxíng le zhěngzhěng yí gè yuè hòu, dāng dì-yī zuò hǎidǎo de lùdì lúnkuò chūxiàn zài yǎnqián shí, quán chuán huānhū quèyuè.", "en": "After navigating boundless oceans for an entire month, when the shoreline outline of the first island surfaced, the crew cheered ecstatically.", "es": "Tras navegar por el inmenso océano durante un mes entero, cuando la silueta de tierra firme emergió ante sus ojos, la tripulación estalló en vítores."}, {"id": "#2", "hanzi": "地质学家运用深部地壳钻探技术，系统研究了远古地质时期大陆板块运动与陆地形成的演化历程。", "pinyin": "Dìzhìxuéjiā yùnyòng shēnbù dìqiào zuāntàn jìshù, xìtǒng yánjiū le yuǎngǔ dìzhì shíqī dàlù bǎnkuài yùndòng yǔ lùdì xíngchéng de yǎnhuà lìchéng.", "en": "Utilizing deep crustal drilling, geologists systematically studied the evolution of tectonic plate motions and landmass formation across deep time.", "es": "Mediante perforaciones de la corteza profunda, los geólogos estudiaron la tectónica de placas prehistórica y la formación de tierra firme."}], "collocations": [{"hanzi": "登上陆地", "en": "step onto land; disembark"}, {"hanzi": "陆地生物", "en": "terrestrial organisms / land creatures"}, {"hanzi": "返回陆地", "en": "return to dry land"}, {"hanzi": "辽阔的陆地", "en": "vast landmass"}, {"hanzi": "离开陆地", "en": "depart from land"}, {"hanzi": "陆地交通", "en": "land transportation"}], "idioms": [{"hanzi": "脚踏实地", "pinyin": "jiǎo tà shí dì", "meaning_en": "stand on solid ground; down-to-earth and earnest"}, {"hanzi": "陆海潘江", "pinyin": "lù hǎi pān jiāng", "meaning_en": "talents as deep as Lu's sea and Pan's river; overflowing literary brilliance"}, {"hanzi": "推舟于陆", "pinyin": "tuī zhōu yú lù", "meaning_en": "push a boat on dry land; futile effort going against nature"}, {"hanzi": "地大物博", "pinyin": "dì dà wù bó", "meaning_en": "vast territory with abundant natural resources"}], "character_decomposition": [{"character": "陆", "pinyin": "lù", "meaning_en": "land; continent; plateau", "meaning_es": "tierra firme; continente", "radical": "阝", "radical_meaning_en": "mound / hill", "meaning_component": "阝 (lofty earthen terraces or embankments)", "sound_component": "击 / 坴 (lù phonetic / clay soil piled high)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: earthen terraces (阝) towering high above waters, denoting solid dry land.", "visual_mnemonic_story_en": "Elevated terraced earthen mounds (阝) rising high and dry above crashing coastal waters (陆).", "visual_mnemonic_story_es": "Terrazas y montículos de tierra firme (阝) que se elevan secos por encima del mar embravecido (陆).", "tone_mnemonic_anchor": "51", "cangjie": "NLJTC", "traditional": "陸"}, {"character": "地", "pinyin": "dì", "meaning_en": "earth; ground; soil", "meaning_es": "tierra; suelo; suelo firme", "radical": "土", "radical_meaning_en": "earth / soil", "meaning_component": "土 (fertile soil supporting vegetation)", "sound_component": "也 (yě phonetic / vessel or winding terrain)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: nourishing soil (土) stretching across undulating terrain (也) to support all life.", "visual_mnemonic_story_en": "Rich dark soil (土) spreading wide across the winding valleys (也) to support trees and homes.", "visual_mnemonic_story_es": "Suelo fértil (土) que se extiende por los valles ondulados (也) sosteniendo campos y hogares.", "tone_mnemonic_anchor": "51", "cangjie": "GPD", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "只有在无边的大洋中航行过数月的人，才能深切体会到陆地的可贵。当双脚重新踏上坚实芬芳的泥土，听着林间小鸟清脆的欢歌，那种重新与大地相连的踏实感，是任何浮华辞藻都无法描摹的幸福。", "pinyin": "Zhǐyǒu zài wúbiān de dàyáng zhōng hángxíng guò shù yuè de rén, cáinéng shēnqiè tǐhuì dào lùdì de kěguì. Dāng shuāngjiǎo chóngxīn tà shàng jiānshí fēnfāng de nítǔ, tīng zhe línjiān xiǎoniǎo qīngcuì de huāngē, nà zhǒng chóngxīn yǔ dàdì xiānglián de tàshígǎn, shì rènhé fúhuá cízǎo dōu wúfǎ miáomó de xìngfú.", "en": "Only those who have sailed boundless seas for months grasp land's precious worth. Stepping again upon firm soil, listening to birdsong, that rooted grounding delivers happiness beyond words.", "es": "Solo quien navega meses en altamar comprende el valor inmenso de la tierra firme. Volver a pisar suelo sólido y aromático entre trinos bosquiseños regala un sosiego que ninguna palabra alcanza a retratar."}, {"id": "#2", "hanzi": "全球气候变暖引发的海平面上升，对低洼岛国及沿海平原的陆地生态系统构成了日益紧迫的生存威胁。通过构筑生态海堤防线、推进红树林湿地修复，不仅能有效抵御潮汐风暴侵蚀，更为维护沿海陆地国土安全与生物多样性筑牢了绿色生态屏障。", "pinyin": "Quánqiú qìhòu biànnuǎn yǐnfā de hǎipíngmiàn shàngshēng, duì dīwā dǎoguó jí yánhǎi píngyuán de lùdì shēngtài xìtǒng gòuchéng le rìyì jǐnpò de shēngcún wēixié. Tōngguò gòuzhù shēngtài hǎidī fángxiàn, tuījìn hóngshùlín shīdì xiūfù, bùjǐn néng yǒuxiào dǐyù cháoxī fēngbào qīnshí, gèng wèi wéihù yánhǎi lùdì guótǔ ānquán yǔ shēngwù duōyàngxìng zhùláo le lǜsè shēngtài píngzhàng.", "en": "Rising sea levels from climate change pose pressing threats to low-lying islands and terrestrial coastal ecosystems. Constructing living seawalls and restoring mangrove wetlands repels tidal storm surges while shielding territorial land and coastal biodiversity.", "es": "La subida del nivel del mar por el cambio climático amenaza los ecosistemas de tierra firme en islas y llanuras costeras. Construir diques vivos y reforestar manglares frena marejadas y blinda la seguridad territorial de la costa."}]}, {"meanings_summary": {"en": "each; respective; each by oneself; individually", "es": "cada uno; respectivamente; por su cuenta; por separado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When distinct individuals (各) act on their own behalf (自), everyone attends to their respective duties (各自).", "composite_memory_hook_es": "Cuando cada individuo (各) responde por sí mismo (自), cada uno atiende a sus respectivos asuntos (各自).", "cultural_and_cognitive_roots": "Chinese culture balances collective harmony with individual distinctness ('和而不同'). '各自' recognizes that within any team or family, each person carries distinct autonomy and personal agency.", "tone_sandhi_and_pitch_modulation": "Two consecutive falling 4th tones: gè zì (51-51). Articulate both syllables with balanced, assertive descending pitches."}, "semantic_boundary_contrasts": {"core_nuance": "各自 emphasizes individual autonomy and separate execution of actions by multiple parties.", "contrasts": [{"id": "1", "compared_word": "各自 vs. 大家", "pinyin": "dàjiā", "analysis": "各自 stresses individual separation where members do distinct things on their own (各自回屋), whereas 大家 stresses collective unity where everyone acts together (大家一起来)."}, {"id": "2", "compared_word": "各自 vs. 分别", "pinyin": "fēnbié", "analysis": "各自 is a pronoun modifying actors' separate domains (各自的责任), while 分别 is an adverb describing departure or sequential differentiation (分别出发)."}, {"id": "3", "compared_word": "各自 vs. 互相", "pinyin": "hùxiāng", "analysis": "各自 focuses on inward separate focus, whereas 互相 focuses on reciprocal interaction directed toward one another."}]}, "traps_and_cognates": {"look_alikes": [{"character": "各", "pinyin": "gè", "meaning_en": "each; every", "distinction_note": "Has 夂 on top and 口 (mouth) at the bottom"}, {"character": "名", "pinyin": "míng", "meaning_en": "name", "distinction_note": "Has 夕 on top and 口 at the bottom"}, {"character": "自", "pinyin": "zì", "meaning_en": "self; from", "distinction_note": "Six strokes with two horizontal strokes inside"}, {"character": "白", "pinyin": "bái", "meaning_en": "white", "distinction_note": "Five strokes with one horizontal stroke inside"}], "etymological_cognates": [{"character": "各位", "pinyin": "gè wèi", "gloss_en": "everybody; ladies and gentlemen"}, {"character": "各个", "pinyin": "gè gè", "gloss_en": "each and every; individually"}, {"character": "自己", "pinyin": "zì jǐ", "gloss_en": "oneself; self"}, {"character": "自觉", "pinyin": "zì jué", "gloss_en": "conscious; voluntary; self-aware"}]}, "id": "27", "hanzi": "各自", "pinyin": "gè zì", "level": "HSK 5", "part_of_speech": "Pronoun", "senses": [{"sense_number": "1", "part_of_speech": "Pronoun", "register": "Standard", "definition_en": "each individual person or entity considered separately and independently", "definition_es": "cada uno por su parte; cada cual independientemente", "example_phrase": "各自回家 (each returns to their respective homes)"}], "example_sentences": [{"id": "#1", "hanzi": "暴风雨来临前，甲板上的水手们迅速奔赴各自的岗位，紧张有序地执行收帆与加固任务。", "pinyin": "Bàofēngyǔ láilín qián, jiǎbǎn shàng de shuǐshǒumen xùnsù bēnfù gèzì de gǎngwèi, jǐnzhāng yǒuxù de zhíxíng shōufān yǔ jiāgù rènwu.", "en": "Before the squall hit, sailors on deck rushed to their respective posts, calmly furling sails and securing lines.", "es": "Antes del temporal, los marineros corrieron a sus respectivos puestos para arriar velas y afianzar amarras con presteza."}, {"id": "#2", "hanzi": "毕业多年后，昔日的同窗好友奔赴全国各地，在各自的专业领域里默默耕耘、施展才华。", "pinyin": "Bìyè duō nián hòu, xīrì de tóngchuāng hǎoyǒu bēnfù quánguó gèdì, zài gèzì de zhuānyè lǐngyù lǐ mòmò gēngyún, shīzhǎn cáihuá.", "en": "Years after graduation, former classmates dispersed across the country, quietly laboring and displaying talents in their respective professional fields.", "es": "Años tras graduarse, los antiguos compañeros se dispersaron por todo el país para labrar su camino y desplegar su talento en sus respectivos campos."}], "collocations": [{"hanzi": "各自负责", "en": "each take responsibility for their own part"}, {"hanzi": "奔赴各自岗位", "en": "rush to respective posts"}, {"hanzi": "各自回家", "en": "each return to one's own home"}, {"hanzi": "表达各自观点", "en": "express respective viewpoints"}, {"hanzi": "各自独立", "en": "each independent"}, {"hanzi": "回到各自生活", "en": "return to respective lives"}], "idioms": [{"hanzi": "各奔前程", "pinyin": "gè bèn qián chéng", "meaning_en": "each goes their own way; each pursues their own future"}, {"hanzi": "各自为政", "pinyin": "gè zì wéi zhèng", "meaning_en": "each administers affairs in their own way; lack of coordination"}, {"hanzi": "各抒己见", "pinyin": "gè shū jǐ jiàn", "meaning_en": "each airs their own views; express personal opinions freely"}, {"hanzi": "各有千秋", "pinyin": "gè yǒu qiān qiū", "meaning_en": "each has its own merits; each has something to recommend it"}], "character_decomposition": [{"character": "各", "pinyin": "gè", "meaning_en": "each; every; different", "meaning_es": "cada; cada cual; diverso", "radical": "口", "radical_meaning_en": "mouth / speech", "meaning_component": "夂 (zhǐ / feet walking in opposite directions)", "sound_component": "口 (mouth / speaking different thoughts)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Ideogrammic compound: footsteps departing in different directions (夂) with each mouth uttering separate thoughts (口).", "visual_mnemonic_story_en": "Footsteps turning in varied directions (夂) as every person's mouth (口) speaks their own distinct opinion.", "visual_mnemonic_story_es": "Pasos que parten en direcciones divergentes (夂) mientras cada boca (口) expresa su propio parecer.", "tone_mnemonic_anchor": "51", "cangjie": "HER", "traditional": ""}, {"character": "自", "pinyin": "zì", "meaning_en": "self; oneself; from", "meaning_es": "uno mismo; propio; desde", "radical": "自", "radical_meaning_en": "nose / self", "meaning_component": "自 (pictograph of human nose pointing to oneself)", "sound_component": "", "stroke_count": "6", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a human nose, which Chinese speakers naturally point to when referring to oneself ('自').", "visual_mnemonic_story_en": "An index finger pointing directly at one's own nose (自) to indicate \"myself\".", "visual_mnemonic_story_es": "Un dedo índice que señala la propia nariz (自) para decir con naturalidad: \"yo mismo\".", "tone_mnemonic_anchor": "51", "cangjie": "HAU", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "聚会结束时，朋友们挥手道别，重新回到各自的生活轨道中。虽然大家为了生计奔波在不同的城市，但那些并肩奋斗的岁月所结下的情谊，宛如暗夜里闪烁的星辰，在各自的天空下默默闪烁、互相照亮。", "pinyin": "Jùhuì jiéshù shí, péngyoumen huīshǒu dàobié, chóngxīn huí dào gèzì de shēnghuó guǐdào zhōng. Suīrán dàjiā wèile shēngjì bēnbō zài bùtóng de chéngshì, dàn nàxiē bìngjiān fèndòu de suìyuè suǒ jiéxià de qíngyì, wǎnrú ànyè lǐ shǎnshuò de xīngchén, zài gèzì de tiānkōng xià mòmò shǎnshuò, hùxiāng zhàoliàng.", "en": "As the gathering ended, friends waved goodbye, returning to their respective life orbits. Though chasing livelihoods across different cities, bonds forged through shared struggle resemble distant stars, quietly illuminating each sky.", "es": "Al concluir la reunión, los amigos se despidieron para retomar sus respectivas vidas. Aunque el trabajo los disperse por ciudades distintas, el cariño forjado en fatigas compartidas titila como estrellas hermanas en sus firmamentos."}, {"id": "#2", "hanzi": "跨国科研合作项目圆满结题后，来自五大洲的研究机构基于各自的实验数据与理论模型，分别发表了专题学术论文。这种既保持独立思辨又开展深度资源共享的协作范式，有力推动了全球尖端物理学研究的协同创新与突破。", "pinyin": "Kuàguó kēyán hézuò xiàngmù yuánmǎn jiétí hòu, láizì wǔdàzhōu de yánjiū jīgòu jīyú gèzì de shíyàn shùjù yǔ lǐlùn móxíng, fēnbié fābiǎo le zhuāntí xuéshù lùnwén. Zhè zhǒng jì bǎochí dúlì sībiàn yòu zhǎnkāi shēndù zīyuán gòngxiǎng de xiézuò fànshì, yǒulì tuīdòng le quánqiú jiānduān wùlǐxué yánjiū de xiétóng chuàngxīn yǔ tūpò.", "en": "Following the completion of the multinational physics project, laboratories across five continents published treatises grounded in their respective data models. This paradigm combining autonomy with resource-sharing accelerates global physics breakthroughs.", "es": "Concluido el proyecto científico multinacional, laboratorios de cinco continentes publicaron artículos con sus respectivos modelos empíricos. Este método, que combina criterio propio y datos compartidos, dinamiza la física de vanguardia mundial."}]}, {"meanings_summary": {"en": "to catch fire; to ignite; to be on fire; to burn", "es": "incendiarse; prender fuego; arder; coger fuego"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When combustible materials come into direct contact (着) with a spark, they immediately catch fire (着火).", "composite_memory_hook_es": "Cuando una chispa entra en contacto (着) con material combustible, prende fuego al instante (着火).", "cultural_and_cognitive_roots": "In maritime culture, fire on a wooden vessel at sea was historically more feared than drowning, giving rise to strict taboos and fire-watch disciplines aboard traditional junks.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone followed by a dipping 3rd tone: zháo huǒ (35-214). Notice that '着' here is read as 'zháo' (2nd tone), NOT 'zhe' or 'zhuó'."}, "semantic_boundary_contrasts": {"core_nuance": "着火 emphasizes the beginning or ongoing state of catching fire and burning uncontrollably.", "contrasts": [{"id": "1", "compared_word": "着火 vs. 点火", "pinyin": "diǎnhuǒ", "analysis": "着火 is typically accidental or natural catching fire (森林着火), whereas 点火 is the deliberate intentional act of igniting or lighting a flame (点火起飞, 点火做饭)."}, {"id": "2", "compared_word": "着火 vs. 燃烧", "pinyin": "ránshāo", "analysis": "着火 emphasizes the accident of catching fire, while 燃烧 is the formal scientific or descriptive term for combustion and burning (燃料燃烧)."}, {"id": "3", "compared_word": "着火 vs. 起火", "pinyin": "qǐhuǒ", "analysis": "着火 is the common spoken verb, whereas 起火 is more formal, commonly used in police and accident investigation reports (起火原因)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "着", "pinyin": "zháo / zhe", "meaning_en": "touch; aspect marker", "distinction_note": "Composed of 羊 top and 目 bottom"}, {"character": "看", "pinyin": "kàn", "meaning_en": "look; see", "distinction_note": "Composed of 手 (hand) shading 目 (eye)"}, {"character": "火", "pinyin": "huǒ", "meaning_en": "fire", "distinction_note": "Four strokes with two outer dots"}, {"character": "灭", "pinyin": "miè", "meaning_en": "extinguish; destroy", "distinction_note": "Has a horizontal stroke 一 smothering 火"}], "etymological_cognates": [{"character": "急着", "pinyin": "jí zháo", "gloss_en": "anxious; in a hurry"}, {"character": "着凉", "pinyin": "zháo liáng", "gloss_en": "catch a cold"}, {"character": "火焰", "pinyin": "huǒ yàn", "gloss_en": "flame; blaze"}, {"character": "火灾", "pinyin": "huǒ zāi", "gloss_en": "fire disaster; conflagration"}]}, "id": "28", "hanzi": "着火", "pinyin": "zháo huǒ", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to catch fire or begin burning (of buildings, ships, forests, materials)", "definition_es": "comenzar a arder; prender fuego; incendiarse", "example_phrase": "仓库着火了 (the warehouse caught fire)"}], "example_sentences": [{"id": "#1", "hanzi": "航海过程中最可怕的隐患之一是电气线路短路导致船舱着火，全船必须随时备好灭火器。", "pinyin": "Hánghǎi guòchéng zhōng zuì kěpà de yǐnhuàn zhīyī shì diànqì xiànlù duǎnlù dǎozhì chuáncāng zháohuǒ, quán chuán bìxū suíshí bèi hǎo mièhuǒqì.", "en": "One of the most terrifying hazards at sea is an electrical short causing cabins to catch fire; extinguishers must stand ready at all times.", "es": "Uno de los mayores peligros en la navegación es que un cortocircuito incendie la cabina; a bordo es obligatorio tener extintores a punto."}, {"id": "#2", "hanzi": "老旧居民楼因电动车违规充电不幸着火，消防官兵在浓烟滚滚中迅速架设云梯疏散受困群众。", "pinyin": "Lǎojiù jūmínlóu yīn diàndòngchē wéiguī chōngdiàn bùxìng zháohuǒ, xiāofáng guānbīng zài nóngyān gǔngǔn zhōng xùnsù jiàshè yúntī shūsàn shòukùn qúnzhòng.", "en": "An old apartment block caught fire due to illicit e-bike charging, prompting firefighters to raise ladders through dense smoke to evacuate residents.", "es": "Un viejo bloque de viviendas se incendió por la recarga indebida de una moto; los bomberos desplegaron escalas entre el humo para evacuar a los vecinos."}], "collocations": [{"hanzi": "着火点", "en": "ignition point; fire spot"}, {"hanzi": "不慎着火", "en": "accidentally catch fire"}, {"hanzi": "防止着火", "en": "prevent catching fire"}, {"hanzi": "着火报警", "en": "fire alarm report"}, {"hanzi": "船舱着火", "en": "cabin catches fire"}, {"hanzi": "森林着火", "en": "forest catches fire"}], "idioms": [{"hanzi": "后院着火", "pinyin": "hòu yuàn zháo huǒ", "meaning_en": "fire in one's backyard; trouble or rebellion arising from one's own camp"}, {"hanzi": "引火烧身", "pinyin": "yǐn huǒ shāo shēn", "meaning_en": "draw fire against oneself; court disaster"}, {"hanzi": "救火扬沸", "pinyin": "jiù huǒ yáng fèi", "meaning_en": "stir boiling water to stop it; adopt counterproductive methods to solve problems"}, {"hanzi": "火上浇油", "pinyin": "huǒ shàng jiāo yóu", "meaning_en": "pour oil onto the fire; aggravate an already inflammatory situation"}], "character_decomposition": [{"character": "着", "pinyin": "zháo", "meaning_en": "touch; catch; ignite", "meaning_es": "tocar; encender; arder", "radical": "目", "radical_meaning_en": "eye", "meaning_component": "羊 (yáng phonetic / horns or wool)", "sound_component": "目 (eye watching closely or coming in contact)", "stroke_count": "11", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound: woolly horns (羊) coming in direct physical contact (目) with heat to ignite.", "visual_mnemonic_story_en": "Dry sheep fleece (羊) brushing against an open flame right before your eyes (目), catching fire instantly.", "visual_mnemonic_story_es": "Lana seca (羊) que roza una llama ante tus propios ojos (目), prendiendo fuego en un instante.", "tone_mnemonic_anchor": "35", "cangjie": "TQBU", "traditional": "著"}, {"character": "火", "pinyin": "huǒ", "meaning_en": "fire; flame; anger", "meaning_es": "fuego; llama; ira", "radical": "火", "radical_meaning_en": "fire / flame", "meaning_component": "火 (pictograph of rising leaping flames)", "sound_component": "", "stroke_count": "4", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of flickering, crackling flames leaping upwards from burning firewood.", "visual_mnemonic_story_en": "Twin sparks flying outward from a central tongue of blazing fire (火).", "visual_mnemonic_story_es": "Dos chispas que saltan a ambos lados de una lengua de fuego ardiente (火).", "tone_mnemonic_anchor": "214", "cangjie": "F", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "茫茫夜海中，水手们最警惕的便是船舱着火。木质与玻璃钢结构的船体一旦遭遇明火，海风将迅速助长火势。每一次出海前对电路线路的仔细排查，都是对全船航行安全最庄严的誓言。", "pinyin": "Mángmáng yèhǎi zhōng, shuǐshǒumen zuì jǐngtì de biàn shì chuáncāng zháohuǒ. Mùzhì yǔ bōligāng jiégòu de chuántǐ yídàn zāoyù mínghuǒ, hǎifēng jiāng xùnsù zhùzhǎng huǒshì. Měi yí cì chūhǎi qián duì diànlù xiànlù de zǐxì páichá, dōu shì duì quán chuán hángxíng ānquán zuì zhuāngyán de shìyán.", "en": "In the nocturnal sea, sailors dread cabin fires above all. Should fiberglass or wood contact an open flame, ocean winds fan blazes furiously. Inspecting electrical circuits before casting off forms an inviolable oath of safe passage.", "es": "En la noche marina, los tripulantes temen el fuego en la cabina más que nada. Si el casco de madera o fibra roza una llama, el viento aviva el incendio con furia. Revisar los circuitos antes de zarpar es un juramento de seguridad sagrado."}, {"id": "#2", "hanzi": "城市高层建筑消防安全专项整治行动重点聚焦外墙保温材料阻燃性能与消防通道畅通情况。数据分析显示，私搭乱接电线是诱发建筑着火的主要诱因。通过推广智能烟感联网报警装置，城市应急管理部门能够实现火情秒级预警与初期扑救联动。", "pinyin": "Chéngshì gāocéng jiànzhù xiāofáng ānquán zhuānxiàng zhěngzhì xíngdòng zhòngdiǎn jùjiāo wàiqiáng bǎowēn cáiliào zǔrán xìngnéng yǔ xiāofáng tōngdào chàngtōng qíngkuàng. Shùjù fēnxī xiǎnshì, sīdāluànjiē diànxiàn shì yòufā jiànzhù zháohuǒ de zhǔyào yòuyīn. Tōngguò tuīguǎng zhìnéng yāngǎn liánwǎng bàojǐng zhuāngzhì, chéngshì yìngjí guǎnlǐ bùmén nénggòu shíxiàn huǒqíng miǎojí yùjǐng yǔ chūqī pūjiù liándòng.", "en": "Urban high-rise fire safety campaigns prioritize exterior insulation flame retardancy and unobstructed emergency lanes. Illegal wiring sparks most structural fires. Implementing networked smoke alarms allows municipal teams to detect blazes and mount rapid suppression.", "es": "La prevención contra incendios en rascacielos se centra en aislamientos ignífugos y vías de evacuación despejadas. El cableado clandestino es la principal causa de fuegos. Los detectores inteligentes permiten alertar en segundos y sofocar conatos de inmediato."}]}, {"meanings_summary": {"en": "moment; juncture of time; constantly; always; at every moment", "es": "momento; instante decisivo; constantemente; en todo momento; a todas horas"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When the sun's progress (时) is carved into sundial graduations (刻), every passing second defines a precious moment (时刻).", "composite_memory_hook_es": "Cuando la marcha del sol (时) queda grabada en el reloj (刻), cada instante que pasa conforma un precioso momento (时刻).", "cultural_and_cognitive_roots": "Ancient sundials marked '刻' (roughly 14.4 minutes, modern 15 minutes) by knife cuts on bronze dials. '时刻' spans both precise historical turning points and constant psychological mindfulness.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone followed by a falling 4th tone: shí kè (35-51). Articulate 'shí' with smooth upward pitch before cutting 'kè' downward crisply."}, "semantic_boundary_contrasts": {"core_nuance": "时刻 refers to a critical pinpoint of time, or functions adverbially to denote perpetual alertness.", "contrasts": [{"id": "1", "compared_word": "时刻 vs. 时间", "pinyin": "shíjiān", "analysis": "时刻 emphasizes a specific critical point, instant, or psychological juncture (关键时刻), whereas 时间 refers to the broad, measurable duration or continuous passage of time (需要时间)."}, {"id": "2", "compared_word": "时刻 vs. 时候", "pinyin": "shíhou", "analysis": "时刻 is formal and literary, often designating momentous occasions, while 时候 is versatile everyday oral Chinese for general timing (吃饭的时候)."}, {"id": "3", "compared_word": "时刻 vs. 瞬间", "pinyin": "shùnjiān", "analysis": "时刻 highlights the historical or emotional significance of a moment, whereas 瞬间 emphasizes the fleeting optical brevity of an eye blink."}]}, "traps_and_cognates": {"look_alikes": [{"character": "时", "pinyin": "shí", "meaning_en": "time; hour", "distinction_note": "Has 日 (sun) on the left and 寸 on the right"}, {"character": "村", "pinyin": "cūn", "meaning_en": "village", "distinction_note": "Has 木 (wood) on the left with 寸"}, {"character": "刻", "pinyin": "kè", "meaning_en": "carve; moment", "distinction_note": "Has 亥 on the left and 刂 (knife) on the right"}, {"character": "赅", "pinyin": "gāi", "meaning_en": "all-inclusive; broad", "distinction_note": "Has 贝 (shell) on the left with 亥"}], "etymological_cognates": [{"character": "时间", "pinyin": "shí jiān", "gloss_en": "time; period"}, {"character": "时代", "pinyin": "shí dài", "gloss_en": "era; epoch; age"}, {"character": "刻度", "pinyin": "kè dù", "gloss_en": "scale graduation; calibration mark"}, {"character": "刻画", "pinyin": "kè huà", "gloss_en": "portray; depict; carve"}]}, "id": "29", "hanzi": "时刻", "pinyin": "shí kè", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a specific point in time, crucial moment, or juncture", "definition_es": "momento específico, coyuntura crucial o instante decisivo", "example_phrase": "关键时刻 (critical moment / crucial juncture)"}, {"sense_number": "2", "part_of_speech": "Adverb", "register": "Formal", "definition_en": "constantly, always, or at all times without ceasing", "definition_es": "constantemente; en todo momento; sin cesar", "example_phrase": "时刻准备着 (always prepared)"}], "example_sentences": [{"id": "#1", "hanzi": "在狂风巨浪将帆船掀起数米高的危急时刻，全家人紧握双手，凭借坚强的信念战胜了恐惧。", "pinyin": "Zài kuángfēng jùlàng jiāng fānchuán xiānqǐ shù mǐ gāo de wēijí shíkè, quán jiārén jǐnwò shuāngshǒu, píngjiè jiānqiáng de xìnniàn zhànshèng le kǒngjù.", "en": "At the perilous moment when monstrous swells tossed the yacht meters into the air, the family clutched hands and conquered terror through faith.", "es": "En el instante crítico en que las olas gigantescas levantaban el velero varios metros, la familia se estrechó las manos y venció el miedo con fe."}, {"id": "#2", "hanzi": "作为一名医护工作者，他时刻将患者的生命健康放在第一位，始终坚守在临床急救最前线。", "pinyin": "Zuòwéi yì míng yīhù gōngzuòzhě, tā shíkè jiāng huànzhě de shēngmìng jiànkāng fàng zài dì-yī wèi, shǐzhōng jiānshǒu zài línchuáng jíjiù zuì qiánxiàn.", "en": "As a healthcare professional, he constantly puts patients' lives first, remaining steadfast on the clinical emergency front lines.", "es": "Como sanitario, antepone en todo momento la salud del paciente y permanece firme en la primera línea de las urgencias hospitalarias."}], "collocations": [{"hanzi": "关键时刻", "en": "crucial moment; turning point"}, {"hanzi": "历史时刻", "en": "historical moment"}, {"hanzi": "危急时刻", "en": "critical juncture; perilous moment"}, {"hanzi": "时刻准备着", "en": "always be prepared"}, {"hanzi": "难忘的时刻", "en": "unforgettable moment"}, {"hanzi": "美好时刻", "en": "wonderful moment"}], "idioms": [{"hanzi": "分分秒秒", "pinyin": "fēn fēn miǎo miǎo", "meaning_en": "every minute and every second; every single moment"}, {"hanzi": "争分夺秒", "pinyin": "zhēng fēn duó miǎo", "meaning_en": "race against time; seize every second"}, {"hanzi": "刻舟求剑", "pinyin": "kè zhōu qiú jiàn", "meaning_en": "notch a boat to find a dropped sword; rigid and foolishly obstinate"}, {"hanzi": "时不再来", "pinyin": "shí bù zài lái", "meaning_en": "time does not return; opportunity knocks but once"}], "character_decomposition": [{"character": "时", "pinyin": "shí", "meaning_en": "time; season; hour", "meaning_es": "tiempo; hora; estación", "radical": "日", "radical_meaning_en": "sun / day", "meaning_component": "日 (sun tracking daylight hours)", "sound_component": "寸 (cùn phonetic / hand rule or unit of measure)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogrammic compound: tracking the sun's trajectory (日) in precise measured units (寸) to determine time.", "visual_mnemonic_story_en": "Measuring the golden sun's shadow (日) with an inch-ruler (寸) to mark the precise passing hour.", "visual_mnemonic_story_es": "Medir la sombra del sol (日) con una regla de pulgadas (寸) para computar el paso de las horas.", "tone_mnemonic_anchor": "35", "cangjie": "ADI", "traditional": "時"}, {"character": "刻", "pinyin": "kè", "meaning_en": "carve; engrave; quarter-hour", "meaning_es": "tallar; grabar; cuarto de hora", "radical": "刂", "radical_meaning_en": "knife / cut", "meaning_component": "刂 (sharp blade incising marks)", "sound_component": "亥 (hài phonetic / cyclical branch or pig)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: a sharp carving knife (刂) notching graduations on ancient sundials to record quarter-hours.", "visual_mnemonic_story_en": "A sharp metal knife (刂) carving deep notches onto a sun clock dial to record fleeting moments.", "visual_mnemonic_story_es": "Un cuchillo afilado (刂) que graba muescas en el cuadrante solar para fijar el paso de los instantes.", "tone_mnemonic_anchor": "51", "cangjie": "YOSH", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "每一个人的生命中，都存在着几个决定人生走向的关键时刻。面对转折点时的每一次犹豫与抉择，都在悄悄重构未来的风景。唯有保持清醒与定力，在重要时刻勇敢迈出脚步，才能在人生的画卷上留下无悔的笔墨。", "pinyin": "Měi yí gè rén de shēngmìng zhōng, dōu cúnzài zhe jǐ gè juédìng rénshēng zǒuxiàng de guānjiàn shíkè. Miànduì zhuǎnzhédiǎn shí de měi yí cì yóuyù yǔ juézé, dōu zài qiāoqiāo chónggòu wèilái de fēngjǐng. Wéiyǒu bǎochí qīngxǐng yǔ dìnglì, zài zhòngyào shíkè yǒnggǎn màichū jiǎobù, cáinéng zài rénshēng de huàjuàn shàng liúxià wúhuǐ de bǐmò.", "en": "In every life there exist critical moments that pivot one's trajectory. Every hesitation and resolution at crossways reshapes future horizons. Staying lucid and taking brave strides at deciding junctures leaves indelible strokes on life's canvas.", "es": "En la vida de cualquiera surgen momentos decisivos que reorientan el rumbo. Cada duda y cada resolución ante las encrucijadas reconfiguran el mañana. Solo con lucidez y paso firme en el instante crucial se pinta un destino sin arrepentimientos."}, {"id": "#2", "hanzi": "载人航天工程进入飞船返回对接的关键时刻，地面测控中心数十个监控大屏实时刷新遥测参数。科研团队时刻保持高度警觉，精准捕捉姿态控制回路中的微秒级数据突变，确保返回舱以最佳角度切入大气层，圆满完成任务。", "pinyin": "Zàirén hángtiān gōngchéng jìnrù fēichuán fǎnhuí duìjiē de guānjiàn shíkè, dìmiàn cèkòng zhōngxīn shùshí gè jiānkòng dàpíng shíshí shuāxīn yáocè cānshù. Kēyán tuánduì shíkè bǎochí gāodù jǐngjué, jīngzhǔn bǔzhuō zītài kòngzhì huílù zhōng de wēimiǎojí shùjù tūbiàn, quèbǎo fǎnhuícāng yǐ zuìjiā jiǎodù qiērù dàqìcéng, yuánmǎn wánchéng rènwu.", "en": "As the manned space capsule approached reentry, mission control screens flashed telemetry in real time. Engineers remained perpetually vigilant, monitoring microsecond attitude control loops to guarantee the module pierced the atmosphere at the ideal vector.", "es": "Al enfilar la nave tripulada el reingreso crítico, las pantallas de control refrescaron la telemetría en tiempo real. Los ingenieros permanecieron en alerta máxima para registrar cualquier microvariación y guiar la cápsula hacia la atmósfera."}]}, {"meanings_summary": {"en": "human life; life journey; existence; one's lifetime", "es": "vida humana; vida; periplo vital; existencia"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A human being (人) bursting forth with vital growth and experience (生) embodies the magnificent journey of life (人生).", "composite_memory_hook_es": "Un ser humano (人) que brota y florece con vitalidad (生) encarna el maravilloso viaje de la vida (人生).", "cultural_and_cognitive_roots": "Traditional Chinese philosophy views '人生' as an ethical journey of continuous self-cultivation ('修身齐家治国平天下'). Life is conceived not merely as biological duration, but as the active realization of human dignity and purpose.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone followed by a high level 1st tone: rén shēng (35-55). Ascend smoothly on 'rén' before articulating 'shēng' with high, clear resonance."}, "semantic_boundary_contrasts": {"core_nuance": "人生 highlights the experiential, philosophical, and moral journey of human beings throughout a lifetime.", "contrasts": [{"id": "1", "compared_word": "人生 vs. 生命", "pinyin": "shēngmìng", "analysis": "人生 focuses on the psychological, spiritual, and social journey across a lifetime (人生观, 人生经历), whereas 生命 refers to biological vitality, physical lifespan, or survival (拯救生命)."}, {"id": "2", "compared_word": "人生 vs. 生活", "pinyin": "shēnghuó", "analysis": "人生 is abstract, lofty, and philosophical, contemplating destiny and meaning, while 生活 concerns daily concrete activities (eating, cooking, chores, working)."}, {"id": "3", "compared_word": "人生 vs. 一生", "pinyin": "yìshēng", "analysis": "人生 contemplates the qualitative nature and wisdom of living, whereas 一生 focuses on the chronological timespan from birth to death (奉献了一生)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "人", "pinyin": "rén", "meaning_en": "human; person", "distinction_note": "Two strokes slanting outward"}, {"character": "入", "pinyin": "rù", "meaning_en": "enter", "distinction_note": "Left stroke shorter with right stroke dominating over top"}, {"character": "生", "pinyin": "shēng", "meaning_en": "birth; life", "distinction_note": "Five strokes with three horizontal lines"}, {"character": "牛", "pinyin": "niú", "meaning_en": "ox; cattle", "distinction_note": "Has vertical stroke cutting through the top horizontal"}], "etymological_cognates": [{"character": "生活", "pinyin": "shēng huó", "gloss_en": "daily life; live"}, {"character": "生命", "pinyin": "shēng mìng", "gloss_en": "biological life; vitality"}, {"character": "人们", "pinyin": "rén men", "gloss_en": "people; the public"}, {"character": "人类", "pinyin": "rén lèi", "gloss_en": "humanity; human race"}]}, "id": "30", "hanzi": "人生", "pinyin": "rén shēng", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the course, experience, and philosophical meaning of human living", "definition_es": "existencia humana; curso o trayectoria de la vida de una persona", "example_phrase": "人生道路 (the path of life)"}], "example_sentences": [{"id": "#1", "hanzi": "翟峰常说，人生有选择，一切皆来得及；只要心怀梦想并付诸行动，任何时候都不算太迟。", "pinyin": "Zhái Fēng cháng shuō, rénshēng yǒu xuǎnzé, yíqiè jiē láidejí; zhǐyào xīnhuái mèngxiǎng bìng fùzhū xíngdòng, rènhé shíhou dōu bú suàn tài chí.", "en": "Zhai Feng often said there are choices in life and it is never too late; as long as you hold dreams and act, no time is too late.", "es": "Zhai Feng solía decir que en la vida hay opciones y siempre se está a tiempo; basta abrigar un sueño y pasar a la acción para que nunca sea tarde."}, {"id": "#2", "hanzi": "许多哲学家通过对人生的深刻反思，探寻个体在漫长历史长河中确立自身价值与伦理责任的路径。", "pinyin": "Xǔduō zhéxuéjiā tōngguò duì rénshēng de shēnkè fǎnsī, tànxún gètǐ zài màncháng lìshǐ chánghé zhōng quèlì zìshēn jiàzhí yǔ lúnlǐ zérèn de lùjìng.", "en": "Through deep reflections on human life, philosophers explore paths for individuals to anchor personal worth and ethical duty within history.", "es": "Mediante hondas reflexiones sobre la vida humana, los filósofos indagan el modo en que el individuo forja su valor y su deber ético en la historia."}], "collocations": [{"hanzi": "人生道路", "en": "path of life; life's journey"}, {"hanzi": "人生感悟", "en": "life reflections; insights into life"}, {"hanzi": "精彩人生", "en": "wonderful life; splendid life"}, {"hanzi": "人生哲学", "en": "philosophy of life"}, {"hanzi": "人生目标", "en": "life goal; life objective"}, {"hanzi": "人生旅程", "en": "life's journey; voyage of life"}], "idioms": [{"hanzi": "人生如梦", "pinyin": "rén shēng rú mèng", "meaning_en": "human life is like a dream; transient nature of existence"}, {"hanzi": "人生苦短", "pinyin": "rén shēng kǔ duǎn", "meaning_en": "life is fleeting and short; life is ephemeral"}, {"hanzi": "百年人生", "pinyin": "bǎi nián rén shēng", "meaning_en": "a hundred years of human life; a human lifetime"}, {"hanzi": "人生何处不相逢", "pinyin": "rén shēng hé chù bù xiāng féng", "meaning_en": "where in life do friends not meet again; the world is small"}], "character_decomposition": [{"character": "人", "pinyin": "rén", "meaning_en": "person; human; people", "meaning_es": "persona; ser humano", "radical": "人", "radical_meaning_en": "human / person", "meaning_component": "人 (pictograph of a walking human being)", "sound_component": "", "stroke_count": "2", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a human being standing erect on two walking legs and leaning forward.", "visual_mnemonic_story_en": "Two steady legs striding forward (人) as an erect human steps bravely into the world.", "visual_mnemonic_story_es": "Dos piernas firmes que avanzan erguidas (人) representando al ser humano que camina por el mundo.", "tone_mnemonic_anchor": "35", "cangjie": "O", "traditional": ""}, {"character": "生", "pinyin": "shēng", "meaning_en": "give birth; live; grow", "meaning_es": "nacer; vivir; crecer", "radical": "生", "radical_meaning_en": "sprout / growth", "meaning_component": "生 (young sprout bursting out of soil)", "sound_component": "一 (ground level)", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a verdant young plant shoot (生) bursting up through soil (一) into life.", "visual_mnemonic_story_en": "A tender green seedling (生) pushing up through the fertile soil toward sunlight and vitality.", "visual_mnemonic_story_es": "Un tierno brote verde (生) que rompe la tierra hacia el sol, rebosante de vitalidad.", "tone_mnemonic_anchor": "55", "cangjie": "HMHM", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "很多人以为，人生是一场必须按部就班抵达终点的赛跑，其实人生更像是一片任由探索的广阔原野。沿途的迷茫、试错与驻足，都是生命不可或缺的注脚。敢于遵从内心做出选择，才能领略到属于自己的独特风景。", "pinyin": "Hěnduō rén yǐwéi, rénshēng shì yì chǎng bìxū ànbùjiùbān dǐdá zhōngdiǎn de sàipǎo, qíshí rénshēng gèng xiàng shì yí piàn rènyóu tànsuǒ de guǎngkuò yuányě. Yántú de mímáng, shìcuò yǔ zhùzú, dōu shì shēngmìng bùkěhuòquē de zhùjiǎo. Gǎnyú zūncóng nèixīn zuòchū xuǎnzé, cáinéng lǐnglüè dào shǔyú zìjǐ de dútè fēngjǐng.", "en": "Many imagine life as a rigid race to a fixed finish line; in truth, life resembles an open wilderness inviting exploration. Confusion, detours, and pauses along the path enrich the journey. Daring to choose from the heart unlocks one's unique vistas.", "es": "Muchos creen que la vida es una carrera encorsetada hacia la meta, cuando en verdad es un páramo fértil abierto a la exploración. Desvíos y dudas son notas vivas del camino. Quien se atreve a elegir con el alma contempla sus propios paisajes irrepetibles."}, {"id": "#2", "hanzi": "社会学与伦理学研究指出，现代人在追求物质丰裕的同时，愈发关注人生的精神归宿与价值实现。构建多维度的社会支持网络与终身成长平台，有助于引导年轻一代摆脱单一的成功学评价束缚，以更加开放包容的心态探索属于自己的多元人生路径。", "pinyin": "Shèhuìxué yǔ lúnlǐxué yánjiū zhǐchū, xiàndài rén zài zhuīqiú wùzhì fēngyù de tóngshí, yùfā guānzhù rénshēng de jīngshén guīsù yǔ jiàzhí shíxiàn. Gòujiàn duōwéidù de shèhuì zhīchí wǎngluò yǔ zhōngshēn chéngzhǎng píngtái, yǒuzhùyú yǐndǎo niánqīng yídài bǎituō dānyī de chénggōngxué píngjià shùfù, yǐ gèngjiā kāifàng bāoróng de xīntài tànsuǒ shǔyú zìjǐ de duōyuán rénshēng lùjìng.", "en": "Sociological and ethical studies note modern people prioritize spiritual fulfillment and personal values alongside material wealth. Multi-tiered social platforms help younger generations transcend narrow metrics of success, exploring multifaceted life journeys with an open mindset.", "es": "La sociología y la ética demuestran que el ser humano contemporáneo prioriza la plenitud interior junto al bienestar material. Forjar redes de crecimiento personal ayuda a los jóvenes a eludir el éxito plano y explorar caminos vitales diversos."}]}, {"meanings_summary": {"en": "worker; manual laborer; blue-collar worker; workman", "es": "obrero; trabajador; operario; peón"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A person (人) applying craft tools (工) to productive labor is an honorable worker (工人).", "composite_memory_hook_es": "Una persona (人) que maneja las herramientas del oficio (工) con esfuerzo es un digno trabajador u obrero (工人).", "cultural_and_cognitive_roots": "In modern Chinese history, the working class ('工人阶级') became the vanguard of industrialization and national modernization, celebrated for dignity, stamina, and craftsmanship spirit.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a rising 2nd tone: gōng rén (55-35). Hold 'gōng' sustained before elevating pitch clearly into 'rén'."}, "semantic_boundary_contrasts": {"core_nuance": "工人 specifically refers to blue-collar wage laborers employed in manufacturing, construction, transport, or physical trades.", "contrasts": [{"id": "1", "compared_word": "工人 vs. 员工", "pinyin": "yuángōng", "analysis": "工人 designates blue-collar manual or technical industrial workers, whereas 员工 is an umbrella corporate term for all staff (including white-collar managers, clerks, and technicians)."}, {"id": "2", "compared_word": "工人 vs. 农民", "pinyin": "nóngmín", "analysis": "工人 works in factories, mines, railways, or urban construction for a wage, while 农民 works in agriculture, tilling arable soil."}, {"id": "3", "compared_word": "工人 vs. 匠人", "pinyin": "jiàngrén", "analysis": "工人 emphasizes wage labor within an industrial collective, whereas 匠人 highlights traditional master craftsmanship, artistry, and individual mastery."}]}, "traps_and_cognates": {"look_alikes": [{"character": "工", "pinyin": "gōng", "meaning_en": "labor; work", "distinction_note": "Three strokes without vertical protrusion"}, {"character": "土", "pinyin": "tǔ", "meaning_en": "earth; soil", "distinction_note": "Has vertical stroke cutting through center"}, {"character": "士", "pinyin": "shì", "meaning_en": "scholar; soldier", "distinction_note": "Top horizontal stroke is longer than bottom"}, {"character": "人", "pinyin": "rén", "meaning_en": "human; person", "distinction_note": "Two simple slanting strokes"}], "etymological_cognates": [{"character": "工业", "pinyin": "gōng yè", "gloss_en": "industry; manufacturing"}, {"character": "工程", "pinyin": "gōng chéng", "gloss_en": "engineering; project"}, {"character": "人工", "pinyin": "rén gōng", "gloss_en": "artificial; manual labor"}, {"character": "人民", "pinyin": "rén mín", "gloss_en": "the people; citizens"}]}, "id": "31", "hanzi": "工人", "pinyin": "gōng rén", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a person engaged in physical, technical, or industrial manual labor", "definition_es": "persona que realiza un trabajo manual, técnico o industrial por un salario", "example_phrase": "建筑工人 (construction worker)"}], "example_sentences": [{"id": "#1", "hanzi": "辞职买船前，翟峰曾是一名普通的铁路工人，每天在铁轨与机车旁过着平淡而规律的生活。", "pinyin": "Cízhí mǎi chuán qián, Zhái Fēng céng shì yì míng pǔtōng de tiělù gōngrén, měitiān zài tiěguǐ yǔ jīchē páng guò zhe píngdàn ér guīlǜ de shēnghuó.", "en": "Before resigning to buy the yacht, Zhai Feng was an ordinary railway worker living a routine life beside rails and locomotives.", "es": "Antes de dejar su empleo para comprar el velero, Zhai Feng era un ferroviario común que llevaba una vida rutinaria junto a las vías."}, {"id": "#2", "hanzi": "造船厂的技术工人们凭借精湛的焊接工艺，顺利攻克了深海科考船高强度钢材拼接的技术难题。", "pinyin": "Zàochuánchǎng de jìshù gōngrénmen píngjiè jīngzhàn de hànjiē gōngyì, shùnlì gōngkè le shēnhǎi kěkǎochuán gāoqiángdù gāngcái pīnjiē de jìshù nándí.", "en": "Shipyard technicians relied on consummate welding skills to overcome the challenge of bonding high-strength steel for the research vessel.", "es": "Los operarios técnicos del astillero aplicaron soldaduras de precisión para unir el acero de alta resistencia del buque de investigación."}], "collocations": [{"hanzi": "铁路工人", "en": "railway worker"}, {"hanzi": "建筑工人", "en": "construction worker"}, {"hanzi": "技术工人", "en": "skilled technician / technical worker"}, {"hanzi": "工人阶级", "en": "working class"}, {"hanzi": "产业工人", "en": "industrial worker"}, {"hanzi": "普通工人", "en": "ordinary worker"}], "idioms": [{"hanzi": "巧夺天工", "pinyin": "qiǎo duó tiān gōng", "meaning_en": "superb craftsmanship excelling nature; wonderful workmanship"}, {"hanzi": "人尽其才", "pinyin": "rén jìn qí cái", "meaning_en": "everyone brings their talents into full play"}, {"hanzi": "任劳任怨", "pinyin": "rèn láo rèn yuàn", "meaning_en": "bear hardship and blame without complaint; work uncomplainingly"}, {"hanzi": "同心同德", "pinyin": "tóng xīn tóng dé", "meaning_en": "of one mind and one heart; united in purpose"}], "character_decomposition": [{"character": "工", "pinyin": "gōng", "meaning_en": "labor; work; craft", "meaning_es": "trabajo; obra; artesano", "radical": "工", "radical_meaning_en": "work / carpenter's square", "meaning_component": "工 (pictograph of a carpenter's square or mallet)", "sound_component": "", "stroke_count": "3", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a carpenter's framing square or stone-chisel tool, denoting craftsmanship and physical work.", "visual_mnemonic_story_en": "An ancient carpenter's square (工) used by craftsmen to measure stone and wood with precision.", "visual_mnemonic_story_es": "Una escuadra de carpintero (工) empleada por los artesanos para labrar madera y piedra con exactitud.", "tone_mnemonic_anchor": "55", "cangjie": "M", "traditional": ""}, {"character": "人", "pinyin": "rén", "meaning_en": "human; person; worker", "meaning_es": "persona; ser humano", "radical": "人", "radical_meaning_en": "person / human", "meaning_component": "人 (pictograph of a person standing)", "sound_component": "", "stroke_count": "2", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a human being standing erect on two walking legs.", "visual_mnemonic_story_en": "An upright person (人) dedicating hands and body to purposeful productive labor.", "visual_mnemonic_story_es": "Un ser humano erguido (人) que entrega su fuerza y destreza a la labor productiva diaria.", "tone_mnemonic_anchor": "35", "cangjie": "O", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "轰鸣的机车与纵横的铁轨，曾是一个铁路工人生活的全部世界。然而，制服与作息时间表可以规范日常的步伐，却锁不住一颗渴望星辰大海的灵魂。当平凡工人决定启航，他的世界便从钢轨延伸至无垠的大洋。", "pinyin": "Hōngmíng de jīchē yǔ zònghéng de tiěguǐ, céng shì yí gè tiělù gōngrén shēnghuó de quánbù shìjiè. Rán'ér, zhìfú yǔ zuòxī shíjiānbiǎo kěyǐ guīfàn rìcháng de bùfá, què suǒbúzhù yì kē kěwàng xīngchéndàhǎi de línghún. Dāng píngfán gōngrén juédìng qǐháng, tā de shìjiè biàn cóng gāngguǐ yánshēn zhì wúyín de dàyáng.", "en": "Roaring engines and crisscrossing tracks once formed a railway worker's whole horizon. Yet uniforms and schedules, while ordering steps, could never cage a soul yearning for deep seas. Casting off, his world expanded from rails to boundless waters.", "es": "El estruendo de los convoyes y las vías férreas llenaban el mundo del ferroviario. Mas el uniforme y el reloj no pudieron atar un alma sedienta de horizontes marinos. Al zarpar, su mundo saltó del frío raíl a la libertad del mar."}, {"id": "#2", "hanzi": "现代化智能制造转型对产业工人的技能素养提出了崭新要求。依托终身职业技能培训平台，越来越多的传统产线工人成长为精通工业机器人操控的高技能人才，不仅显著提升了制造业智能化水平，也为新型工业化建设注入了源源不断的内生动能。", "pinyin": "Xiàndàihuà zhìnéng zhìzào zhuǎnxíng duì chǎnyè gōngrén de jìnéng sùyǎng tíchū le zhǎnxīn yāoqiú. Yītuō zhōngshēn zhíyè jìnéng péixùn píngtái, yuèláiyuè duō de chuántǒng chǎnxiàn gōngrén chéngzhǎng wéi jīngtōng gōngyè jīqìrén cāokòng de gāojìnéng réncái, bùjǐn xiǎnzhù tíshēng le zhìzàoyè zhìnénghuà shuǐpíng, yě wèi xīnxíng gōngyèhuà jiànshè zhùrù le yuányuán bùduàn de nèishēng dòngnéng.", "en": "Smart manufacturing demands upgraded technical competencies from industrial workers. Vocational training empowers factory workers to become skilled robotics operators, elevating factory automation and injecting vitality into new industrialization.", "es": "La fabricación inteligente impone nuevas competencias a los operarios industriales. Los cursos de reciclaje técnico convierten a los trabajadores de línea en expertos en robótica, elevando la automatización y dinamizando el tejido industrial."}]}, {"meanings_summary": {"en": "wife; Mrs.; madam; married woman", "es": "esposa; mujer; señora; doña"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Addressing the lady of the household with the highest honor (太) repeated twice creates the respectful title for a wife (太太).", "composite_memory_hook_es": "Dirigirse a la dueña de la casa con el máximo respeto (太) por duplicado conforma el trato digno hacia la esposa (太太).", "cultural_and_cognitive_roots": "Originally in ancient China, '太太' was reserved as a high title for the mothers and grandmothers of feudal lords (e.g. the Three Tais of the Zhou dynasty). In modern times, it evolved into the polite term for a married woman.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone followed by neutral tone: tài tai (51-0). Deliver the first syllable firmly down from pitch 5 to 1, followed by a light, unaccented neutral syllable."}, "semantic_boundary_contrasts": {"core_nuance": "太太 is a polite, respectful term for a married woman or someone's spouse, often used in social settings.", "contrasts": [{"id": "1", "compared_word": "太太 vs. 老婆", "pinyin": "lǎopo", "analysis": "太太 is formal, courteous, and respectful in social polite discourse (张太太, 他太太), whereas 老婆 is affectionate, informal, colloquial oral speech used at home."}, {"id": "2", "compared_word": "太太 vs. 妻子", "pinyin": "qīzi", "analysis": "太太 is an address form or social term, while 妻子 is the formal legal and standard written term for 'spouse/wife' in law and essays."}, {"id": "3", "compared_word": "太太 vs. 女士", "pinyin": "nǚshì", "analysis": "太太 specifically implies marriage and spousal status, whereas 女士 is a modern professional title for any woman regardless of marital status."}]}, "traps_and_cognates": {"look_alikes": [{"character": "太", "pinyin": "tài", "meaning_en": "greatest; supreme", "distinction_note": "Has a dot 丶 at the bottom center of 大"}, {"character": "大", "pinyin": "dà", "meaning_en": "big; great", "distinction_note": "Lacks the bottom dot: 大"}, {"character": "犬", "pinyin": "quǎn", "meaning_en": "dog; hound", "distinction_note": "Has a dot 丶 in the upper right quadrant"}, {"character": "天", "pinyin": "tiān", "meaning_en": "sky; heaven", "distinction_note": "Has a horizontal stroke 一 on top of 大"}], "etymological_cognates": [{"character": "太阳", "pinyin": "tài yáng", "gloss_en": "sun; sunshine"}, {"character": "太极", "pinyin": "tài jí", "gloss_en": "Tai Chi; supreme ultimate"}, {"character": "老太", "pinyin": "lǎo tài", "gloss_en": "old woman; elderly lady"}, {"character": "太空", "pinyin": "tài kōng", "gloss_en": "outer space; cosmos"}]}, "id": "32", "hanzi": "太太", "pinyin": "tài tai", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a married woman; one's own or another's wife", "definition_es": "esposa; cónyuge femenina", "example_phrase": "他太太很贤惠 (his wife is very virtuous)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Formal", "definition_en": "polite title of address for a married woman; Mrs.; Madam", "definition_es": "tratamiento de cortesía para una mujer casada; señora", "example_phrase": "王太太 (Mrs. Wang)"}], "example_sentences": [{"id": "#1", "hanzi": "面对辞职航海的疯狂提议，翟峰的太太没有丝毫埋怨，而是选择坚定地与丈夫并肩踏上未知旅途。", "pinyin": "Miànduì cízhí hánghǎi de fēngkuáng tíyì, Zhái Fēng de tàitai méiyǒu sīháo mányuàn, ér shì xuǎnzé jiāndìng de yǔ zhàngfu bìngjiān tà shàng wèizhī lǚtú.", "en": "Faced with the wild proposal to quit work and sail, Zhai Feng's wife harbored no complaint, choosing steadfastly to set out with her husband.", "es": "Ante la descabellada idea de renunciar al trabajo y lanzarse al mar, la esposa de Zhai Feng no dudó, optando por acompañar a su marido a lo desconocido."}, {"id": "#2", "hanzi": "大使携太太出席了国庆招待晚宴，与来自各国的政要及友好人士进行了亲切友好的文化交流。", "pinyin": "Dàshǐ xié tàitai chūxí le guóqìng zhāodài wǎnyàn, yǔ láizì gèguó de zhèngyào jí yǒuhǎo rénshì jìnxíng le qīnqiè yǒuhǎo de wénhuà jiāoliú.", "en": "Accompanied by his wife, the ambassador attended the reception banquet, engaging in cordial cultural dialogues with dignitaries.", "es": "Acompañado por su distinguida esposa, el embajador asistió a la recepción oficial y conversó cordialmente con dignatarios extranjeros."}], "collocations": [{"hanzi": "老太太", "en": "elderly lady; grandmother"}, {"hanzi": "陪太太", "en": "accompany one's wife"}, {"hanzi": "全职太太", "en": "full-time housewife"}, {"hanzi": "王太太", "en": "Mrs. Wang"}, {"hanzi": "富太太", "en": "wealthy madam / rich lady"}, {"hanzi": "年轻太太", "en": "young married woman"}], "idioms": [{"hanzi": "相敬如宾", "pinyin": "xiāng jìng rú bīn", "meaning_en": "treat each other with the respect due to an honored guest (of spouses)"}, {"hanzi": "夫唱妇随", "pinyin": "fū chàng fù suí", "meaning_en": "husband sings and wife follows; marital harmony and cooperation"}, {"hanzi": "白头偕老", "pinyin": "bái tóu xié lǎo", "meaning_en": "remain together until white-haired old age; grow old together"}, {"hanzi": "结发夫妻", "pinyin": "jié fà fū qī", "meaning_en": "husband and wife tied in youth; original married couple"}], "character_decomposition": [{"character": "太", "pinyin": "tài", "meaning_en": "highest; greatest; excessive", "meaning_es": "supremo; grandísimo; excesivo", "radical": "大", "radical_meaning_en": "big / great", "meaning_component": "大 (person standing wide)", "sound_component": "丶 (drop or dot denoting supreme degree)", "stroke_count": "4", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient ideograph: adding a diacritical dot (丶) beneath a towering person (大) to signify the utmost, grandest rank.", "visual_mnemonic_story_en": "A distinguished person (大) honored with a precious jade pendant (丶), denoting supreme status.", "visual_mnemonic_story_es": "Una persona insigne (大) que porta una valiosa joya (丶) simbolizando la máxima distinción honorífica.", "tone_mnemonic_anchor": "51", "cangjie": "KI", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "航海日志里记录着许多琐碎而温存的细节。每当深夜狂风骤起，妻子总是默默递上一杯热茶，用温柔的目光抚平丈夫的紧绷。生活中的相濡以沫，不在于海誓山盟的豪迈，而在于危难时刻并肩承受风雨的无言担当。", "pinyin": "Hánghǎi rìzhì lǐ jìlù zhe xǔduō suǒsuì ér wēncún de xìjié. Měi dāng shēnyè kuángfēng zhòuqǐ, qīzi zǒngshì mòmò dì shàng yì bēi rèchá, yòng wēnróu de mùguāng fǔpíng zhàngfu de jǐnbēng. Shēnghuó zhōng de xiāngrúyǐmò, bú zàiyú hǎishìmòméng de háomài, ér zàiyú wēinàn shíkè bìngjiān chéngshòu fēngyǔ de wúyán dāndāng.", "en": "The logbook preserves tender domestic details. When nocturnal gales struck, his wife quietly passed warm tea, soothing tension with a calm gaze. True spousal devotion lies not in grand vows, but in weathering storms shoulder to shoulder.", "es": "El diario de a bordo guarda tiernos detalles cotidianos. En mitad del temporal nocturno, la esposa servía té caliente, apaciguando la tensión con una mirada dulce. La complicidad conyugal no vive de vanas promesas, sino de afrontar juntos la tormenta en silencio."}, {"id": "#2", "hanzi": "跨文化社会学调查发现，汉语中对配偶称谓的变迁深刻映射了家庭结构的现代转型。从旧时代的尊卑礼制称谓，到现代社会中“太太”与“爱人”的通用，折射出男女平等理念在婚姻生活中的确立，以及夫妻双方对等协作伙伴关系的重构。", "pinyin": "Kuàwénhuà shèhuìxué diàochá fāxiàn, Hànyǔ zhōng duì pèi'ǒu chēngwèi de biànqiān shēnkè yìngshè le jiātíng jiégòu de xiàndài zhuǎnxíng. Cóng jiù shídài de zūnbēi lǐzhì chēngwèi, dào xiàndài shèhuì zhōng \"tàitai\" yǔ \"àiren\" de tōngyòng, zhéshè chū nánnǚ píngděng lǐniàn zài hūnyīn shēnghuó zhōng de quèlì, yǐjí fūqī shuāngfāng duìděng xiézuò huǒbàn guānxì de chónggòu.", "en": "Sociological research shows shifts in marital address terms reflect modern family evolutions. Transitioning from feudal hierarchical honorifics to terms like '太太' illuminates gender equality gains and marital partnerships based on equal mutual respect.", "es": "Los estudios sociológicos muestran que la evolución de los apelativos conyugales refleja la modernización familiar. El paso de tratamientos feudales a términos de cortesía visibiliza la igualdad de género y la consolidación de matrimonios basados en la complicidad mutua."}]}, {"meanings_summary": {"en": "at any time; at all times; whenever necessary; constantly", "es": "en cualquier momento; en todo momento; a cualquier hora; cuando sea necesario"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Following along (随) the continuous footsteps of time (时) means being ready at any given moment (随时).", "composite_memory_hook_es": "Seguir de cerca (随) el paso incesante de las horas (时) implica estar dispuesto en cualquier momento (随时).", "cultural_and_cognitive_roots": "Daoist philosophy emphasizes '随顺自然' (flowing in harmony with nature's seasons). '随时' encapsulates responsiveness, flexibility, and adaptable readiness to life's unfolding shifts.", "tone_sandhi_and_pitch_modulation": "Two consecutive rising 2nd tones: suí shí (35-35). Rise gently on 'suí' before continuing the melodic elevation on 'shí'."}, "semantic_boundary_contrasts": {"core_nuance": "随时 stresses temporal flexibility, readiness, or constant availability whenever needed.", "contrasts": [{"id": "1", "compared_word": "随时 vs. 及时", "pinyin": "jíshí", "analysis": "随时 indicates anytime without time constraints (随时打电话), whereas 及时 means promptly or without delay right when a problem occurs (及时发现问题)."}, {"id": "2", "compared_word": "随时 vs. 准时", "pinyin": "zhǔnshí", "analysis": "随时 denotes open-ended flexible timing, while 准时 means punctually at a predetermined appointed minute (准时开会)."}, {"id": "3", "compared_word": "随时 vs. 往往", "pinyin": "wǎngwǎng", "analysis": "随时 denotes potential occurrence at any time, while 往往 indicates recurrent frequency based on past patterns."}]}, "traps_and_cognates": {"look_alikes": [{"character": "随", "pinyin": "suí", "meaning_en": "follow; adapt", "distinction_note": "Has 阝 on the left with 辶 inside"}, {"character": "队", "pinyin": "duì", "meaning_en": "team; line", "distinction_note": "Has 阝 on the left and 人 on the right"}, {"character": "时", "pinyin": "shí", "meaning_en": "time; season", "distinction_note": "Has 日 on the left and 寸 on the right"}, {"character": "村", "pinyin": "cūn", "meaning_en": "village", "distinction_note": "Has 木 (wood) on the left with 寸"}], "etymological_cognates": [{"character": "随便", "pinyin": "suí biàn", "gloss_en": "as you please; casual"}, {"character": "跟随", "pinyin": "gēn suí", "gloss_en": "follow; accompany"}, {"character": "时候", "pinyin": "shí hou", "gloss_en": "time; moment"}, {"character": "及时", "pinyin": "jí shí", "gloss_en": "in time; timely"}]}, "id": "33", "hanzi": "随时", "pinyin": "suí shí", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "at any point in time; whenever the occasion arises", "definition_es": "en cualquier momento; siempre que sea oportuno o preciso", "example_phrase": "随时联系 (contact at any time)"}], "example_sentences": [{"id": "#1", "hanzi": "海上天气变幻莫测，乌云随时可能遮蔽太阳带来狂风暴雨，全船人员必须时刻保持高度警惕。", "pinyin": "Hǎishàng tiānqì biànhuànmòcè, wūyún suíshí kěnéng zhēbì tàiyáng dài lái kuángfēngbàoyǔ, quán chuán rényuán bìxū shíkè bǎochí gāodù jǐngtì.", "en": "Ocean weather is unpredictable; dark clouds may shroud the sun at any moment to trigger squalls, demanding vigilance.", "es": "El tiempo en el mar es impredecible; negros nubarrones pueden tapar el sol en cualquier instante y desatar tormentas, exigiendo alerta máxima."}, {"id": "#2", "hanzi": "为了应对突发公共卫生事件，三甲医院急诊重症监护团队随时待命，确保绿色救治通道畅通无阻。", "pinyin": "Wèile yìngduì tūfā gōnggòng wèishēng shìjiàn, sānjiǎ yīyuàn jízhěn zhòngzhèng jiānhù tuánduì suíshí dàimìng, quèbǎo lǜsè jiùzhì tōngdào chàngtōng wúzǔ.", "en": "In response to emergency public health incidents, top-tier ICU teams stand by at all times, keeping rapid-response corridors open.", "es": "Para afrontar emergencias sanitarias, los equipos de cuidados intensivos hospitalarios permanecen en guardia permanente, despejando la vía verde de auxilio."}], "collocations": [{"hanzi": "随时联系", "en": "contact at any time"}, {"hanzi": "随时随地", "en": "anytime and anywhere"}, {"hanzi": "随时待命", "en": "on call at all times; stand by"}, {"hanzi": "随时发生", "en": "happen at any moment"}, {"hanzi": "随时更新", "en": "update constantly / at any time"}, {"hanzi": "随时调整", "en": "adjust at any time"}], "idioms": [{"hanzi": "随遇而安", "pinyin": "suí yù ér ān", "meaning_en": "accommodate oneself to circumstances; at ease wherever one is"}, {"hanzi": "随时随地", "pinyin": "suí shí suí dì", "meaning_en": "anytime and anywhere; at all times and places"}, {"hanzi": "随行就市", "pinyin": "suí háng jiù shì", "meaning_en": "adjust prices according to market conditions"}, {"hanzi": "与时俱进", "pinyin": "yǔ shí jù jìn", "meaning_en": "advance with the times; keep pace with history"}], "character_decomposition": [{"character": "随", "pinyin": "suí", "meaning_en": "follow; comply with; adapt", "meaning_es": "seguir; obedecer; adaptarse", "radical": "阝", "radical_meaning_en": "mound / step", "meaning_component": "阝 (lofty embankment or step)", "sound_component": "辶 / 隋 (suí phonetic / flesh or following path)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: following closely behind someone along steps or winding road embankments (阝).", "visual_mnemonic_story_en": "Walking footsteps following closely behind an elder (阝) along the mountain path wherever he leads (随).", "visual_mnemonic_story_es": "Pasos que siguen de cerca a un guía experto (阝) por senderos escarpados allá donde vaya (随).", "tone_mnemonic_anchor": "35", "cangjie": "NLKNB", "traditional": "隨"}, {"character": "时", "pinyin": "shí", "meaning_en": "time; hour; opportunity", "meaning_es": "tiempo; hora; sazón", "radical": "日", "radical_meaning_en": "sun / day", "meaning_component": "日 (sun marking daylight hours)", "sound_component": "寸 (cùn phonetic / inch rule of measurement)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogrammic compound: tracking the sun (日) with an inch rule (寸) to observe passing time.", "visual_mnemonic_story_en": "The golden sun (日) casting its measured inch of shadow (寸) as each moment ticks by.", "visual_mnemonic_story_es": "El sol dorado (日) proyectando una pulgada de sombra (寸) que marca el fluir del tiempo.", "tone_mnemonic_anchor": "35", "cangjie": "ADI", "traditional": "時"}], "extended_reading_passages": [{"id": "#1", "hanzi": "真正的内心自由，是一种随时能够放下包袱启程的勇气。当我们不再执着于外界强加的条条框框，便能在生活的任何一个拐角轻装上阵。生活从来没有固定的剧本，随时敞开怀抱，才能拥抱沿途未曾预料的美丽。", "pinyin": "Zhēnzhèng de nèixīn zìyóu, shì yì zhǒng suíshí nénggòu fàngxià bāofu qǐchéng de yǒngqì. Dāng wǒmen búzài zhízháo yú wàijiè qiángjiā de tiáotiáokuāngkuāng, biàn néng zài shēnghuó de rènhé yí gè guǎijiǎo qīngzhuāng shàngzhèn. Shēnghuó cónglái méiyǒu gùdìng de jùběn, suíshí chǎngkāi huáibào, cáinéng yōngbào yántú wèicéng yùliào de měilì.", "en": "True inner freedom is the courage to drop burdens and set out at any moment. When freed from imposed constraints, one travels light through any crossroad. Life lacks a rigid script; opening one's arms anytime welcomes unforeseen wonder.", "es": "La auténtica libertad interior es la valentía de aligerar equipaje y partir en cualquier momento. Sin el yugo de moldes ajenos, se camina liviano por cualquier encrucijada. La vida no tiene guión fijo: abrir el pecho en todo momento abraza bellezas inesperadas."}, {"id": "#2", "hanzi": "移动互联网与边缘计算的协同演进，使得海量物联网设备能够随时随地实现低时延互联互通。无论是在偏远荒野还是在繁忙都市，智能感知终端均能随时将水文监测数据回传云端中枢，为气象预警与自然资源保护提供了强有力的实时算力支撑。", "pinyin": "Yídòng hùliánwǎng yǔ biānyuán jìsuàn de xiétóng yǎnjìn, shǐdé hǎiliàng wùliánwǎng shèbèi nénggòu suíshí suídì shíxiàn dīshíyán hùliánhùtōng. Wúlùn shì zài piānyuǎn huāngyě háishì zài fánmáng dūshì, zhìnéng gǎnzhī zhōngduān jūn néng suíshí jiāng shuǐwén jiāncè shùjù huíchuán yúnduān zhōngshū, wèi qìxiàng yùjǐng yǔ zìrán zīyuán bǎohù tígōng le qiángyǒulì de shíshí suànlì zhīchēng.", "en": "The evolution of mobile networks and edge computing allows IoT devices to interconnect anytime, anywhere with low latency. In remote wilderness or cities, smart sensors transmit environmental metrics to cloud hubs, powering real-time climate warnings.", "es": "La computación perimetral y el internet móvil permiten conectar millones de sensores en cualquier momento y lugar. Tanto en páramos como en urbes, los terminales envían datos hidrológicos a la nube, respaldando las alertas climáticas en tiempo real."}]}, {"meanings_summary": {"en": "to hug; to embrace; to hold in arms; to welcome open-heartedly", "es": "abrazar; abrazarse; acoger con entusiasmo; abrazo"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Wrapping protective hands around someone (拥) and holding them tenderly in your arms (抱) forms a heartfelt embrace (拥抱).", "composite_memory_hook_es": "Rodear con brazos protectores (拥) y estrechar contra el pecho con ternura (抱) sella un cálido abrazo (拥抱).", "cultural_and_cognitive_roots": "Traditional Chinese etiquette favored polite bowing over public tactile displays. The modern popularity of '拥抱' reflects emotional openness in family and metaphorical acceptance of world trends.", "tone_sandhi_and_pitch_modulation": "High level 1st tone followed by a falling 4th tone: yōng bào (55-51). Sustain 'yōng' high and open before dropping 'bào' with warm downward resonance."}, "semantic_boundary_contrasts": {"core_nuance": "拥抱 conveys warmth, deep emotional resonance, and wholehearted acceptance (physically or metaphorically).", "contrasts": [{"id": "1", "compared_word": "拥抱 vs. 搂", "pinyin": "lǒu", "analysis": "拥抱 is formal, elegant, and affectionate with two people encircling each other, whereas 搂 is colloquial, often indicating one-sided grasping around someone's waist or shoulders."}, {"id": "2", "compared_word": "拥抱 vs. 接受", "pinyin": "jiēshòu", "analysis": "拥抱 implies proactive, enthusiastic, open-armed adoption of changes (拥抱变革), while 接受 is neutral, denoting passive or compliant receipt (接受批评)."}, {"id": "3", "compared_word": "拥抱 vs. 迎接", "pinyin": "yíngjiē", "analysis": "拥抱 focuses on the intimate holding or internalizing, whereas 迎接 describes going out to meet and welcome arriving guests."}]}, "traps_and_cognates": {"look_alikes": [{"character": "拥", "pinyin": "yōng", "meaning_en": "hug; crowd", "distinction_note": "Has 扌 on the left and 邕 on the right"}, {"character": "佣", "pinyin": "yōng", "meaning_en": "commission; servant", "distinction_note": "Has 亻 (person) on the left with 邕"}, {"character": "抱", "pinyin": "bào", "meaning_en": "hold; hug", "distinction_note": "Has 扌 on the left and 包 on the right"}, {"character": "拘", "pinyin": "jū", "meaning_en": "arrest; detain", "distinction_note": "Has 扌 on the left and 句 on the right"}], "etymological_cognates": [{"character": "拥挤", "pinyin": "yōng jǐ", "gloss_en": "crowded; congested"}, {"character": "拥护", "pinyin": "yōng hù", "gloss_en": "support; endorse"}, {"character": "抱怨", "pinyin": "bào yuàn", "gloss_en": "complain; grumble"}, {"character": "抱负", "pinyin": "bào fù", "gloss_en": "ambition; aspiration"}]}, "id": "34", "hanzi": "拥抱", "pinyin": "yōng bào", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to encircle another person with arms in affectionate physical embrace", "definition_es": "estrechar entre los brazos en señal de afecto o cariño; abrazar", "example_phrase": "紧紧拥抱 (hug tightly)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Formal", "definition_en": "to welcome, accept, or adopt eagerly (change, future, opportunity)", "definition_es": "acoger con entusiasmo o abrirse a nuevas realidades", "example_phrase": "拥抱未来 (embrace the future)"}], "example_sentences": [{"id": "#1", "hanzi": "历经重重风浪终于平安靠岸的那一刻，夫妻俩紧紧拥抱在一起，激动的泪水夺眶而出。", "pinyin": "Lìjīng chóngchóng fēnglàng zhōngyú píng'ān kào'àn de nà yí kè, fūqī liǎ jǐnjǐn yōngbào zài yìqǐ, jīdòng de lèishuǐ duókuàng'érchū.", "en": "The moment they docked safely after weathering countless storms, the couple held each other in a tight embrace, tears of relief welling up.", "es": "Al atracar a salvo tras superar incontables temporales, los esposos se fundieron en un apretado abrazo con lágrimas de emoción."}, {"id": "#2", "hanzi": "在技术浪潮席卷全球的当下，企业必须主动打破传统思维定式，积极拥抱数字化变革与人工智能新纪元。", "pinyin": "Zài jìshù làngcháo xíjuǎn quánqiú de dāngxià, qǐyè bìxū zhǔdòng dǎpò chuántǒng sīwéi dìngshì, jījí yōngbào shùzìhuà biàngé yǔ réngōng zhìnéng xīn jìyuán.", "en": "Amid sweeping global technological tides, enterprises must break conventional mindsets to proactively embrace digital transformation.", "es": "Con las olas tecnológicas barriendo el planeta, las empresas deben romper moldes caducos y abrazar resueltamente la transformación digital."}], "collocations": [{"hanzi": "热烈拥抱", "en": "warm / passionate embrace"}, {"hanzi": "紧紧拥抱", "en": "hug tightly"}, {"hanzi": "拥抱未来", "en": "embrace the future"}, {"hanzi": "互相拥抱", "en": "embrace each other"}, {"hanzi": "深情拥抱", "en": "affectionate embrace"}, {"hanzi": "拥抱生活", "en": "embrace life"}], "idioms": [{"hanzi": "投怀送抱", "pinyin": "tóu huái sòng bào", "meaning_en": "throw oneself into someone's arms; ingratiate oneself eagerly"}, {"hanzi": "前呼后拥", "pinyin": "qián hū hòu yōng", "meaning_en": "escorted by callers in front and crowds behind; with a large entourage"}, {"hanzi": "抱头痛哭", "pinyin": "bào tóu tòng kū", "meaning_en": "hold each other's heads and weep bitterly"}, {"hanzi": "左拥右抱", "pinyin": "zuǒ yōng yòu bào", "meaning_en": "embrace right and left; surrounded by concubines or wealth"}], "character_decomposition": [{"character": "拥", "pinyin": "yōng", "meaning_en": "embrace; crowd; support", "meaning_es": "abrazar; apiñarse; apoyar", "radical": "扌", "radical_meaning_en": "hand / arm", "meaning_component": "扌 (arms holding someone close)", "sound_component": "邕 (yōng phonetic / city surrounded by moat or harmonious gathering)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: outstretched arms (扌) gathering someone gently into an intimate protective circle (邕).", "visual_mnemonic_story_en": "Strong loving arms (扌) wrapping affectionately around someone to shelter and support them (拥).", "visual_mnemonic_story_es": "Brazos tiernos y fuertes (扌) que rodean a un ser querido para abrigarlo y protegerlo con afecto (拥).", "tone_mnemonic_anchor": "55", "cangjie": "QYVB", "traditional": "擁"}, {"character": "抱", "pinyin": "bào", "meaning_en": "hold in arms; hug; cherish", "meaning_es": "abrazar; sostener en brazos; albergar", "radical": "扌", "radical_meaning_en": "hand / arm", "meaning_component": "扌 (hands wrapping and holding)", "sound_component": "包 (bāo phonetic / wrap or package)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: hands (扌) wrapping completely around someone like a precious package (包).", "visual_mnemonic_story_en": "Two arms (扌) tenderly wrapping around a child (包) to press them close against the chest.", "visual_mnemonic_story_es": "Dos brazos (扌) que envuelven con ternura a un niño (包) para acunarlo contra el pecho.", "tone_mnemonic_anchor": "51", "cangjie": "QPU", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "在漫长而孤独的航海岁月中，最抚慰人心的莫过于家人的一个拥抱。那不需要任何言语的解释，只要两颗心在风暴过后紧紧贴在一起，所有的恐惧与疲惫便会瞬间消融，化作继续前行的勇气与力量。", "pinyin": "Zài màncháng ér gūdú de hánghǎi suìyuè zhōng, zuì fǔwèi rénxīn de mòguòyú jiārén de yí gè yōngbào. Nà bù xūyào rènhé yányǔ de jiěshì, zhǐyào liǎng kē xīn zài fēngbào guòhòu jǐnjǐn tiē zài yìqǐ, suǒyǒu de kǒngjù yǔ píbèi biàn huì shùnjiān xiāoróng, huàzuò jìxù qiánxíng de yǒngqì yǔ lìliang.", "en": "In long, lonely voyaging months, nothing consoles like a family embrace. Needing no words, two hearts pressing together after storms dissolves fear and exhaustion into renewed courage to sail on.", "es": "En la soledad de la singladura marina, nada reconforta tanto como el abrazo de los tuyos. Sin necesidad de palabras, sentir latir dos corazones tras el temporal disuelve el miedo en renovado aliento para seguir navegando."}, {"id": "#2", "hanzi": "伴随新一轮科技革命的演进，实体经济面临着深刻的组织形态重塑。主动拥抱技术创新、推进智能化改造的企业，不仅能在激烈的全球产业链竞争中抢占先机，更为推动产业升级与可持续高质量发展开拓了广阔空间。", "pinyin": "Bànsuí xīn yì lún kējì gémìng de yǎnjìn, shítǐ jīngjì miànlín zhe shēnkè de zǔzhī xíngtài chóngshù. Zhǔdòng yōngbào jìshù chuàngxīn, tuījìn zhìnénghuà gǎizào de qǐyè, bùjǐn néng zài jīliè de quánqiú chǎnyèliàn jìngzhēng zhōng qiǎngzhàn xiānjī, gèng wèi tuīdòng chǎnyè shēngjí yǔ kěchíxù gāozhìliàng fāzhǎn kāituò le guǎngkuò kōngjiān.", "en": "Amid evolving scientific revolutions, industrial economies undergo deep organizational remodeling. Firms actively embracing technological innovation capture strategic footholds in global competition, opening vistas for quality development.", "es": "La nueva revolución tecnológica redefine las estructuras productivas. Aquellas empresas que abrazan la innovación técnica y la automatización inteligente lideran las cadenas globales de valor, abriendo amplias perspectivas de progreso sostenible."}]}, {"meanings_summary": {"en": "future; tomorrow; coming; approaching; prospective", "es": "futuro; porvenir; venidero; por venir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "What has not yet (未) arrived (来) lies open ahead of us as the promising future (未来).", "composite_memory_hook_es": "Lo que todavía no (未) ha llegado (来) se abre ante nosotros como el prometedor porvenir (未来).", "cultural_and_cognitive_roots": "In Chinese philosophical time perception, the future is envisioned as unmanifest potential ('未') arriving continuously from the horizon ('来'). Optimism and proactive preparation govern one's posture toward tomorrow.", "tone_sandhi_and_pitch_modulation": "Falling 4th tone followed by a rising 2nd tone: wèi lái (51-35). Drop 'wèi' firmly before elevating pitch smoothly on 'lái'."}, "semantic_boundary_contrasts": {"core_nuance": "未来 specifically refers to the temporal domain or prospective era that has not yet occurred.", "contrasts": [{"id": "1", "compared_word": "未来 vs. 将来", "pinyin": "jiānglái", "analysis": "未来 is broader, philosophical, and visionary, modifying technologies and societies (未来科技, 走向未来), while 将来 refers practically to one's later years or forthcoming time (将来打算做什么)."}, {"id": "2", "compared_word": "未来 vs. 前途", "pinyin": "qiántú", "analysis": "未来 denotes objective chronological time ahead, whereas 前途 focuses specifically on personal career prospects, fortunes, or professional destiny (前途一片光明)."}, {"id": "3", "compared_word": "未来 vs. 明天", "pinyin": "míngtiān", "analysis": "未来 encompasses long-term epochs and philosophical tomorrow, while 明天 denotes the literal next calendar day."}]}, "traps_and_cognates": {"look_alikes": [{"character": "未", "pinyin": "wèi", "meaning_en": "not yet", "distinction_note": "Top horizontal stroke is shorter than the second"}, {"character": "末", "pinyin": "mò", "meaning_en": "end; tip", "distinction_note": "Top horizontal stroke is longer than the second"}, {"character": "来", "pinyin": "lái", "meaning_en": "come; arrive", "distinction_note": "Seven strokes with two inner dots"}, {"character": "米", "pinyin": "mǐ", "meaning_en": "rice", "distinction_note": "Six strokes with four angled dots around cross"}], "etymological_cognates": [{"character": "未必", "pinyin": "wèi bì", "gloss_en": "not necessarily; maybe not"}, {"character": "未知", "pinyin": "wéi zhī", "gloss_en": "unknown; unfamiliar"}, {"character": "后来", "pinyin": "hòu lái", "gloss_en": "afterwards; later on"}, {"character": "来临", "pinyin": "lái lín", "gloss_en": "arrive; approach; come"}]}, "id": "35", "hanzi": "未来", "pinyin": "wèi lái", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "time that is yet to come; future days or prospects", "definition_es": "tiempo que está por venir; porvenir; futuro", "example_phrase": "走向未来 (walk into the future)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Formal", "definition_en": "approaching, prospective, or yet to arrive", "definition_es": "futuro; venidero; que llegará en breve", "example_phrase": "未来三年 (in the coming three years)"}], "example_sentences": [{"id": "#1", "hanzi": "面对未知而充满挑战的环球航行，翟峰一家对未来充满信心，坚信人生有无限种可能。", "pinyin": "Miànduì wèizhī ér chōngmǎn tiǎozhàn de huánqiú hángxíng, Zhái Fēng yì jiā duì wèilái chōngmǎn xìnxīn, jiānxìn rénshēng yǒu wúxiàn zhǒng kěnéng.", "en": "Confronting a circumnavigation full of challenges, Zhai Feng's family embraced the future with confidence, convinced life holds limitless possibilities.", "es": "Ante la desafiante vuelta al mundo, la familia de Zhai Feng miró al porvenir con fe, convencida de que la vida alberga infinitas posibilidades."}, {"id": "#2", "hanzi": "国际前沿学术论坛围绕绿色能源与量子计算展开深度研讨，共同勾勒未来数字社会的创新蓝图。", "pinyin": "Guójì qiányán xuéshù lùntán wéirào lǜsè néngyuán yǔ liàngzǐ jìsuàn zhǎnkāi shēndù yántǎo, gòngtóng gōulè wèilái shùzì shèhuì de chuàngxīn lántú.", "en": "The international academic forum deliberated green energy and quantum computing, sketching innovation blueprints for future digital societies.", "es": "El foro científico internacional debatió sobre energías verdes y computación cuántica, trazando la hoja de ruta de la futura sociedad digital."}], "collocations": [{"hanzi": "美好的未来", "en": "bright / beautiful future"}, {"hanzi": "展望未来", "en": "look forward to the future"}, {"hanzi": "充满未来感", "en": "futuristic; full of future vibes"}, {"hanzi": "未见未来", "en": "unseen future"}, {"hanzi": "规划未来", "en": "plan for the future"}, {"hanzi": "走向未来", "en": "head into the future"}], "idioms": [{"hanzi": "前途无量", "pinyin": "qián tú wú liàng", "meaning_en": "have boundless prospects; have an infinitely bright future"}, {"hanzi": "继往开来", "pinyin": "jì wǎng kāi lái", "meaning_en": "carry forward the past and forge into the future"}, {"hanzi": "方兴未艾", "pinyin": "fāng xīng wèi ài", "meaning_en": "just unfolding and in the ascendant; far from coming to an end"}, {"hanzi": "承前启后", "pinyin": "chéng qián qǐ hòu", "meaning_en": "inherit the past and usher in the future"}], "character_decomposition": [{"character": "未", "pinyin": "wèi", "meaning_en": "not yet; 8th earthly branch", "meaning_es": "aún no; todavía no", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "木 (tree foliage)", "sound_component": "一 (shorter top stroke indicating leaves not yet fully grown)", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ideogrammic compound: a tree (木) with its upper branches (一) still young and not yet fully flourished.", "visual_mnemonic_story_en": "A young sapling (木) whose uppermost branch (一) has not yet burst into full summer blossom.", "visual_mnemonic_story_es": "Un arbolito (木) cuyas ramas superiores (一) aún no han florecido plenamente bajo el sol.", "tone_mnemonic_anchor": "51", "cangjie": "JD", "traditional": ""}, {"character": "来", "pinyin": "lái", "meaning_en": "come; arrive; return", "meaning_es": "venir; llegar; regresar", "radical": "木", "radical_meaning_en": "tree / grain plant", "meaning_component": "木 (cereal plant)", "sound_component": "从 / 麦 (wheat ears arriving from heaven as a gift)", "stroke_count": "7", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of an ear of ripe wheat descending from the heavens to nourish humanity.", "visual_mnemonic_story_en": "Ripe golden wheat stalks (来) arriving across the fields like a bountiful harvest blessing.", "visual_mnemonic_story_es": "Espigas de trigo maduro (来) que llegan meciéndose por los campos como una bendición de la tierra.", "tone_mnemonic_anchor": "35", "cangjie": "DT", "traditional": "來"}], "extended_reading_passages": [{"id": "#1", "hanzi": "未来从来不是一个遥不可及的彼岸，它就孕育在我们当下的每一个选择与行动之中。与其为不可知的明天患得患失，不如全身心地投入眼前的每一次起航。勇敢面对风浪的人，终将在时间的洗礼下迎来属于自己的灿烂曙光。", "pinyin": "Wèilái cónglái bú shì yí gè yáobùkějí de bǐ'àn, tā jiù yùnyù zài wǒmen dāngxià de měi yí gè xuǎnzé yǔ xíngdòng zhīzhōng. Yǔqí wèi bùkězhī de míngtiān huàndéhuànshī, bùrú quánxīnxīnyì de tóurù yǎnqián de měi yí cì qǐháng. Yǒnggǎn miànduì fēnglàng de rén, zhōng jiāng zài shíjiān de xǐlǐ xià yínglái shǔyú zìjǐ de cànlàn shǔguāng.", "en": "The future is no unreachable shore; it incubates in every choice and deed of the present. Rather than fretting over tomorrow's uncertainties, throw your whole soul into each casting off. The brave greet their radiant dawn.", "es": "El porvenir no es una ribera inalcanzable: germina en cada decisión y acto del presente. En vez de vacilar ante el mañana incierto, conviene entregarse a cada travesía con el alma. Quien desafía las olas cosecha su propia alborada."}, {"id": "#2", "hanzi": "全球可持续发展战略正在深刻定义人类社会的未来格局。通过大力发展清洁低碳能源与循环经济模式，世界各国正携手应对极端气候变化挑战。这一历史进程不仅关乎当代人的生存福祉，更承载着为子孙后代构筑绿色宜居家园的庄严历史承诺。", "pinyin": "Quánqiú kěchíxù fāzhǎn zhànlüè zhèngzài shēnkè dìngyì rénlèi shèhuì de wèilái gégjú. Tōngguò dàlì fāzhǎn qīngjié dītàn néngyuán yǔ xúnhuán jīngjì móshì, shìjiè gèguó zhèng xiéshǒu yìngduì jíduān qìhòu biànhuà tiǎozhàn. Zhè yí lìshǐ jìnchéng bùjǐn guānhū dāngdàirén de shēngcún fúzhǐ, gèng chéngzài zhe wèi zǐsūnhòudài gòuzhù lǜsè yíjū jiāyuán de zhuāngyán lìshǐ chéngnuò.", "en": "Global sustainability frameworks are defining humanity's future configuration. Accelerating clean energy and circular economic models tackles climate shocks, ensuring present well-being while fulfilling a solemn compact to bequeath a green homeland to progeny.", "es": "El desarrollo sostenible define el porvenir de la humanidad. Impulsar energías limpias y economía circular combate el cambio climático, garantizando el bienestar presente y blindando el compromiso histórico de legar un planeta verde a las futuras generaciones."}]}, {"meanings_summary": {"en": "nautical mile; sea mile (unit of maritime distance, approx. 1,852 meters)", "es": "milla náutica; milla marina (unidad de distancia marina, aprox. 1.852 metros)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Measuring navigational distance across the vast blue ocean (海) using standardized sea leagues (里) gives the nautical mile (海里).", "composite_memory_hook_es": "Medir las leguas (里) navegadas a través del inmenso mar (海) define la milla náutica (海里).", "cultural_and_cognitive_roots": "The international nautical mile (1,852 meters) corresponds to one minute of latitude on the earth's surface. In modern Chinese maritime law, it designates boundary baselines and exclusive economic zones.", "tone_sandhi_and_pitch_modulation": "Two consecutive dipping 3rd tones: hǎi lǐ (214-214). Under 3rd tone sandhi, 'hǎi' changes into a rising 2nd tone: hái lǐ (35-214)."}, "semantic_boundary_contrasts": {"core_nuance": "海里 is strictly the maritime and aviation unit of distance (1 nautical mile = 1.852 km).", "contrasts": [{"id": "1", "compared_word": "海里 vs. 公里", "pinyin": "gōnglǐ", "analysis": "海里 is used exclusively in marine navigation and aviation (1海里 = 1.852公里), while 公里 (kilometer) is the universal metric land distance unit."}, {"id": "2", "compared_word": "海里 vs. 里", "pinyin": "lǐ", "analysis": "海里 is a nautical mile, whereas 里 refers to the traditional Chinese land unit of 500 meters (半公里)."}, {"id": "3", "compared_word": "海里 vs. 节", "pinyin": "jié", "analysis": "海里 is a unit of absolute spatial distance, whereas 节 (knot) is a unit of navigational speed (1节 = 1海里/小时)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "海", "pinyin": "hǎi", "meaning_en": "sea; ocean", "distinction_note": "Has 氵 on the left and 每 on the right"}, {"character": "梅", "pinyin": "méi", "meaning_en": "plum", "distinction_note": "Has 木 on the left with 每"}, {"character": "里", "pinyin": "lǐ", "meaning_en": "mile; inside", "distinction_note": "Composed of 田 top and 土 bottom"}, {"character": "重", "pinyin": "zhòng", "meaning_en": "heavy; repeat", "distinction_note": "Has vertical stroke cutting through center"}], "etymological_cognates": [{"character": "海洋", "pinyin": "hǎi yáng", "gloss_en": "ocean; sea"}, {"character": "里程", "pinyin": "lǐ chéng", "gloss_en": "mileage; milestone"}, {"character": "公里", "pinyin": "gōng lǐ", "gloss_en": "kilometer"}, {"character": "华里", "pinyin": "huá lǐ", "gloss_en": "traditional Chinese li (500 meters)"}]}, "id": "36", "hanzi": "海里", "pinyin": "hǎi lǐ", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "unit of distance used in maritime and aerial navigation, equal to 1,852 meters", "definition_es": "unidad de distancia usada en navegación marítima y aérea (1.852 m)", "example_phrase": "航行五十海里 (sail fifty nautical miles)"}], "example_sentences": [{"id": "#1", "hanzi": "帆船以平均六节的航速日夜前行，全家人在两个月内顺利完成了上千海里的远洋航程。", "pinyin": "Fānchuán yǐ píngjūn liù jié de hángsù rìyè qiánxíng, quán jiārén zài liǎng gè yuè nèi shùnlì wánchéng le shàng qiān hǎilǐ de yuǎnyáng hángchéng.", "en": "The sailboat advanced day and night at an average speed of six knots, completing over a thousand nautical miles within two months.", "es": "El velero navegó día y noche a una media de seis nudos, completando con éxito más de mil millas náuticas en dos meses."}, {"id": "#2", "hanzi": "海事搜救直升机飞赴距海岸线两百海里的外海区域，成功营救出遇险货轮上的受困船员。", "pinyin": "Hǎishì sōujiù zhíshēngjī fēifù jù hǎi'ànxiàn liǎng bǎi hǎilǐ de wàihǎi qūyù, chénggōng yíngjiù chū yùxiǎn huòlún shàng de shòukùn chuányuán.", "en": "The maritime rescue helicopter flew 200 nautical miles offshore, successfully rescuing stranded crew members from the distressed freighter.", "es": "El helicóptero de salvamento marítimo voló a doscientas millas náuticas mar adentro para rescatar a los marineros de un mercante en apuros."}], "collocations": [{"hanzi": "航行海里", "en": "nautical miles sailed"}, {"hanzi": "十海里", "en": "ten nautical miles"}, {"hanzi": "两百海里专属经济区", "en": "200-nautical-mile Exclusive Economic Zone"}, {"hanzi": "每小时海里数", "en": "knots / nautical miles per hour"}, {"hanzi": "数千海里", "en": "thousands of nautical miles"}, {"hanzi": "一海里", "en": "one nautical mile"}], "idioms": [{"hanzi": "鹏程万里", "pinyin": "péng chéng wàn lǐ", "meaning_en": "the roc flies ten thousand li; have a bright, boundless future"}, {"hanzi": "沧海一粟", "pinyin": "cāng hǎi yí sù", "meaning_en": "a single grain in the vast blue sea; a tiny drop in the ocean"}, {"hanzi": "万里之行，始于足下", "pinyin": "wàn lǐ zhī xíng, shǐ yú zú xià", "meaning_en": "a journey of a thousand li begins with a single step"}, {"hanzi": "四海为家", "pinyin": "sì hǎi wéi jiā", "meaning_en": "make one's home anywhere within the four seas; feel at home anywhere"}], "character_decomposition": [{"character": "海", "pinyin": "hǎi", "meaning_en": "ocean; sea", "meaning_es": "mar; océano", "radical": "氵", "radical_meaning_en": "water / liquid", "meaning_component": "氵 (vast rolling ocean waves)", "sound_component": "每 (měi phonetic / maternal fertility and abundance)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: boundless waters (氵) embracing every stream like a mother (每).", "visual_mnemonic_story_en": "Vast blue water (氵) stretching infinitely like an all-embracing mother (每).", "visual_mnemonic_story_es": "Inmensas aguas azules (氵) que se extienden como una madre infinita (每).", "tone_mnemonic_anchor": "214", "cangjie": "EOWY", "traditional": ""}, {"character": "里", "pinyin": "lǐ", "meaning_en": "li (unit of distance); village; inside", "meaning_es": "li (unidad de distancia); legua china", "radical": "里", "radical_meaning_en": "field / village", "meaning_component": "田 (cultivated crop fields)", "sound_component": "土 (earth / land boundaries)", "stroke_count": "7", "composition_type": "上下结构", "etymology_and_mnemonic": "Ideogrammic compound: marked fields (田) divided by earthen boundary balks (土), ancient unit of distance.", "visual_mnemonic_story_en": "Paced boundaries marked with earth (土) dividing farmers' fields (田) into measurable leagues.", "visual_mnemonic_story_es": "Límites de tierra (土) que demarcan los bancales cultivados (田) en leguas mensurables.", "tone_mnemonic_anchor": "214", "cangjie": "WG", "traditional": "裡"}], "extended_reading_passages": [{"id": "#1", "hanzi": "航海日志上的每一个数字，都凝聚着全家人的汗水与梦想。每一海里的推进，都伴随着与洋流和季风的搏击。当帆船终于跨越数千海里抵达彼岸，那些在风浪中丈量的距离，已化作生命中最坚实、最辉煌的勋章。", "pinyin": "Hánghǎi rìzhì shàng de měi yí gè shùzì, dōu níngjù zhe quán jiārén de hànshuǐ yǔ mèngxiǎng. Měi yì hǎilǐ de tuījìn, dōu bànsuí zhe yǔ yángliú hé jìfēng de bójī. Dāng fānchuán zhōngyú kuàyuè shù qiān hǎilǐ dǐdá bǐ'àn, nàxiē zài fēnglàng zhōng zhàngliáng de jùlí, yǐ huàzuò shēngmìng zhōng zuì jiānshí, zuì huīhuáng de xūnzhāng.", "en": "Every figure in the logbook distills family sweat and aspirations. Every nautical mile gained fought ocean currents and monsoons. Surmounting thousands of miles, distances measured in tempests become life's proudest medals.", "es": "Cada número del cuaderno de bitácora destila sudor y sueños. Cada milla náutica ganada fue un pulso con las corrientes y el viento. Al salvar miles de millas hasta la otra orilla, la distancia se tornó en la más brillante medalla vital."}, {"id": "#2", "hanzi": "国际海洋法公约明确规定了两百海里专属经济区的法律制度，赋予沿海国勘探、开发和养护自然资源的主权权利。海事执法编队定期对专属经济区海域展开例行巡航，有效维护了国家海洋权益与海洋生物资源的可持续开发秩序。", "pinyin": "Guójì hǎiyángfǎ gōngyuē míngquè guīdìng le liǎng bǎi hǎilǐ zhuānshǔ jīngjìqū de fǎlǜ zhìdù, fùyǔ yánhǎiguó kāntàn, kāifā hé yǎnghù zìrán zīyuán de zhǔquán quánlì. Hǎishì zhífǎ biānduì dìngqī duì zhuānshǔ jīngjìqū hǎiyù zhǎnkāi lìxíng xúnháng, yǒuxiào wéihù le guójiā hǎiyáng quányì yǔ hǎiyáng shēngwù zīyuán de kěchíxù kāifā zhìxù.", "en": "The UN Convention on the Law of the Sea establishes 200-nautical-mile Exclusive Economic Zones, granting sovereign rights to coastal states. Maritime patrols in EEZ waters safeguard territorial marine interests and sustainable aquaculture exploitation.", "es": "La Convención sobre el Derecho del Mar reconoce la Zona Económica Exclusiva de doscientas millas náuticas, otorgando derechos soberanos a los Estados ribereños. Las patrullas regulares protegen los recursos marinos y el orden sostenible."}]}, {"meanings_summary": {"en": "flight of steps; staircase; steps; way out of awkward situation; level", "es": "escalones; peldaños; grada; salida de apuro; nivel"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Carving elevated stone terraces (台) into terraced flights of stairs (阶) creates the steps we climb to reach high ground (台阶).", "composite_memory_hook_es": "Labrar gradas de piedra (台) en peldaños escalonados (阶) conforma la escalera que permite subir a lo alto (台阶).", "cultural_and_cognitive_roots": "In traditional Chinese social psychology, '面子' (face) is paramount. '给台阶下' provides a metaphorical staircase for an embarrassed party to step down gracefully without losing dignity.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone followed by a high level 1st tone: tái jiē (35-55). Ascend cleanly on 'tái' and pronounce 'jiē' with sustained high clarity."}, "semantic_boundary_contrasts": {"core_nuance": "台阶 designates physical outdoor/indoor masonry steps, or metaphorically a dignified exit from an embarrassing predicament.", "contrasts": [{"id": "1", "compared_word": "台阶 vs. 楼梯", "pinyin": "lóutī", "analysis": "台阶 refers to stone/concrete flights of steps outside buildings, temples, or quays, while 楼梯 refers to complete indoor staircases connecting building floors."}, {"id": "2", "compared_word": "台阶 vs. 梯子", "pinyin": "tīzi", "analysis": "台阶 is a fixed structural masonry stairway, whereas 梯子 is a portable movable wooden or aluminum ladder."}, {"id": "3", "compared_word": "台阶 vs. 阶段", "pinyin": "jiēduàn", "analysis": "台阶 is a concrete physical step or face-saving opportunity, while 阶段 is an abstract temporal phase or chronological epoch."}]}, "traps_and_cognates": {"look_alikes": [{"character": "台", "pinyin": "tái", "meaning_en": "platform; desk", "distinction_note": "Five strokes with 厶 top and 口 bottom"}, {"character": "各", "pinyin": "gè", "meaning_en": "each; every", "distinction_note": "Six strokes with 夂 top and 口 bottom"}, {"character": "阶", "pinyin": "jiē", "meaning_en": "steps; stairs", "distinction_note": "Has 阝 on the left and 介 on the right"}, {"character": "队", "pinyin": "duì", "meaning_en": "team; ranks", "distinction_note": "Has 阝 on the left and 人 on the right"}], "etymological_cognates": [{"character": "平台", "pinyin": "píng tái", "gloss_en": "platform; terrace; forum"}, {"character": "看台", "pinyin": "kàn tái", "gloss_en": "bleachers; grandstand"}, {"character": "阶段", "pinyin": "jiē duàn", "gloss_en": "stage; phase; period"}, {"character": "阶级", "pinyin": "jiē jí", "gloss_en": "social class; rank"}]}, "id": "37", "hanzi": "台阶", "pinyin": "tái jiē", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a series of flat outdoor or indoor steps constructed for walking up and down", "definition_es": "serie de escalones para subir o bajar; gradas", "example_phrase": "登上台阶 (climb up the steps)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Colloquial", "definition_en": "an opportunity or face-saving way out of an embarrassing deadlock", "definition_es": "salida airosa de un apuro; forma de salvar las apariencias", "example_phrase": "给他一个台阶下 (give him a face-saving way out)"}], "example_sentences": [{"id": "#1", "hanzi": "帆船终于停靠在码头，全家人踩着石砌的台阶缓缓走上海岸，心中涌起无限的感慨与欣喜。", "pinyin": "Fānchuán zhōngyú tíngkào zài mǎtou, quán jiārén cǎi zhe shíqì de táijiē huǎnhuǎn zǒu shàng hǎi'àn, xīnzhōng yǒngqǐ wúxiàn de gǎnkǎi yǔ xīnxǐ.", "en": "The sailboat finally docked at the pier, and the family climbed the stone steps onto shore with boundless emotion and joy.", "es": "El velero atracó al fin en el muelle y la familia subió despacio los peldaños de piedra hacia la costa, embargada de emoción y júbilo."}, {"id": "#2", "hanzi": "在激烈的商务谈判陷入僵局时，主持人适时提出折中方案，为双方各自找了个体面的台阶下。", "pinyin": "Zài jīliè de shāngwù tánpàn xiànrù jiāngjú shí, zhǔchírén shìshí tíchū zhézhōng fāng'àn, wèi shuāngfāng gèzì zhǎo le gè tǐmiàn de táijiē xià.", "en": "When intense negotiations hit an impasse, the moderator proposed a compromise, offering both sides a dignified way out.", "es": "Ante el bloqueo de la negociación, el mediador planteó un acuerdo de compromiso, brindando a ambas partes una salida airosa y digna."}], "collocations": [{"hanzi": "下台阶", "en": "go down the steps; find a face-saving way out"}, {"hanzi": "石台阶", "en": "stone steps"}, {"hanzi": "走下台阶", "en": "walk down the steps"}, {"hanzi": "上台阶", "en": "go up steps; reach a new level"}, {"hanzi": "迈上新台阶", "en": "step up to a new level / higher stage"}, {"hanzi": "找台阶下", "en": "look for a face-saving exit"}], "idioms": [{"hanzi": "步步高升", "pinyin": "bù bù gāo shēng", "meaning_en": "rise step by step; climb higher and higher promotion"}, {"hanzi": "登高望远", "pinyin": "dēng gāo wàng yuǎn", "meaning_en": "climb high to gaze far; take a broad long-term view"}, {"hanzi": "拾级而上", "pinyin": "shè jí ér shàng", "meaning_en": "climb steps step by step; ascend a flight of stairs"}, {"hanzi": "顺理成章", "pinyin": "shùn lǐ chéng zhāng", "meaning_en": "follow as a logical consequence; fall into place naturally"}], "character_decomposition": [{"character": "台", "pinyin": "tái", "meaning_en": "platform; stage; terrace", "meaning_es": "plataforma; estrado; terraza", "radical": "口", "radical_meaning_en": "mouth / base", "meaning_component": "厶 (sī phonetic / private boundary)", "sound_component": "口 (platform foundation or opening)", "stroke_count": "5", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient pictograph of a raised observation platform built of stone or earth to overlook surroundings.", "visual_mnemonic_story_en": "A sturdy elevated observation terrace (台) with level stone slabs allowing people to climb high.", "visual_mnemonic_story_es": "Una sólida terraza o estrado de piedra (台) que permite elevarse para otear el horizonte.", "tone_mnemonic_anchor": "35", "cangjie": "IR", "traditional": "臺"}, {"character": "阶", "pinyin": "jiē", "meaning_en": "steps; stairs; rank", "meaning_es": "escalón; peldaño; rango", "radical": "阝", "radical_meaning_en": "mound / step", "meaning_component": "阝 (lofty earthen slopes with steps)", "sound_component": "价 / 介 (jiè phonetic / divider or border marker)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound: stone steps carved into an earthen slope (阝) marked with clear increments (介).", "visual_mnemonic_story_en": "Stone stairs carved step by step into a rocky earthen hillside (阝) to climb upward (阶).", "visual_mnemonic_story_es": "Peldaños de piedra labrados en una ladera escarpada (阝) para ascender paso a paso (阶).", "tone_mnemonic_anchor": "55", "cangjie": "NLOLL", "traditional": "階"}], "extended_reading_passages": [{"id": "#1", "hanzi": "走过岁月漫长的风雨，才明白人生的每一步攀登都需要脚踏实地。生活不会铺就平坦的捷径，那些看似陡峭的台阶，正是磨砺意志的试金石。只要不轻言放弃，每一个台阶都将把你引向更开阔的人生视界。", "pinyin": "Zǒuguò suìyuè màncháng de fēngyǔ, cái míngbai rénshēng de měi yí bù pāndēng dōu xūyào jiǎotàshídì. Shēnghuó bú huì pūjiù píngtǎn de jiéjìng, nàxiē kànsì dǒuqiào de táijiē, zhèng shì mólì yìzhì de shìjīnshí. Zhǐyào bù qīngyán fàngqì, měi yí gè táijiē dōu jiāng bǎ nǐ yǐnxiàng gèng kāikuò de rénshēng shìjiè.", "en": "Traversing long years of storm teaches that every ascent requires steady footwork. Life lays down no effortless shortcuts; steep steps test the spirit's mettle. Persisting unyieldingly, each step elevates you to wider life vistas.", "es": "Superados los temporales del camino se comprende que cada ascensión exige pisar firme. La vida no regala atajos llanos: los peldaños empinados forjan el carácter. Quien no se rinde descubre que cada grada abre horizontes más diáfanos."}, {"id": "#2", "hanzi": "产业经济学最新评估报告显示，高端装备制造核心技术的自主攻关推动了国家工业基础迈上新台阶。在数控机床、工业软件及关键基础零部件领域取得的系统性突破，有力夯实了现代化产业体系的抗风险底座与自主创新活力。", "pinyin": "Chǎnyè jīngjìxué zuìxīn pínggū bàogào xiǎnshì, gāoduān zhuāngbèi zhìzào héxīn jìshù de zìzhǔ gōngguān tuīdòng le guójiā gōngyè jīchǔ mài shàng xīn táijiē. Zài shùkòng jīchuáng, gōngyè ruǎnjiàn jí guānjiàn jīchǔ língbùjiàn lǐngyù qǔdé de xìtǒngxìng tūpò, yǒulì hāngshí le xiàndàihuà chǎnyè tǐxì de kàngfēngxiǎn dǐzuò yǔ zìzhǔ chuàngxīn huólì.", "en": "Industrial reports indicate domestic breakthroughs in high-end equipment have propelled the nation's industrial foundation onto a new tier. Milestones across CNC tooling and software solidify modernized supply chain resilience and sovereign vitality.", "es": "Los informes industriales confirman que la innovación en maquinaria avanzada ha llevado la base productiva nacional a un nuevo nivel. Los logros en robótica y software industrial apuntalan la resiliencia y soberanía del tejido productivo."}]}, {"meanings_summary": {"en": "era; age; epoch; times; historical period", "es": "época; era; período histórico; tiempos; edad"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The unfolding sun of history (时) carried forward by successive generations (代) forms a grand historical era (时代).", "composite_memory_hook_es": "El curso solar del tiempo (时) trasvasado entre generaciones sucesivas (代) forja una gran época histórica (时代).", "cultural_and_cognitive_roots": "Traditional Chinese historiography structured cosmic time through dynasty shifts and generation successions ('代代相传'). '时代' captures the zeitgeist—the unique spiritual pulse and material characteristics of an age.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone followed by a falling 4th tone: shí dài (35-51). Elevate pitch on 'shí' before dropping firmly on 'dài'."}, "semantic_boundary_contrasts": {"core_nuance": "时代 specifically designates an expansive macro-historical epoch defined by dominant cultural, economic, or technological hallmarks.", "contrasts": [{"id": "1", "compared_word": "时代 vs. 时期", "pinyin": "shíqī", "analysis": "时代 refers to grand, transformative historical epochs (如工业时代, 封建时代), while 时期 refers to specific, shorter political, military, or life intervals (如抗战时期, 实习时期)."}, {"id": "2", "compared_word": "时代 vs. 年代", "pinyin": "niándài", "analysis": "时代 defines qualitative cultural/technological milestones, whereas 年代 specifies numerical decades or archaeological centuries (如八十年代, 年代久远)."}, {"id": "3", "compared_word": "时代 vs. 岁月", "pinyin": "suìyuè", "analysis": "时代 carries objective socio-historical weight, whereas 岁月 carries subjective, emotional, and poetic nostalgia for passing years (难忘的岁月)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "时", "pinyin": "shí", "meaning_en": "time; era", "distinction_note": "Has 日 (sun) on the left and 寸 on the right"}, {"character": "村", "pinyin": "cūn", "meaning_en": "village", "distinction_note": "Has 木 (wood) on the left with 寸"}, {"character": "代", "pinyin": "dài", "meaning_en": "era; replace", "distinction_note": "Has 亻 on the left and 弋 on the right"}, {"character": "伐", "pinyin": "fá", "meaning_en": "chop; cut down", "distinction_note": "Has 亻 on the left and 戈 (halberd) on the right"}], "etymological_cognates": [{"character": "时间", "pinyin": "shí jiān", "gloss_en": "time; duration"}, {"character": "时期", "pinyin": "shí qī", "gloss_en": "period; stage"}, {"character": "代表", "pinyin": "dài biǎo", "gloss_en": "represent; representative"}, {"character": "年代", "pinyin": "nián dài", "gloss_en": "decade; time period; age"}]}, "id": "38", "hanzi": "时代", "pinyin": "shí dài", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a broad historical period distinguished by prominent social, technological, or political features", "definition_es": "gran período histórico caracterizado por rasgos sociales o técnicos propios", "example_phrase": "互联网时代 (the internet age / digital era)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a specific stage or phase in an individual's life (youth, student days)", "definition_es": "etapa o período concreto de la vida de una persona", "example_phrase": "学生时代 (student days)"}], "example_sentences": [{"id": "#1", "hanzi": "在这个提倡个性与多元价值的新时代，越来越多的人敢于打破传统框架，勇敢追逐属于自己的航海梦想。", "pinyin": "Zài zhè gè tíchàng gèxìng yǔ duōyuán jiàzhí de xīn shídài, yuèláiyuè duō de rén gǎnyú dǎpò chuántǒng kuàngjià, yǒnggǎn zhuīzhú shǔyú zìjǐ de hánghǎi mèngxiǎng.", "en": "In this new era championing individuality and pluralism, more people dare break traditional molds to chase ocean dreams.", "es": "En esta nueva era que celebra la diversidad y la iniciativa individual, cada vez más personas rompen moldes para perseguir sus sueños marineros."}, {"id": "#2", "hanzi": "人工智能算法的跨越式突破正在推动整个人类文明由信息化社会全面迈向数智化时代。", "pinyin": "Réngōng zhìnéng suànfǎ de kuàyuèshì tūpò zhèngzài tuīdòng zhěnggè rénlèi wénmíng yóu xìnxīhuà shèhuì quánmiàn màixiàng shùzhìhuà shídài.", "en": "Leapfrog breakthroughs in artificial intelligence algorithms are driving human civilization from information society into the intelligent era.", "es": "Los avances decisivos en inteligencia artificial impulsan a la civilización desde la sociedad de la información hacia la era de la inteligencia digital."}], "collocations": [{"hanzi": "新时代", "en": "new era"}, {"hanzi": "学生时代", "en": "student days"}, {"hanzi": "信息时代", "en": "information age"}, {"hanzi": "时代发展", "en": "development of the era"}, {"hanzi": "走在时代前列", "en": "march at the forefront of the times"}, {"hanzi": "时代的产物", "en": "product of the times"}], "idioms": [{"hanzi": "与时俱进", "pinyin": "yǔ shí jù jìn", "meaning_en": "keep pace with the times; advance with history"}, {"hanzi": "应运而生", "pinyin": "yìng yùn ér shēng", "meaning_en": "emerge as the times require; arise at the opportune moment"}, {"hanzi": "风起云涌", "pinyin": "fēng qǐ yún yǒng", "meaning_en": "like rising winds and scudding clouds; gathering momentum"}, {"hanzi": "继往开来", "pinyin": "jì wǎng kāi lái", "meaning_en": "carry forward the heritage and open up the future"}], "character_decomposition": [{"character": "时", "pinyin": "shí", "meaning_en": "time; season; era", "meaning_es": "tiempo; hora; época", "radical": "日", "radical_meaning_en": "sun / day", "meaning_component": "日 (sun tracking the passage of daylight)", "sound_component": "寸 (cùn phonetic / measuring ruler)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogrammic compound: measuring the sun's trajectory (日) with a ruler (寸) to track the passing hours and seasons.", "visual_mnemonic_story_en": "The golden sun (日) casting its measured inch of shadow (寸) as epochs and seasons unfold.", "visual_mnemonic_story_es": "El sol dorado (日) proyectando una pulgada de sombra (寸) conforme maduran los siglos y las estaciones.", "tone_mnemonic_anchor": "35", "cangjie": "ADI", "traditional": "時"}, {"character": "代", "pinyin": "dài", "meaning_en": "generation; era; replace", "meaning_es": "generación; época; sustituir", "radical": "亻", "radical_meaning_en": "person / human", "meaning_component": "亻 (generations of humans passing the torch)", "sound_component": "弋 (yì phonetic / stake or shooting arrow)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogrammic/phono-semantic compound: one generation of humans (亻) replacing another like marked stakes (弋) on a trail.", "visual_mnemonic_story_en": "A new generation of human pioneers (亻) taking the relay stake (弋) to lead humanity forward into a fresh era.", "visual_mnemonic_story_es": "Una nueva generación (亻) que toma el relevo (弋) para guiar a la comunidad hacia una nueva era.", "tone_mnemonic_anchor": "51", "cangjie": "OIP", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "每一个时代都会留下属于自己的独特印记。身处滚滚向前的历史洪流中，我们既是时代的见证者，也是时代的塑造者。唯有勇敢回应时代提出的命题，在风云变幻中坚定心中的理想，才能活出生命的辽阔与尊严。", "pinyin": "Měi yí gè shídài dōu huì liúxià shǔyú zìjǐ de dútè yìnjì. Shēnchǔ gǔngǔn xiàngqián de lìshǐ hóngliú zhōng, wǒmen jì shì shídài de jiànzhèngzhě, yě shì shídài de shùzàozhě. Wéiyǒu yǒnggǎn huìyìng shídài tíchū de mìngtí, zài fēngyún biànhuàn zhōng jiāndìng xīnzhōng de lǐxiǎng, cáinéng huó chū shēngmìng de liáokuò yǔ zūnyán.", "en": "Every era imprints its unique signature. In the rushing current of history, we are both witnesses and shapers of our time. Responding boldly to epochal questions and holding ideals firm realizes life's grandeur and dignity.", "es": "Cada época deja su propia impronta. En el caudal imparable de la historia somos tanto testigos como artífices de nuestro tiempo. Responder con audacia a sus desafíos y afianzar los ideales dignifica la existencia humana."}, {"id": "#2", "hanzi": "全球数字经济的高速发展标志着人类社会正式步入算力时代。数据作为新型核心生产要素，正在深度重塑传统工业生产与社会治理逻辑。牢牢把握时代科技创新主动权，推动数字技术与实体经济深度融合，是抢占未来国际竞争制高点的核心引擎。", "pinyin": "Quánqiú shùzì jīngjì de gāosù fāzhǎn biāozhì zhe rénlèi shèhuì zhèngshì bùrù suànlì shídài. Shùjù zuòwéi xīnxíng héxīn shēngchǎn yàosù, zhèngzài shēndù chóngshù chuántǒng gōngyè shēngchǎn yǔ shèhuì zhìlǐ luójí. Láoláo bǎwò shídài kējì chuàngxīn zhǔdòngquán, tuīdòng shùzì jìshù yǔ shítǐ jīngjì shēndù rónghé, shì qiǎngzhàn wèilái guójì jìngzhēng zhìgāodiǎn de héxīn yǐnqíng.", "en": "The rise of the global digital economy marks humanity's formal entry into the computing era. As a core factor of production, data reshapes manufacturing and governance. Mastering technological sovereignty and fusing digital tools with industry powers competitiveness.", "es": "El despegue de la economía digital sitúa a la humanidad en la era del procesamiento masivo de datos. Como factor productivo clave, el dato revoluciona la industria y la gobernanza. Liderar la innovación tecnológica blinda la soberanía en la escena internacional."}]}, {"meanings_summary": {"en": "lightning; lightning flash; electric flash in storm", "es": "relámpago; rayo; destello eléctrico; fulgor"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A person darting through a doorway in a flash (闪) combined with atmospheric electricity (电) creates brilliant lightning (闪电).", "composite_memory_hook_es": "Un destello fugaz (闪) junto a la descarga eléctrica del cielo (电) alumbra el potente relámpago (闪电).", "cultural_and_cognitive_roots": "In ancient Chinese mythology, the Lightning Mother ('电母') wielded twin bronze mirrors that flashed across the skies to illuminate guilt and illuminate righteous retribution alongside the Thunder God ('雷公').", "tone_sandhi_and_pitch_modulation": "Dipping 3rd tone followed by a falling 4th tone: shǎn diàn (214-51). Dip 'shǎn' smoothly into lower vocal pitch before delivering 'diàn' firmly downward."}, "semantic_boundary_contrasts": {"core_nuance": "闪电 specifically denotes the visual optical streak of atmospheric electrical discharge during a storm.", "contrasts": [{"id": "1", "compared_word": "闪电 vs. 雷", "pinyin": "léi", "analysis": "闪电 is the visible optical flash of light, whereas 雷 is the audible acoustic rumble and sonic boom caused by atmospheric expansion."}, {"id": "2", "compared_word": "闪电 vs. 光芒", "pinyin": "guāngmáng", "analysis": "闪电 is an episodic natural meteorological electrical discharge, whereas 光芒 refers broadly to steady or radiant rays of illumination from the sun, stars, or gold."}, {"id": "3", "compared_word": "闪电 vs. 火花", "pinyin": "huǒhuā", "analysis": "闪电 is a massive atmospheric storm phenomenon, whereas 火花 refers to small physical sparks flying from friction, welding, or hearths."}]}, "traps_and_cognates": {"look_alikes": [{"character": "闪", "pinyin": "shǎn", "meaning_en": "flash; dodge", "distinction_note": "Has 门 (door) enclosing 人 (person)"}, {"character": "问", "pinyin": "wèn", "meaning_en": "ask; inquire", "distinction_note": "Has 门 enclosing 口 (mouth)"}, {"character": "电", "pinyin": "diàn", "meaning_en": "electricity; lightning", "distinction_note": "Five strokes with a curved right tail"}, {"character": "申", "pinyin": "shēn", "meaning_en": "express; extend", "distinction_note": "Has vertical stroke piercing through both top and bottom"}], "etymological_cognates": [{"character": "闪烁", "pinyin": "shǎn shuò", "gloss_en": "flicker; twinkle; shimmer"}, {"character": "闪开", "pinyin": "shǎn kāi", "gloss_en": "dodge; get out of the way"}, {"character": "电脑", "pinyin": "diàn nǎo", "gloss_en": "computer"}, {"character": "电话", "pinyin": "diàn huà", "gloss_en": "telephone; phone call"}]}, "id": "39", "hanzi": "闪电", "pinyin": "shǎn diàn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a visible electrical discharge occurring within a cloud or between cloud and ground", "definition_es": "descarga eléctrica natural visible entre nubes o entre nube y tierra; relámpago", "example_phrase": "一道闪电 (a flash of lightning)"}], "example_sentences": [{"id": "#1", "hanzi": "漆黑的夜海中突然划过一道耀眼的闪电，将汹涌翻滚的巨浪照得雪亮，随即传来了沉闷的雷声。", "pinyin": "Qīhēi de yèhǎi zhōng tūrán huàguò yí dào yàoyǎn de shǎndiàn, jiāng xiōngyǒng fāngǔn de jùlàng zhào de xuěliàng, suíjí chuánlái le chénmèn de léishēng.", "en": "A blinding flash of lightning ripped through the inky sea, illuminating churning swells snow-white before thunder crashed.", "es": "Un relámpago cegador rasgó la noche marina, iluminando las olas encrespadas con blancura de nieve antes de resonar el trueno."}, {"id": "#2", "hanzi": "气象科研团队部署了地面三维闪电定位网，实现了对强对流天气中雷击灾害的毫秒级高精度实时追踪。", "pinyin": "Qìxiàng kēyán tuánduì bùshǔ le dìmiàn sānwéi shǎndiàn dìngwèiwǎng, shíxiàn le duì qiáng duìliú tiānqì zhōng léijī zāihài de háomiǎojí gāojīngdù shíshí zhuīzōng.", "en": "The meteorological team deployed a ground 3D lightning location network, enabling millisecond tracking of strikes during convective storms.", "es": "El equipo meteorológico desplegó una red tridimensional de detección de rayos, rastreando en milisegundos las descargas en tormentas severas."}], "collocations": [{"hanzi": "一道闪电", "en": "a flash of lightning"}, {"hanzi": "闪电般的速度", "en": "lightning speed; lightning fast"}, {"hanzi": "闪电战", "en": "blitzkrieg; lightning war"}, {"hanzi": "闪电交加", "en": "lightning flashes interlaced with thunder"}, {"hanzi": "划破夜空的闪电", "en": "lightning tearing through the night sky"}, {"hanzi": "闪电光芒", "en": "flash / glow of lightning"}], "idioms": [{"hanzi": "电闪雷鸣", "pinyin": "diàn shǎn léi míng", "meaning_en": "lightning flashes and thunder rumbles; severe thunderstorm"}, {"hanzi": "雷厉风行", "pinyin": "léi lì fēng xíng", "meaning_en": "swift as thunder and speedy as wind; enforce strictly and vigorously"}, {"hanzi": "吉光片羽", "pinyin": "jí guāng piàn yǔ", "meaning_en": "precious fragment of a mythological beast; rare artistic relics"}, {"hanzi": "风驰电掣", "pinyin": "fēng chí diàn chè", "meaning_en": "swift as the wind and quick as lightning; traveling at immense speed"}], "character_decomposition": [{"character": "闪", "pinyin": "shǎn", "meaning_en": "flash; dodge; lightning", "meaning_es": "destello; esquivar; relampaguear", "radical": "门", "radical_meaning_en": "gate / door", "meaning_component": "门 (double door leaf)", "sound_component": "人 (human slipping through door instantly)", "stroke_count": "5", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ideogrammic compound: a person (人) darting swiftly through an open doorway (门) like a flash of light.", "visual_mnemonic_story_en": "A person (人) slipping swiftly through a doorway (门) like a momentary flicker of bright light.", "visual_mnemonic_story_es": "Una persona (人) que cruza como un suspiro por el quicio de la puerta (门), veloz como un destello.", "tone_mnemonic_anchor": "214", "cangjie": "ANOR", "traditional": "閃"}, {"character": "电", "pinyin": "diàn", "meaning_en": "electricity; lightning; telegram", "meaning_es": "electricidad; rayo; telégrafo", "radical": "田 / 申", "radical_meaning_en": "field / lightning flash", "meaning_component": "雨 (ancient rain cloud)", "sound_component": "申 (zigzag lightning bolt streaking from sky)", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of an atmospheric lightning bolt zig-zagging downward from rainclouds to the earth.", "visual_mnemonic_story_en": "A jagged lightning strike (电) zig-zagging across storm clouds to deliver electric energy.", "visual_mnemonic_story_es": "Un rayo zigzagueante (电) que cruza el cielo nublado descargando una tremenda corriente eléctrica.", "tone_mnemonic_anchor": "51", "cangjie": "LWU", "traditional": "電"}], "extended_reading_passages": [{"id": "#1", "hanzi": "狂暴的风雨夜，闪电如利剑般一次次劈开苍穹，照亮了怒涛汹涌的海面。短暂的光芒虽只有一瞬，却让迷茫的水手看清了暗礁与航向。生命中的灵感往往如同闪电，唯有时刻做好准备的人，才能捕捉到那穿透迷雾的顿悟。", "pinyin": "Kuángbào de fēngyǔ yè, shǎndiàn rú lìjiàn bān yícìcì pīkāi cāngqióng, zhàoliàng le nùtāo xiōngyǒng de hǎimiàn. Duǎnzàn de guāngmáng suī zhǐyǒu yí shùn, què ràng mímáng de shuǐshǒu kàn qīng le ànjiāo yǔ hángxiàng. Shēngmìng zhōng de línggǎn wǎngwǎng rútóng shǎndiàn, wéiyǒu shíkè zuò hǎo zhǔnbèi de rén, cáinéng bǔzhuō dào nà chuāntòu míwù de dùnwù.", "en": "On tempestuous nights, lightning slashes heaven like blades, illuminating raging crests. Fleeting light lasts an instant, yet reveals reefs and course. Inspiration resembles lightning; only minds prepared seize insight piercing gloom.", "es": "En la noche tempestuosa, los rayos rasgan el cielo como espadas iluminando el mar furioso. Su fulgor dura un instante, mas basta para revelar arrecifes y rumbo. La inspiración asemeja al relámpago: solo quien está alerta atrapa la claridad que rasga la niebla."}, {"id": "#2", "hanzi": "物理观测表明，强对流云团中粒子碰撞引发电荷分离，当电场击穿空气时便产生耀眼的闪电。现代气象雷达能精准捕捉闪电频次，为极端暴雨预警与航空防雷提供了关键的数据支撑。", "pinyin": "Wùlǐ guāncè biǎomíng, qiáng duìliú yúntuán zhōng lìzǐ pèngzhuàng yǐnfā diànhè fēnlí, dāng diànchǎng jīchuān kōngqì shí biàn chǎnshēng yàoyǎn de shǎndiàn. Xiàndài qìxiàng léidá néng jīngzhǔn bǔzhuō shǎndiàn píncì, wèi jíduān bàoyǔ yùjǐng yǔ hángkōng fángléi tígōng le guānjiàn de shùjù zhīchēng.", "en": "Observations confirm particle collisions in clouds prompt charge separation, sparking brilliant lightning. Modern radar tracks strike frequencies, providing key data for severe storm warnings and aviation safety.", "es": "La observación física confirma que el choque de partículas en las nubes separa cargas y desata el rayo. Los radares rastrean las descargas, aportando datos clave para alertas de tormentas severas y seguridad aérea."}]}, {"meanings_summary": {"en": "thunder; mine (weapon); shocking; astonishing", "es": "trueno; mina (artefacto explosivo); atronador; desconcertante"}, "mnemonics_and_roots": {"composite_memory_hook_en": "When heavy rain clouds (雨) shake open fields (田) with sonic rumbles, mighty thunder echoes (雷).", "composite_memory_hook_es": "Cuando las nubes de lluvia (雨) hacen temblar los campos de cultivo (田) con estruendo, retumba el potente trueno (雷).", "cultural_and_cognitive_roots": "In ancient Chinese mythology, the Thunder Duke ('雷公') punished the wicked and awakened the dormant soil during the Awakening of Insects ('惊蛰'), making thunder an emblem of cosmic justice and vernal rebirth.", "tone_sandhi_and_pitch_modulation": "Rising 2nd tone: léi (35). Elevate the vocal contour smoothly from pitch 3 to 5 with full resonating breath."}, "semantic_boundary_contrasts": {"core_nuance": "雷 denotes the acoustic shockwave and rumble of atmospheric discharge, or explosive mine ordnance.", "contrasts": [{"id": "1", "compared_word": "雷 vs. 电", "pinyin": "diàn", "analysis": "雷 is the audible sound wave of thunder (打雷, 听见雷声), whereas 电 is the visible optical streak of lightning or electrical energy."}, {"id": "2", "compared_word": "雷 vs. 轰鸣", "pinyin": "hōngmíng", "analysis": "雷 refers specifically to meteorological thunder or weapon mines, while 轰鸣 is an onomatopoeic noun describing continuous roaring engines, machines, or waterfalls."}, {"id": "3", "compared_word": "雷 vs. 爆", "pinyin": "bào", "analysis": "雷 produces acoustic booms from atmospheric plasma or buried ordnance, whereas 爆 indicates physical detonation, exploding, or bursting outward."}]}, "traps_and_cognates": {"look_alikes": [{"character": "雷", "pinyin": "léi", "meaning_en": "thunder; mine", "distinction_note": "Has 雨 on top and 田 at the bottom"}, {"character": "雪", "pinyin": "xuě", "meaning_en": "snow", "distinction_note": "Has 雨 on top and 彐 at the bottom"}, {"character": "震", "pinyin": "zhèn", "meaning_en": "quake; shock", "distinction_note": "Has 雨 on top and 辰 at the bottom"}, {"character": "霜", "pinyin": "shuāng", "meaning_en": "frost", "distinction_note": "Has 雨 on top and 相 at the bottom"}], "etymological_cognates": [{"character": "雷电", "pinyin": "léi diàn", "gloss_en": "thunder and lightning"}, {"character": "雷鸣", "pinyin": "léi míng", "gloss_en": "thunder roll; rumble of thunder"}, {"character": "雷暴", "pinyin": "léi bào", "gloss_en": "thunderstorm"}, {"character": "扫雷", "pinyin": "sǎo léi", "gloss_en": "minesweeping; clear mines"}]}, "id": "40", "hanzi": "雷", "pinyin": "léi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the loud acoustic rumble or crash caused by lightning heating the air", "definition_es": "estruendo acústico producido en las nubes por una descarga eléctrica; trueno", "example_phrase": "打雷 (thunder rumbling)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "explosive military mine (landmine, naval mine)", "definition_es": "artefacto explosivo bélico (mina terrestre o submarina)", "example_phrase": "水雷 (naval mine)"}], "example_sentences": [{"id": "#1", "hanzi": "滚滚春雷在天边轰鸣炸响，惊醒了沉睡的大地，宣告着漫长冬季的终结与生机盎然的春天来临。", "pinyin": "Gǔngǔn chūnléi zài tiānbiān hōngmíng zhàxiǎng, jīngxǐng le chénsùi de dàdì, xuāngào zhe màncháng dōngjì de zhōngjié yǔ shēngjī'àngrán de chūntiān láilín.", "en": "Rolling spring thunder boomed along the horizon, awakening the sleeping earth and heralding the end of winter and the dawn of vibrant spring.", "es": "El retumbar del trueno primaveral estalló en el confín despertando a la tierra dormida, proclamando el fin del invierno y la llegada de la primavera."}, {"id": "#2", "hanzi": "海军扫雷艇编队在复杂海况下展开实战化演练，利用水下声呐设备成功排除多枚潜伏的水雷。", "pinyin": "Hǎijūn sǎoléitǐng biānduì zài fùzá hǎikuàng xià zhǎnkāi shízhànhuà yǎnliàn, lìyòng shuǐxià shēngnà shèbèi chénggōng páichú duō méi qiánfú de shuǐléi.", "en": "The naval minesweeper flotilla staged combat drills, using sonar gear to detect and neutralize several submerged naval mines.", "es": "La flotilla de dragaminas realizó maniobras tácticas en alta mar, empleando sonares para localizar y neutralizar minas submarinas."}], "collocations": [{"hanzi": "打雷", "en": "thunder rumbles / strikes"}, {"hanzi": "雷声", "en": "sound of thunder; thunderclap"}, {"hanzi": "雷雨", "en": "thunderstorm"}, {"hanzi": "水雷", "en": "naval mine"}, {"hanzi": "地雷", "en": "landmine"}, {"hanzi": "雷达", "en": "radar"}], "idioms": [{"hanzi": "雷厉风行", "pinyin": "léi lì fēng xíng", "meaning_en": "swift as thunder and speedy as wind; enforce rules vigorously"}, {"hanzi": "雷霆万钧", "pinyin": "léi tíng wàn jūn", "meaning_en": "with thunderous force and crushing momentum"}, {"hanzi": "平地惊雷", "pinyin": "píng dì jīng léi", "meaning_en": "sudden thunderclap from a clear sky; shocking sudden news"}, {"hanzi": "电闪雷鸣", "pinyin": "diàn shǎn léi míng", "meaning_en": "lightning flashes and thunder rolls; furious thunderstorm"}], "character_decomposition": [{"character": "雷", "pinyin": "léi", "meaning_en": "thunder; mine", "meaning_es": "trueno; mina", "radical": "雨", "radical_meaning_en": "rain", "meaning_component": "雨 (rain clouds)", "sound_component": "田 (tián / spinning rolling wheels or drum rumbles)", "stroke_count": "13", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient pictograph: rain clouds (雨) discharging sonic booms echoing across cultivated valley fields (田) like spinning chariot wheels.", "visual_mnemonic_story_en": "Rain clouds (雨) bursting open over agricultural fields (田) with an earth-shaking acoustic thunderclap.", "visual_mnemonic_story_es": "Nubes de lluvia torrencial (雨) que descargan sobre los campos de labor (田) con un estruendoso trueno.", "tone_mnemonic_anchor": "35", "cangjie": "MBW", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "滚滚的春雷总是在初春的深夜悄然炸响。那一阵阵低沉而有力的轰鸣，仿佛是大自然伸出的巨手，叩开了沉睡一冬的草木冻土。万物在雷声的召唤下破土发芽，生命在此刻完成了从蛰伏到蓬勃的庄严更迭。", "pinyin": "Gǔngǔn de chūnléi zǒngshì zài chūchūn de shēnyè qiǎorán zhàxiǎng. Nà yízhènzhèn dīchén ér yǒulì de hōngmíng, fǎngfú shì dàzìrán shēnchū de jùshǒu, kòukāi le chénsùi yì dōng de cǎomù dòngtǔ. Wànwù zài léishēng de zhàohuàn xià pòtǔ fāyá, shēngmìng zài cǐkè wánchéng le cóng zhéfú dào péngbó de zhuāngyán gēngdié.", "en": "Rolling spring thunder detonates in the depths of early spring nights. Deep, pulsing rumbles seem like nature's giant palm knocking open frozen loam. Under thunder's summons, all green bursts forth, turning dormancy into vigorous life.", "es": "El trueno primaveral estalla en el silencio de la noche temprana. Su rumor hondo es como la mano de la naturaleza abriendo la tierra helada. Al eco del trueno brotan las semillas, cumpliendo el tránsito sagrado del letargo a la vida plena."}, {"id": "#2", "hanzi": "气象研究表明，强雷暴云团的形成与近地面垂直风切变密切相关。剧烈对流激发的雷电活动往往伴随短时强降水与大风。提升多普勒雷达监测精度，是防范雷击灾害与保障航线安全的重要举措。", "pinyin": "Qìxiàng yánjiū biǎomíng, qiáng léibào yúntuán de xíngchéng yǔ jìndìmiàn chuízhí fēngqiēbiàn mìqiè xiāngguān. Jùliè duìliú jīfā de léidiàn huódòng wǎngwǎng bànsuí duǎnshí qiáng jiàngshuǐ yǔ dàfēng. Tíshēng Duōpǔlēi léidá jiānkòng jīngdù, shì fángfàn léijī zāihài yǔ bǎozhàng hángxiàn ānquán de zhòngyào jǔcuò.", "en": "Meteorology reveals storm clouds link closely with wind shear. Violent convective lightning triggers flash downpours and gales. Upgrading Doppler radar accuracy remains crucial for lightning prevention and flight safety.", "es": "La meteorología vincula las tormentas con la cizalladura del viento. Los truenos acarrean aguaceros torrenciales y vendavales. Mejorar la precisión del radar Doppler es decisivo para prevenir rayos y blindar las aerovías."}]}];
